import sys

def print_file(path, name):
    try:
        with open(path + '/' + name, 'r') as f:
            content = f.read()
        # Find the first line that indicates __file__
        for line in content.split('\n'):
            stripped = line.strip()
            if '__file__' in stripped and '=' in stripped:
                # Extract the path from the assignment
                parts = stripped.split('=', 1)
                val = parts[1].strip()
                # Remove quotes
                if val.startswith("'") and val.endswith("'"):
                    val = val[1:-1]
                elif val.startswith('"') and val.endswith('"'):
                    val = val[1:-1]
                print(val)
                return True
    except FileNotFoundError:
        pass
    return False

