def _walk(root):
    stack = [root]
    while stack:
        d = stack.pop()
        try:
            entries = sorted(os.listdir(d))
        except OSError:
            continue
        for name in entries:
            path = os.path.join(d, name)
            if os.path.isdir(path):
                stack.append(path)
            elif name.endswith(".jsonl"):
                yield path


