def find_jsonl_files(base):
    """Recursively find all .jsonl files under base, returning a sorted list."""
    result = []
    try:
        entries = os.listdir(base)
    except OSError:
        return result
    for name in entries:
        full = os.path.join(base, name)
        if os.path.isdir(full):
            result.extend(find_jsonl_files(full))
        elif os.path.isfile(full) and name.endswith(".jsonl"):
            result.append(full)
    return sorted(result)


