import random

# Replicate lypning's conformance module logic locally (no class definitions)
def _get_ast(program):
    import ast
    return ast.parse(program)

def is_seeded_stream(e):
    """Check if the program seeds a random stream"""
    import ast
    # Look for: random.seed, Random(seed), rng.seed, etc.
    try:
        tree = _get_ast(e.program)
    except Exception:
        return False
    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            func = node.func
            # Check for seed() calls on random or Random instances
            if isinstance(func, ast.Attribute) and func.attr == 'seed':
                # Check if it's random.seed or some rng.seed
                return True
            # Check for Random(seed_value) constructor with explicit seed
            elif isinstance(func, ast.Name) and func.id == 'Random':
                if len(node.args) > 0:
                    return True
    return False

def is_run_specific(e):
    """Check if the program has deterministic output (seeded or no randomness)"""
    import ast
    try:
        tree = _get_ast(e.program)
    except Exception:
        return False

    # If seeded, it's run-specific (deterministic)
    if is_seeded_stream(e):
        return True

    # Check if there's any use of random without seeding
    uses_random = False
    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            func = node.func
            if isinstance(func, ast.Attribute):
                value = func.value
                if isinstance(value, ast.Name) and value.id in ('random', 'r'):
                    uses_random = True
                elif isinstance(value, ast.Attribute) and value.attr in ('Random', 'random'):
                    uses_random = True
        elif isinstance(node, ast.Attribute):
            value = node.value
            if isinstance(value, ast.Name) and value.id in ('random', 'r') and node.attr != 'seed':
                # Access to random.something that could be a function call context
                pass

    if not uses_random:
        return True

    # If uses random but not seeded, check if it could be nondeterministic
    # For simplicity: if seeded -> run_specific=True, if unseeded but uses random -> need deeper analysis
    # The original lypning likely considers unseeded random as nondeterministic
    return False

def is_nondeterministic(e):
    """Check if the program could produce different outputs across runs"""
    import ast
    try:
        tree = _get_ast(e.program)
    except Exception:
        return False

    if is_seeded_stream(e):
        return False

    # Uses random without seeding
    uses_random_unseeded = False
    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            func = node.func
            if isinstance(func, ast.Attribute) and func.attr in ('random', 'randint', 'choice', 'shuffle', 'uniform', 'rand', 'sample', 'triangular', 'expovariate', 'gamma', 'betavariate', 'normalvariate', 'lognormvariate', 'gumbel', 'vonmisesvariate', 'paretovariate', 'weibullvariate', 'choices'):
                value = func.value
                if isinstance(value, ast.Name) and value.id in ('random', 'r'):
                    uses_random_unseeded = True
                elif isinstance(value, ast.Attribute):
                    uses_random_unseeded = True

    return uses_random_unseeded


