def _decode_string_escapes(s):
    result = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] == '\\' and i + 1 < n:
            nxt = s[i + 1]
            if nxt == 'n':
                result.append('\n')
            elif nxt == 't':
                result.append('\t')
            elif nxt == 'r':
                result.append('\r')
            elif nxt == '"':
                result.append('"')
            elif nxt == '\\':
                result.append('\\')
            elif nxt == '/':
                result.append('/')
            elif nxt == 'b':
                result.append('\b')
            elif nxt == 'f':
                result.append('\f')
            elif nxt == 'u' and i + 5 < n + 1:
                hexstr = s[i + 2:i + 6]
                if len(hexstr) == 4:
                    try:
                        code = int(hexstr, 16)
                        result.append(chr(code))
                    except Exception:
                        result.append('u')
                    i += 6
                    continue
                else:
                    result.append('\\u')
                    i += 2
                    continue
            else:
                result.append('\\')
                result.append(nxt)
            i += 2
            continue
        result.append(s[i])
        i += 1
    return ''.join(result)


