def _fmt_str(s, spec):
    """Handle string formatting specifiers."""
    # String format specs: [fill][align][sign][#][0][width][.prec][type]
    # For strings, valid types are 's', 'r', or empty

    # Parse the spec
    fill = ''
    align = ''
    width = 0
    precision = None
    typ = ''

    i = 0
    n = len(spec)

    # Check for fill+align (first char is fill, second is align)
    if n >= 2 and spec[1] in '<>=^':
        fill = spec[0]
        align = spec[1]
        i = 2
    elif n >= 1 and spec[0] in '<>=^':
        align = spec[0]
        i = 1

    # Width
    while i < n and spec[i].isdigit():
        i += 1

    if i < n and spec[i] == '.':
        # Precision
        prec_start = i + 1
        j = prec_start
        while j < n and spec[j].isdigit():
            j += 1
        precision = int(spec[prec_start:j]) if j > prec_start else 0
        i = j

    # Type
    if i < n:
        typ = spec[i:]

    if typ not in ('', 's', 'r'):
        raise ValueError(f"Invalid format specification for str: {spec!r}")

    # Apply precision
    if precision is not None:
        s = s[:precision]

    # Apply padding based on align
    if width > 0 and len(s) < width:
        pad_len = width - len(s)
        if not align:
            # Default: right-align for numeric, but for strings it's left? 
            # Actually, for strings default alignment is left (<)
            # Wait, actually Python defaults to no alignment which means...
            # Let me check: for strings, default is left align
            if fill:
                s = s + fill * pad_len
            else:
                s = s + ' ' * pad_len
        elif align == '<':
            s = s + (fill if fill else ' ') * pad_len
        elif align == '>':
            s = (fill if fill else ' ') * pad_len + s
        elif align == '^':
            left_pad = pad_len // 2
            right_pad = pad_len - left_pad
