def _eval_expr(expr):
    """Safely evaluate a simple expression without using eval."""
    # Parse the expression
    tree = parse(expr, mode='eval')

    def _node_to_value(node):
        from ast import BinOp, UnaryOp, Name, Num, Str, List, Tuple, Dict, NameConstant, Ellipsis, BoolOp, Operator
        if isinstance(node, NameConstant):
            return node.value
        elif isinstance(node, Name):
            name = node.id
            # Look up in globals - for our purposes, names are 're', 'len', 'str', 'int', etc.
            # We'll handle these specially
            return name  # return the name as a string, we'll handle it in evaluation
        elif isinstance(node, (Num,)):
            return node.n
        elif isinstance(node, Str):
            return node.s
        elif isinstance(node, List):
            return [_node_to_value(e) for e in node.elts]
        elif isinstance(node, Tuple):
            return tuple(_node_to_value(e) for e in node.elts)
        elif isinstance(node, BinOp):
            left = _node_to_value(node.left)
            right = _node_to_value(node.right)
            op = type(node.op).__name__
            if op == 'Add':
                return left + right
            elif op == 'Sub':
                return left - right
            elif op == 'Mult':
                return left * right
            elif op == 'Div':
                return left / right
            elif op == 'FloorDiv':
                return left // right
            elif op == 'Mod':
                return left % right
            elif op == 'Pow':
                return left ** right
            elif op == 'BitAnd':
                return left & right
            elif op == 'BitOr':
                return left | right
            elif op == 'BitXor':
                return left ^ node
            elif op == 'LShift':
                return left << right
            elif op == 'RShift':
                return left >> right
            else:
                raise ValueError("Unsupported operator: " + op)
        elif isinstance(node, UnaryOp):
            operand = _node_to_value(node.operand)
            op = type(node.op).__name__
            if op == 'USub':
                return -operand
            elif op == 'UAdd':
                return +operand
            elif op == 'Invert':
                return ~operand
            else:
                raise ValueError("Unsupported unary op: " + op)
        else:
            raise ValueError("Unsupported AST node: " + str(type(node)))

    # For simplicity, let's just use a direct approach since our expressions are simple
    # They all call re.findall or len(re.findall(...))
    # Let's parse and handle specific patterns

    stripped = expr.strip()

    # Pattern: re.findall('pattern', 'string', flags)
    # Pattern: len(re.findall('pattern', 'string'))
    # Pattern: len(re.findall('pattern', 'string', flags))

    try:
        # Try to match re.findall at top level
        if stripped.startswith('re.findall'):
            # Find the three arguments
            args = _parse_args(stripped[len('re.findall'):])
            if len(args) == 2:
                pattern_str, string_str = args[0], args[1]
                return re.findall(pattern_str, string_str)
            elif len(args) == 3:
                pattern_str, string_str, flags_val = args[0], args[1], args[2]
                if flags_val == 're.I':
                    return re.findall(pattern_str, string_str, re.I)
                else:
                    return re.findall(pattern_str, string_str, flags_val)
        elif stripped.startswith('len(') and 're.findall' in stripped:
            inner = stripped[4:-1].strip()
            result = _eval_expr(inner)
            return len(result)
        else:
            raise ValueError("Cannot handle expression: " + expr)
    except Exception as e:
        raise e

def _parse_args(s):
    """Parse function arguments from a string like '(a, b, c)'"""
    s = s.strip()
    if not s.startswith('(') or not s.endswith(')'):
        raise ValueError("Expected parenthesized arguments")
    s = s[1:-1]
    args = []
    i = 0
    while i < len(s):
        # Skip whitespace
        while i < len(s) and s[i] in ' \t\n':
            i += 1
        if i >= len(s):
            break
        # Check for quote
        if s[i] in "'\"":
            quote = s[i]
            i += 1
            start = i
            while i < len(s) and s[i] != quote:
                if s[i] == '\\':
                    i += 1
                i += 1
            # s[i] should be quote
            arg_str = s[start:i]
            # Decode escapes
            if quote == "'":
                # Handle Python string escapes
                decoded = _decode_string(arg_str, "'")
            else:
                decoded = _decode_string(arg_str, '"')
            args.append(decoded)
            i += 1  # skip closing quote
        else:
            # Not a quoted string - must be something like re.I
            j = i
            while j < len(s) and s[j] != ',' and s[j] not in ' \t\n':
                j += 1
            token = s[i:j]
            args.append(token)
            i = j
        # Skip comma
        while i < len(s) and s[i] in ' \t\n':
            i += 1
        if i < len(s) and s[i] == ',':
            i += 1
    return args

def _decode_string(s, quote):
    """Decode a Python string with escapes"""
    result = []
    i = 0
    while i < len(s):
        if s[i] == '\\' and i + 1 < len(s):
            nxt = s[i+1]
            if nxt == 'n':
                result.append('\n')
                i += 2
            elif nxt == 't':
                result.append('\t')
                i += 2
            elif nxt == 'r':
                result.append('\r')
                i += 2
            elif nxt == 'f':
                result.append('\f')
                i += 2
            elif nxt == 'v':
                result.append('\v')
                i += 2
            elif nxt == 'b':
                result.append('\b')
                i += 2
            elif nxt == 'a':
                result.append('\a')
                i += 2
            elif nxt == '\\':
                result.append('\\')
                i += 2
            elif nxt == "'":
                result.append("'")
                i += 2
            elif nxt == '"':
                result.append('"')
                i += 2
            elif nxt == 'x':
                # hex escape
                if i + 3 < len(s):
                    hex_code = s[i+2:i+4]
                    result.append(chr(int(hex_code, 16)))
                    i += 4
                else:
                    result.append(s[i])
                    i += 1
            elif nxt == 'u':
                if i + 5 < len(s):
                    hex_code = s[i+2:i+6]
                    result.append(chr(int(hex_code, 16)))
                    i += 6
                else:
                    result.append(s[i])
                    i += 1
            elif nxt == 'N':
                # Unicode name - this is complex, skip for now
                result.append(s[i])
                i += 1
            else:
                result.append(s[i])
                i += 1
        else:
            result.append(s[i])
            i += 1
    return ''.join(result)

