            while j < n and (s[j].isalnum() or s[j] == '_'):
                j += 1
            tokens.append(('NAME', s[i:j]))
            i = j
        elif c.isdigit():
            j = i + 1
            while j < n and s[j].isdigit():
                j += 1
            if j < n and s[j] == '.':
                j += 1
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(('FLOAT', float(s[i:j])))
            else:
                tokens.append(('INT', int(s[i:j])))
            i = j
        elif c in "'\"":
            quote = c
            j = i + 1
            buf = ''
            while j < n and s[j] != quote:
                if s[j] == '\\':
                    j += 1
                    if j >= n:
                        break
                    e = s[j]
                    if e == 'n': buf += '\n'
                    elif e == 't': buf += '\t'
                    elif e == 'r': buf += '\r'
