import ast

# Build a minimal safe evaluator that handles the specific expressions needed

# We need to handle:
# - re.findall(pattern, string, flags)
# - len(list)
# - String literals
# - Numeric literals  
# - 'a' * 100000 (multiplication of string and int)
# - Tuple/dict/list literals if needed

def code_eval(code, globals_map=None):
    if globals_map is None:
        globals_map = _build_globals()

    tree = ast.parse(code, mode='eval')
    return _eval_node(tree.body, globals_map)


