def _parse_args(args_str):
    """Parse comma-separated arguments from a function call argument string."""
    args = []
    depth = 0
    current = ''
    in_string = False
    string_char = None
    i = 0

    while i < len(args_str):
        c = args_str[i]

        if in_string:
            if c == '\\' and i + 1 < len(args_str):
                current += c + args_str[i+1]
                i += 2
                continue
            if c == string_char:
                in_string = False
                current += c
            else:
                current += c
        else:
            if c in ('"', "'"):
                in_string = True
                string_char = c
                current += c
            elif c == '(':
                depth += 1
                current += c
            elif c == ')':
                depth -= 1
                current += c
            elif c == ',' and depth == 0:
                args.append(current.strip())
                current = ''
            else:
