def _eval_single_arg(arg):
    """Evaluate a single argument which should be a string literal or integer literal."""
    arg = arg.strip()

    # Check for raw string
    if arg.startswith("r'") or arg.startswith('r"'):
        quote_char = arg[1]
        # Extract the content between the quotes
