import sys

def _percent_b(v, prec=4):
    """Replicate CPython's %b formatting for given value and precision."""
    import math
    if isinstance(v, bool):
        v = int(v)
    if v == 0:
        # Zero: '0p+0' regardless of precision
        mantissa_digits = ""
        exp = 0
    else:
        sign = "-" if v < 0 else ""
        av = abs(v)
        m, e = math.frexp(av)
        # m in [0.5, 1.0); convert to integer bits
        # frexp returns m such that av = m * 2^e, m in [0.5, 1.0)
        # We want M.mmm... form where M is first bit (always 1)
        # Convert m to a list of binary digits after the implicit leading 1
        # m = 0.5 + fractional; multiply by 2 to get in [1, 2)
        mm = m * 2  # now in [1, 2)
        # Integer part is always 1
        frac_part = mm - 1
        # Get up to prec bits from frac_part
        bits = []
        fb = frac_part
        for i in range(prec):
            fb *= 2
            if fb >= 1:
                bits.append('1')
                fb -= 1
            else:
                bits.append('0')
        mantissa_digits = "".join(bits)
        exp = e

    if exp >= 0:
        exp_str = "+%d" % exp
    else:
        exp_str = "-%d" % (-exp)

    if mantissa_digits == "":
        result = "0p%s" % exp_str
    else:
        result = "1.%sp%s" % (mantissa_digits, exp_str)

    return repr("'" + result + "'")

