def manual_b(value, precision=None):
    """Manual implementation of %b conversion."""
    if precision is None or precision < 0:
        return bin(value)[2:]
    elif value == 0:
        return '0' * precision
    else:
        s = bin(abs(value))[2:]
        if len(s) > precision:
            # Truncate to fit
            s = s[:precision]
        else:
            # Pad with zeros on the left
            s = s.rjust(precision, '0')
        return ('-' if value < 0 else '') + s


