def pct_b(value, precision):
    """Emulate '%.*b' % precision, value"""
    if isinstance(value, bool):
        vi = int(value)
    else:
        vi = value

    if vi < 0:
        sign = '-'
        av = -vi
    else:
        sign = ''
        av = vi

    if av == 0:
        bits = '0'
    else:
        bits = bin(av)[2:]

    # Pad to at least `precision` bits on the left
    if len(bits) < precision:
        bits = '0' * (precision - len(bits)) + bits

    return sign + bits

