for c in cases:
    try:
        r = repr(b"abc".hex(c))
    except Exception as e:
        r = type(e).__name__ + ": " + str(e)
    print(repr(c), "->", r)
print("--- bytes sep ---")
for c in [b"-", b"::", b"", b"\xff"]:
    try:
        r = repr(b"abc".hex(c))
    except Exception as e:
        r = type(e).__name__ + ": " + str(e)
    print(repr(c), "->", r)
print("--- other types ---")
for c in [1, None, 2.0]:
    try:
        r = repr(b"abc".hex(c))
    except Exception as e:
        r = type(e).__name__ + ": " + str(e)
    print(repr(c), "->", r)
print("--- bytearray/memoryview.hex same rules ---")
print(sys.version)

