import base64, os, sys

def a2b_base64(s, strict_mode=False):
    # Emulate binascii.a2b_base64 behavior for Python 3.x
    if isinstance(s, str):
        s = s.encode('ascii')

    # Remove all non-alphabet characters (whitespace is not in the base64 alphabet)
    # The base64 alphabet is A-Z, a-z, 0-9, +, /, and padding =
    # In strict mode, only whitespace (space, tab, newline, carriage return, form feed, vertical tab) 
    # is allowed as garbage. In non-strict mode, all bytes outside the valid set are removed.

    valid_chars = b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/='

    filtered = bytearray()
    for byte in s:
        c = bytes([byte])
        if c in valid_chars:
            filtered.append(byte)
        elif not strict_mode:
            # In non-strict mode, ignore invalid bytes
            pass
        else:
            # In strict mode, raise an error
            raise ValueError("Non-base64 digit found")

    filtered_bytes = bytes(filtered)

    # Now validate and decode the filtered string
    # Count number of '=' signs
    pad_count = filtered_bytes.count(b'=')
    if pad_count > 2:
        raise ValueError("Excess padding in base-64 string")

    # The length of the data part (excluding padding) must be congruent to 0 or 4 mod 4
    data_len = len(filtered_bytes) - pad_count

    # Check that padding is only at the end
    last_char_index = len(filtered_bytes) - 1
    if pad_count > 0:
        # All '=' should be at the end
        for i in range(last_char_index - pad_count + 1, last_char_index + 1):
            if filtered_bytes[i] != ord('='):
                raise ValueError("Invalid base-64 padding position")
        # No '=' before the last 2 positions except when it's the final padding
        # Actually, check that there are no '=' before the padding section
        for i in range(len(filtered_bytes)):
            if filtered_bytes[i] == ord('='):
                # This must be one of the last pad_count characters
                if i < len(filtered_bytes) - pad_count:
                    raise ValueError("Invalid base-64 padding position")
                break

    if data_len % 4 != 0 and data_len % 4 != 2:
        # After removing padding, we need data_len such that total (data_len + pad_count) % 4 == 0
        total = len(filtered_bytes)
        if total % 4 != 0:
            raise ValueError("Invalid base-64 encoded string, wrong padding")

    # Total length with padding must be multiple of 4
    if len(filtered_bytes) % 4 != 0:
        raise ValueError("Invalid base-64 encoded string, wrong padding")

    # Build output
    out = bytearray()
    idx = 0
    n = len(filtered_bytes)
    while idx < n:
        block = filtered_bytes[idx:idx+4]
        idx += 4

        # Decode the 4-byte group into up to 3 bytes
        vals = []
        for ch in block:
            c = chr(ch)
            if c == '=':
                vals.append(None)
            elif 'A' <= c <= 'Z':
