def safe_eval(expr):
    """Safely evaluate a Python expression that only uses builtins."""
    # The expressions we need to handle are all of the form:
    # <bytes_or_bytearray>.hex(...)
    # We can parse them and evaluate safely since they only use literals and method calls

    tree = ast.parse(expr, mode='eval')

    def _eval_node(node):
        if isinstance(node, ast.Expression):
            return _eval_node(node.body)
        elif isinstance(node, ast.Call):
            func = _eval_node(node.func)
            args = [_eval_node(a) for a in node.args]
            kwargs = {k.arg: _eval_node(v) for k, v in node.keywords}
            return func(*args, **kwargs)
        elif isinstance(node, ast.Attribute):
            obj = _eval_node(node.value)
            attr = node.attr
            return getattr(obj, attr)
        elif isinstance(node, ast.Bytes):
            return node.s
        elif isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.Name):
            name = node.id
            if name == 'bytearray':
                return bytearray
            raise NameError(name)
        else:
            raise ValueError("Unsupported AST node: %s" % type(node).__name__)

    return _eval_node(tree)

