def hexsep(data, sep=None, bytes_per_sep=None):
    if sep is None and bytes_per_sep is None:
        return data.hex()
    # If either provided, both must be valid
    if sep is None:
        raise TypeError("bytes_per_sep argument given without sep")
    if not isinstance(sep, (str, bytes)):
        raise TypeError("sep must be str or bytes, not %s" % type(sep).__name__)
    if bytes_per_sep is None:
        raise ValueError("sep argument given without bytes_per_sep")
    if not isinstance(bytes_per_sep, int) or isinstance(bytes_per_sep, bool):
        raise TypeError("bytes_per_sep must be an integer, not %s" % type(bytes_per_sep).__name__)
    if bytes_per_sep <= 0:
        raise ValueError("bytes_per_sep must be greater than zero")
    if isinstance(sep, str):
        if len(sep) != 1:
            raise ValueError("separators must be a single ASCII character")
        if ord(sep) > 127:
            raise ValueError("separators must be a single ASCII character")
        sep_bytes = sep.encode('ascii')
    else:
        sep_bytes = sep
        if len(sep_bytes) != 1:
            raise ValueError("separators must be a single ASCII character")
        if ord(sep_bytes[0]) > 127:
            raise ValueError("separators must be a single ASCII character")

    hex_str = data.hex()
    result = []
    i = 0
    while i < len(hex_str):
        chunk_end = min(i + bytes_per_sep * 2, len(hex_str))
        result.append(hex_str[i:chunk_end])
        i = chunk_end
        if i < len(hex_str):
            result.append(sep)
    return ''.join(result)


