def bytes_hex(data, sep=None, bytes_per_sep=1):
    # Mirror CPython's bytes.hex() behavior

    # Validate sep
    if sep is None:
        use_sep = None
    else:
        if isinstance(sep, (bytes, bytearray)):
            if len(sep) != 1:
                raise ValueError("separator must be a single byte")
            use_sep = chr(sep[0])
        elif isinstance(sep, str):
            if len(sep) != 1:
                raise ValueError("separator must be a single byte")
            if not all(32 <= ord(c) <= 126 for c in sep):
                raise ValueError("separator must be a printable ASCII character")
            use_sep = sep
        else:
            raise TypeError("sep must be an str or bytes-like object of length 1")

    # Validate bytes_per_sep
    if not isinstance(bytes_per_sep, int):
        raise TypeError("bytes_per_sep must be an integer")
    if isinstance(bytes_per_sep, bool):
        raise TypeError("bytes_per_sep must be an integer")
    if bytes_per_sep < 1:
        raise ValueError("bytes_per_sep must be at least 1")

    # Convert data to list of bytes
    if isinstance(data, (bytes, bytearray)):
        b_list = list(data)
    else:
        raise TypeError("argument must be a bytes-like object")

    # Build result
    parts = []
    n = len(b_list)
    for i, b in enumerate(b_list):
        parts.append('%02x' % b)
        if use_sep is not None and i + 1 < n and (i + 1) % bytes_per_sep == 0:
            parts.append(use_sep)

    return ''.join(parts)


