# Base64 and URL-safe base64 encode/decode tables
_b64chars = b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
_altchars_default = b'+/'
_url_chars = b'-_'


def _b64_encode(data, altchars=None):
    """Emulate base64.b64encode(data, altchars=None)"""
    if not isinstance(data, (bytes, bytearray, memoryview)):
        raise TypeError("expected a bytes-like object, got %s" % type(data).__name__)
    if altchars is not None:
        if not isinstance(altchars, (bytes, bytearray, memoryview)):
            raise TypeError("altchars must be a bytes-like object")
        data_bytes = bytes(data)
    else:
        data_bytes = bytes(data)

    # Perform standard base64 encoding using binascii
    result = binascii.b2a_base64(data_bytes)[:-1]  # strip trailing newline

    if altchars is not None:
        altchars_bytes = bytes(altchars)
        if len(altchars_bytes) != 2:
            raise TypeError("altchars must be of length 2")
        plus_idx = result.find(b'+')
        slash_idx = result.find(b'/')
        if plus_idx >= 0 or slash_idx >= 0:
            result = result.replace(b'+', altchars_bytes[0:1]).replace(b'/', altchars_bytes[1:2])

    return result


def _b64_decode(s, altchars=None, validate=False):
    """Emulate base64.b64decode(s, altchars=None, validate=False)"""
    # Determine the type of input
    if isinstance(s, str):
        s_bytes = s.encode('utf-8')
    elif isinstance(s, (bytes, bytearray, memoryview)):
        s_bytes = bytes(s)
    else:
        raise TypeError("expected a bytes-like object, got %s" % type(s).__name__)

    # Handle altchars
    if altchars is not None:
        if not isinstance(altchars, (bytes, bytearray, memoryview)):
            raise TypeError("altchars must be a bytes-like object")
        altchars_bytes = bytes(altchars)
        if len(altchars_bytes) != 2:
            raise TypeError("altchars must be of length 2")
        s_bytes = s_bytes.replace(altchars_bytes[0:1], b'+').replace(altchars_bytes[1:2], b'/')

    # Validate if requested
    if validate:
        for c in s_bytes:
            ch = chr(c)
            if ch == '=':
                continue
            if not (ch.isalnum() or ch in '+/='):
                raise ValueError("Non-base64 digit found")

    # Decode
    try:
        result = binascii.a2b_base64(s_bytes)
    except (TypeError, ValueError) as e:
        if isinstance(e, ValueError):
            raise ValueError(str(e))
        else:
            raise TypeError(str(e))

    return result


def _urlsafe_b64_encode(data):
    """Emulate base64.urlsafe_b64encode(data)"""
    return _b64_encode(data, altchars=b'-_')


def _urlsafe_b64_decode(s):
    """Emulate base64.urlsafe_b64decode(s)"""
    if isinstance(s, str):
        s_bytes = s.encode('utf-8')
    elif isinstance(s, (bytes, bytearray, memoryview)):
        s_bytes = bytes(s)
    else:
        raise TypeError("expected a bytes-like object, got %s" % type(s).__name__)

    # Replace - with + and _ with /
    s_bytes = s_bytes.replace(b'-', b'+').replace(b'_', b'/')

    return _b64_decode(s_bytes)


