def b64encode(data, altchars=None):
    if isinstance(data, str):
        raise TypeError("argument should be bytes or an integer, not 'str'")
    try:
        buf = bytearray(data)
    except (TypeError, ValueError) as e:
        raise TypeError("argument should be a bytes-like object, not '%s'" % type(data).__name__) from None

    # Base64 encode
    result = []
    n = len(buf)
    i = 0
    b64chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    while i < n:
        # Get up to 3 bytes
        b0 = buf[i]
        has_b1 = i + 1 < n
        has_b2 = i + 2 < n
        b1 = buf[i + 1] if has_b1 else 0
        b2 = buf[i + 2] if has_b2 else 0

        # Combine into 24-bit number
        triple = (b0 << 16) | (b1 << 8) | b2

        # Extract 4 six-bit groups
        c0 = triple >> 18
        c1 = (triple >> 12) & 0x3F
        c2 = (triple >> 6) & 0x3F
        c3 = triple & 0x3F

        if has_b2:
            result.append(b64chars[c0])
            result.append(b64chars[c1])
            result.append(b64chars[c2])
            result.append(b64chars[c3])
        elif has_b1:
            result.append(b64chars[c0])
            result.append(b64chars[c1])
            result.append(b64chars[c2])
            result.append('=')
        else:
            result.append(b64chars[c0])
            result.append(b64chars[c1])
            result.append('=')
            result.append('=')

        i += 3

    encoded = ''.join(result)

    if altchars is not None:
        if isinstance(altchars, str):
            raise TypeError("altchars must be bytes-like object, not 'str'")
        try:
            alt_bytes = bytes(altchars)
        except (TypeError, ValueError):
            raise TypeError("altchars must be bytes-like object") from None
        if len(alt_bytes) != 2:
            raise binascii.Error("altchars length must be 2")
        encoded = encoded.replace('+', chr(alt_bytes[0])).replace('/', chr(alt_bytes[1]))
        return bytes([ord(c) for c in encoded])
    else:
        return bytes([ord(c) for c in encoded])


class BinASCIIError(Exception):
    pass

def b64decode(s, altchars=None, validate=False):
    if isinstance(s, str):
        # Accept str for compatibility - CPython's b64decode does accept str
        pass
    elif isinstance(s, int):
        raise TypeError("argument should be a bytes-like object or ASCII-string, not 'int'")
    else:
        try:
            s = bytes(s)
        except (TypeError, ValueError):
            raise TypeError("argument should be a bytes-like object or ASCII-string, not '%s'" % type(s).__name__) from None

    if isinstance(s, str):
        s_bytes = s.encode('utf-8')
    else:
        s_bytes = s

    # Strip whitespace
    filtered = b''
    for byte in s_bytes:
        ch = chr(byte)
        if ch not in ' \t\n\r\x0b\x0c':
            filtered += bytes([byte])

    if altchars is not None:
        if isinstance(altchars, str):
            raise TypeError("altchars must be bytes-like object, not 'str'")
        try:
            alt_bytes = bytes(altchars)
        except (TypeError, ValueError):
            raise TypeError("altchars must be bytes-like object") from None
        if len(alt_bytes) != 2:
            raise BinASCIIError("altchars length must be 2")
        # Replace altchars with + and /
        new_filtered = b''
        for byte in filtered:
            if byte == alt_bytes[0]:
                new_filtered += b'+'
            elif byte == alt_bytes[1]:
                new_filtered += b'/'
            else:
                new_filtered += bytes([byte])
        filtered = new_filtered

    if validate:
        b64set = set(b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=")
        for byte in filtered:
            if byte not in b64set:
                raise BinASCIIError("Non-base64 digit found")

    # Decode
    b64map = {}
    b64chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    for i, c in enumerate(b64chars):
        b64map[ord(c)] = i

    # Count padding
    s_str = filtered.decode('latin-1') if isinstance(filtered, bytes) else filtered
    padding = 0
    for c in reversed(s_str):
        if c == '=':
            padding += 1
        else:
            break

    if padding > 2:
        raise BinASCIIError("Incorrect padding")

    # Remove padding
    core = s_str.rstrip('=')

    # Decode each group of 4 chars
    result = bytearray()
    i = 0
    while i < len(core):
        remaining = len(core) - i
        if remaining >= 4:
            g = core[i:i+4]
            v0 = b64map.get(ord(g[0]), -1)
            v1 = b64map.get(ord(g[1]), -1)
            v2 = b64map.get(ord(g[2]), -1)
            v3 = b64map.get(ord(g[3]), -1)

            if v0 < 0 or v1 < 0 or v2 < 0 or v3 < 0:
                raise BinASCIIError("Non-base64 digit found")

            triple = (v0 << 18) | (v1 << 12) | (v2 << 6) | v3
            result.append((triple >> 16) & 0xFF)
            result.append((triple >> 8) & 0xFF)
            result.append(triple & 0xFF)
            i += 4
        elif remaining == 3:
            g = core[i:i+3]
            v0 = b64map.get(ord(g[0]), -1)
            v1 = b64map.get(ord(g[1]), -1)
            v2 = b64map.get(ord(g[2]), -1)

            if v0 < 0 or v1 < 0 or v2 < 0:
                raise BinASCIIError("Non-base64 digit found")

            triple = (v0 << 18) | (v1 << 12) | (v2 << 6)
            result.append((triple >> 16) & 0xFF)
            result.append((triple >> 8) & 0xFF)
            i += 3
        elif remaining == 2:
            g = core[i:i+2]
            v0 = b64map.get(ord(g[0]), -1)
            v1 = b64map.get(ord(g[1]), -1)

            if v0 < 0 or v1 < 0:
                raise BinASCIIError("Non-base64 digit found")

            triple = (v0 << 18) | (v1 << 12)
            result.append((triple >> 16) & 0xFF)
            i += 2
        elif remaining == 1:
            raise BinASCIIError("Invalid base64 data")

    # Truncate based on padding
    if padding == 1:
        result = result[:-2]
    elif padding == 2:
        result = result[:-1]

    return bytes(result)


def urlsafe_b64encode(data):
    return b64encode(data, altchars=b'-_')

def urlsafe_b64decode(s):
    return b64decode(s, altchars=b'-_')


