    def rec(dirpath, idx):
        if idx == len(parts):
            # we have reached the end of the pattern; check that this dir matches? no - pattern refers to files, not dirs at this point unless it ends in /
            return
        pat = parts[idx]
        if pat == '**':
            # match zero or more directory levels
            # Zero levels: continue matching the rest from the same directory (only if next segment(s) are not '**' again?)
            # Simpler: first try matching the remaining pattern here, then descend into subdirs.
            # To avoid exponential blow-up on many '**', but patterns likely simple.
            # We attempt matching the rest of the pattern starting at current directory
            rec_dir_match(dirpath, idx + 1, names_all_subdirs())
            # also descend into each subdirectory
