            for name in sorted(listdir_safe(dirpath)):
                p = os.path.join(dirpath, name)
                if os.path.isdir(p):
                    rec(p, idx)
        elif pat == '*':
            for name in sorted(listdir_safe(dirpath)):
                full = os.path.join(dirpath, name)
                if os.path.isfile(full):
                    # If this is the last segment, record file; otherwise if more segments remain and it's a dir, continue
                    if idx == len(parts) - 1:
                        results.append(full)
                    elif os.path.isdir(full):
                        rec(full, idx + 1)
                # For non-last segments, must be directory
                # Actually for middle segments '*' should match dirs too? In glob semantics, * does not match paths containing separator, but within a single component it can match directories when followed by more components.
                    # Already handled above
        else:
            full = os.path.join(dirpath, pat)
            if idx == len(parts) - 1:
                if os.path.isfile(full):
                    results.append(full)
            else:
                if os.path.isdir(full):
                    rec(full, idx + 1)

    def listdir_safe(d):
        try:
            return os.listdir(d)
        except OSError:
            return []

    def names_all_subdirs():
        pass

    def rec_dir_match(dirpath, idx, _unused=None):
        if idx == len(parts):
            # nothing left: if dirpath itself is a file? no, it's a directory. Ignore.
            return
        pat = parts[idx]
        if pat == '**':
            # Again, allow skipping further
            for name in sorted(listdir_safe(dirpath)):
                p = os.path.join(dirpath, name)
                if os.path.isdir(p):
                    rec_dir_match(p, idx + 1)
                # Also allow stopping here if this was the final pattern element, but idx==len already handled above
            return
        elif pat == '*':
            for name in sorted(listdir_safe(dirpath)):
                full = os.path.join(dirpath, name)
                if idx == len(parts) - 1:
                    if os.path.isfile(full):
                        results.append(full)
                elif os.path.isdir(full):
                    rec_dir_match(full, idx + 1)
        else:
            full = os.path.join(dirpath, pat)
            if idx == len(parts) - 1:
                if os.path.isfile(full):
                    results.append(full)
            elif os.path.isdir(full):
                rec_dir_match(full, idx + 1)

    # Start recursion from the root given by the fixed part before first wildcard
    # Find the longest prefix of parts that contains no wildcards
    fixed_idx = 0
    while fixed_idx < len(parts) and parts[fixed_idx] not in ('**', '*'):
