class TrackedFile:
    def __init__(self, file):
        self.file = file
        self.pos = 0
    def read(self, n=None):
        data = self.file.read(n)
        self.pos += len(data)
        return data
    def readline(self):
        data = self.file.readline()
        self.pos += len(data)
        return data
    def readlines(self):
        data = self.file.readlines()
        self.pos += sum(len(line) for line in data)
        return data
    def __iter__(self):
        return self

