class FakeFile:
    def __init__(self, f):
        self.f = f
        self.iterating = False
        self.it = None

    def readline(self):
        return self.f.readline()

    def readlines(self):
        return self.f.readlines()

    def read(self, size=-1):
        return self.f.read(size)

    def __next__(self):
        # Manually manage iterator state to avoid setting the underlying flag?
        # Or just call next on the underlying file's iterator?
        if self.it is None:
            self.it = iter(self.f)
        return next(self.it)

    def __iter__(self):
        if self.it is None:
            self.it = iter(self.f)
        return self.it

    def seek(self, pos):
        self.f.seek(pos)
        self.it = None # Reset iterator state
        return 0

    def tell(self):
        # Here is the trick. We want the *actual* position.
        # If the underlying file has been iterated, f.tell() raises OSError.
        # But we can compute the position? 
        # Or we can force a flush/read to reset? No.
        # Actually, if we hold a reference to the buffer, we can get position from there.
        return self.f.buffer.tell()

