import os


class _TellWrapper:
    """Wrap a file object so that tell() never raises OSError.

    If an underlying tell() call would raise OSError, return -1 instead.
    All other methods delegate to the wrapped object."""

    def __init__(self, f):
        self._f = f

    def readline(self, *args, **kwargs):
        return self._f.readline(*args, **kwargs)

    def readlines(self, *args, **kwargs):
        return self._f.readlines(*args, **kwargs)

    def read(self, *args, **kwargs):
        return self._f.read(*args, **kwargs)

    def seek(self, *args, **kwargs):
        return self._f.seek(*args, **kwargs)

    def tell(self):
        try:
            return self._f.tell()
        except OSError:
            return -1

    def __next__(self):
        return next(self._f)

    def __iter__(self):
        return iter(self._f)

    def close(self):
        self._f.close()

    def __getattr__(self, name):
        return getattr(self._f, name)


