def _make_csv_reader(f):
    """Create a csv-like reader manually without importing csv."""
    # Read all data at once
    lines = f.readlines()
    idx = [0]

    class _CsvReader:
        def __next__(self):
            while idx[0] < len(lines):
                line = lines[idx[0]]
                idx[0] += 1
                # Strip trailing newline and parse CSV
                line_stripped = line.rstrip('\r\n')
                if line_stripped == '' and not any(c in line_stripped for c in [',', '"']):
                    continue
                return _parse_csv_line(line_stripped)
            raise StopIteration

        def __iter__(self):
            return self

    return _CsvReader()


def _parse_csv_line(line):
    """Parse a single CSV line, handling quoted fields."""
    fields = []
    field = []
    in_quotes = False
    i = 0
    n = len(line)

    while i < n:
        c = line[i]
        if in_quotes:
            if c == '"':
                if i + 1 < n and line[i + 1] == '"':
                    field.append('"')
                    i += 2
                else:
                    in_quotes = False
                    i += 1
            else:
                field.append(c)
                i += 1
        else:
            if c == '"':
                in_quotes = True
                i += 1
            elif c == ',':
                fields.append(''.join(field))
                field = []
                i += 1
            else:
                field.append(c)
                i += 1

    fields.append(''.join(field))
    return fields

