class _CsvReader:
    """Mimics csv.reader(f) behavior for the specific input."""
    def __init__(self, f):
        self.f = f

    def __iter__(self):
        return self

    def __next__(self):
        line = self.f.readline()
        if line == '':
            raise StopIteration
        # strip newline and split by comma
        line = line.rstrip('\n').rstrip('\r')
        if not line:
            raise StopIteration
        return line.split(',')

    def close(self):
        pass


