import json, pathlib

JD = json.JSONDecodeError


def _qualname_of(obj):
    try:
        return obj.__qualname__
    except AttributeError:
        pass
    if isinstance(obj, type):
        mod = getattr(obj, "__module__", "")
        nm = obj.__name__
        if "." in mod and mod.startswith("__main__") is False:
            parts = mod.split(".")
            top = parts[0]
            rest = parts[1:]
            inner = None
            for i in range(len(rest) - 1, -1, -1):
                candidate = ".".join([top] + rest[:i + 1])
                mobj = __import__(candidate, fromlist=[nm])
                cur = mobj
                for seg in rest[:i]:
                    cur = getattr(cur, seg, None)
                    if cur is None:
                        break
                nested = getattr(cur, nm, None) if cur is not None else None
                if nested is obj:
                    if inner is None:
                        inner = "".join(".".join([".".join(rest[:i + 1]), nm]))
            if inner is not None:
                # reconstruct: module_top.rest[:-1].Name or just Name if no outer class
                prefix = []
                for seg in rest[:-1]:
                    prefix.append(seg)
                if prefix:
                    return ".".join(prefix + [nm])
                return nm
        return nm
    # For other objects, fall back to __class__.__name__ based
    cls = type(obj)
    name = getattr(cls, "__name__", "<unknown>")
    return name


