# Reproduce the JSON tokenizer semantics from json.loads with stdlib-free code.
# Since we can't import json (only os and sys allowed), we must parse JSON by hand.
# However, the constraint says "no imports beyond os and sys". So we need to implement a minimal JSON parser.

# Let's write a simple recursive-descent JSON parser that handles the needed types.

def parse_json(s):
    i = 0
    n = len(s)

    def skip_ws():
        nonlocal i
        while i < n and s[i] in ' \t\n\r':
            i += 1

    def parse_value():
        nonlocal i
        skip_ws()
        if i >= n:
            raise ValueError("Unexpected end")
        c = s[i]
        if c == '{':
            return parse_object()
        elif c == '[':
            return parse_array()
        elif c == '"':
            return parse_string()
        elif c == 't':
            if s[i:i+4] == 'true':
                i += 4
                return True
            else:
                raise ValueError("Invalid value")
        elif c == 'f':
            if s[i:i+5] == 'false':
                i += 5
                return False
            else:
                raise ValueError("Invalid value")
        elif c == 'n':
            if s[i:i+4] == 'null':
                i += 4
                return None
            else:
                raise ValueError("Invalid value")
        else:
            return parse_number()

    def parse_string():
        nonlocal i
        if s[i] != '"':
            raise ValueError("Expected string")
        i += 1
        buf = []
        while i < n:
            c = s[i]
            if c == '\\':
                i += 1
                if i >= n:
                    raise ValueError("Bad escape")
                ec = s[i]
                if ec == '"':
                    buf.append('"')
                elif ec == '\\':
                    buf.append('\\')
                elif ec == '/':
                    buf.append('/')
                elif ec == 'b':
                    buf.append('\b')
                elif ec == 'f':
                    buf.append('\f')
                elif ec == 'n':
                    buf.append('\n')
