import os, sys

# We can't use json or collections, so we manually parse JSON lines.
# The goal: replicate the behavior of the original program exactly.

def _json_parse(s):
    """Minimal JSON parser."""
    i = 0
    n = len(s)

    def skip_ws():
        nonlocal i
        while i < n and s[i] in ' \t\n\r':
            i += 1

    def parse_value():
        nonlocal i
        skip_ws()
        if i >= n:
            raise ValueError("Unexpected end")
        c = s[i]
        if c == '{':
            return parse_object()
        elif c == '[':
            return parse_array()
        elif c == '"':
            return parse_string()
        elif c == 't':
            # true
            i += 4
            return True
        elif c == 'f':
            # false
            i += 5
            return False
        elif c == 'n':
            # null
            i += 4
            return None
        else:
            return parse_number()

    def parse_object():
        nonlocal i
        assert s[i] == '{'
        i += 1
        obj = {}
        skip_ws()
        if i < n and s[i] == '}':
            i += 1
            return obj
        while True:
            skip_ws()
            key = parse_string()
            skip_ws()
            assert s[i] == ':'
            i += 1
            val = parse_value()
            obj[key] = val
            skip_ws()
            if i < n and s[i] == ',':
                i += 1
                continue
            elif i < n and s[i] == '}':
                i += 1
                break
            else:
                raise ValueError("Expected , or }")
        return obj

    def parse_array():
        nonlocal i
        assert s[i] == '['
        i += 1
        arr = []
        skip_ws()
        if i < n and s[i] == ']':
            i += 1
            return arr
        while True:
            val = parse_value()
            arr.append(val)
            skip_ws()
            if i < n and s[i] == ',':
                i += 1
                continue
            elif i < n and s[i] == ']':
                i += 1
                break
            else:
                raise ValueError("Expected , or ]")
        return arr

    def parse_string():
        nonlocal i
        assert s[i] == '"'
        i += 1
        chars = []
        while i < n:
            c = s[i]
            if c == '\\':
                i += 1
                ec = s[i]
                if ec == 'n': chars.append('\n')
                elif ec == 't': chars.append('\t')
                elif ec == 'r': chars.append('\r')
                elif ec == '\\': chars.append('\\')
                elif ec == '/': chars.append('/')
                elif ec == '"': chars.append('"')
                elif ec == 'b': chars.append('\b')
                elif ec == 'f': chars.append('\f')
                elif ec == 'u':
                    hexs = s[i+1:i+5]
                    i += 4
                    code = int(hexs, 16)
                    chars.append(chr(code))
                else:
                    chars.append(ec)
                i += 1
            elif c == '"':
                i += 1
                break
            else:
                chars.append(c)
                i += 1
        return ''.join(chars)

    def parse_number():
        nonlocal i
        start = i
        if i < n and s[i] == '-':
            i += 1
        while i < n and s[i].isdigit():
            i += 1
        if i < n and s[i] == '.':
            i += 1
            while i < n and s[i].isdigit():
                i += 1
        if i < n and s[i] in 'eE':
            i += 1
            if i < n and s[i] in '+-':
                i += 1
            while i < n and s[i].isdigit():
                i += 1
        num_str = s[start:i]
        if '.' in num_str or 'e' in num_str or 'E' in num_str:
            return float(num_str)
        return int(num_str)

    result = parse_value()
    skip_ws()
    return result


