import base64


class Error(ValueError):
    """Exception raised when a2b_base64 fails."""
    def __init__(self, msg, e=None):
        super().__init__(msg)
        self.e = e


def a2b_base64(s, strict_mode=False):
    """Mimic binascii.a2b_base64 behavior.

    In non-strict mode, ignores invalid characters and whitespace.
    Raises Error if the input is not valid base64 (bad length/padding).
    """
    if s is None:
        raise TypeError("argument 1 must be bytes or str, not 'NoneType'")
    if isinstance(s, str):
        s = s.encode('latin-1')

    # Remove all non-base64 characters for validation purposes
    # Base64 alphabet: A-Z, a-z, 0-9, +, /, =
    valid_chars = set(b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=')
    filtered = bytearray()
    for c in s:
        if c == b'\n'[0] or c == b'\r'[0] or c == b'\t'[0] or c == b' '[0]:
            continue
        if c in valid_chars:
            filtered.append(c)

    # Now validate the filtered string
    s_filtered = bytes(filtered)

    # Check padding: '=' only at end
    eq_count = s_filtered.count(ord('='))
    if eq_count > 0:
        if s_filtered[-eq_count:] != b'=' * eq_count:
            raise Error("Invalid base64-encoded string: number of data characters ({}); "
                       "input contains non-base64 characters".format(len(s_filtered) - eq_count))
        if eq_count > 2:
            raise Error("Invalid base64-encoded string: too many '=' characters")
        if len(s_filtered) % 4 != 0:
            raise Error("Invalid base64-encoded string: number of data characters ({}) cannot be 1 more than a multiple of 4".format(len(s_filtered) - eq_count))

    if len(s_filtered) % 4 != 0:
        # For non-strict mode, we need to figure out what binascii does
        # binascii.a2b_base64 in non-strict mode will try to decode as much as possible
        # Let's just use base64.b64decode with validate=False but handle errors

        # Try to decode using base64 module
        try:
            return base64.b64decode(s_filtered, validate=False)
        except Exception as e:
            raise Error(str(e))
    else:
        # Length is multiple of 4
        try:
            return base64.b64decode(s_filtered, validate=True)
        except Exception as e:
            # Check for bad padding
            if eq_count == 1:
                raise Error("Invalid base64-encoded string: number of data characters ({}) cannot be 1 more than a multiple of 4".format(len(s_filtered) - eq_count))
            elif eq_count > 2:
                raise Error("Invalid base64-encoded string: too many '=' characters")
            raise Error(str(e))


