    """Equivalent to binascii.a2b_base64: ignores non-base64 characters, decodes."""
    if isinstance(data, str):
        data = data.encode('ascii')

    # Filter out non-base64 characters (keep only A-Z, a-z, 0-9, +, /, =)
    b64_chars = set(b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=')
    filtered = bytes(c for c in data if c in b64_chars)

    # Decode the filtered base64 string
    return base64.b64decode(filtered)

