            idx += 1
        if idx >= len(s):
            raise ValueError("Unexpected end")
        c = s[idx]
        if c == '{':
            return parse_object(idx)
        elif c == '[':
            return parse_array(idx)
        elif c == '"':
            return parse_string(idx)
