            # number or literal
            m = re.match(r'(true|false|null|-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?)', s[idx:])
            if not m:
                raise ValueError(f"Cannot parse at {idx}: {s[idx:]}")
            val_str = m.group(1)
            idx += m.end()
