                return True
            elif val_str == 'false':
                return False
            elif val_str == 'null':
                return None
            else:
                # Number
                if '.' in val_str or 'e' in val_str or 'E' in val_str:
                    fval = float(val_str)
                    if parse_float is not None:
                        return parse_float(fval)
                    return fval
                else:
                    ival = int(val_str)
                    if parse_int is not None:
                        return parse_int(ival)
                    return ival

