        result = pairs if object_pairs_hook is None else object_pairs_hook(pairs)
        if object_hook is not None and isinstance(result, dict):
            result = object_hook(result)
        return result, idx

    def parse_key(idx):
        # Key must be a string
        val, new_idx = parse_string(idx)
        return val, new_idx

    def parse_string(idx):
        # idx points to '"'
        assert s[idx] == '"'
        idx += 1
        res = []
        while idx < len(s):
            c = s[idx]
            if c == '\\':
                idx += 1
                esc = s[idx]
                if esc == '"':
                    res.append('"')
                elif esc == '\\':
                    res.append('\\')
                elif esc == '/':
                    res.append('/')
                elif esc == 'b':
                    res.append('\b')
                elif esc == 'f':
                    res.append('\f')
                elif esc == 'n':
                    res.append('\n')
                elif esc == 'r':
                    res.append('\r')
                elif esc == 't':
                    res.append('\t')
                elif esc == 'u':
                    hex_str = s[idx+1:idx+5]
                    res.append(chr(int(hex_str, 16)))
                    idx += 4
                idx += 1
            elif c == '"':
                idx += 1
                break
