                res.append(c)
                idx += 1
        return ''.join(res), idx

    def parse_array(idx):
        assert s[idx] == '['
        idx += 1
        items = []
        while idx < len(s) and s[idx] in ' \t\n\r':
            idx += 1
        if idx < len(s) and s[idx] == ']':
            idx += 1
            return items, idx
        val, idx = parse_value(idx)
        items.append(val)
        while idx < len(s) and s[idx] in ' \t\n\r':
            idx += 1
        if idx < len(s) and s[idx] == ',':
            idx += 1
            while idx < len(s) and s[idx] in ' \t\n\r':
                idx += 1
            val, idx = parse_value(idx)
            items.append(val)
            while idx < len(s) and s[idx] in ' \t\n\r':
                idx += 1
            if idx < len(s) and s[idx] == ',':
                continue
        if idx < len(s) and s[idx] == ']':
            idx += 1
        else:
            raise ValueError("Expected ]")
        return items, idx

    result, _ = parse_value(0)
    return result


