import os, sys

def parse_json(s):
    s = s.strip()
    if not s:
        raise ValueError("Empty JSON")

    def skip_ws(i):
        while i < len(s) and s[i] in ' \t\n\r':
            i += 1
        return i

    def parse_string(i):
        if s[i] != '"':
            raise ValueError(f"Expected string at {i}")
        i += 1
        buf = []
        while True:
            c = s[i]
            i += 1
            if c == '"':
                break
            elif c == '\\':
                nc = s[i]
                i += 1
                if nc == '"':
                    buf.append('"')
                elif nc == '\\':
                    buf.append('\\')
                elif nc == '/':
                    buf.append('/')
                elif nc == 'b':
                    buf.append('\b')
                elif nc == 'f':
                    buf.append('\f')
                elif nc == 'n':
                    buf.append('\n')
                elif nc == 'r':
                    buf.append('\r')
                elif nc == 't':
                    buf.append('\t')
                elif nc == 'u':
                    hex_str = s[i:i+4]
                    i += 4
                    code = int(hex_str, 16)
                    buf.append(chr(code))
                else:
                    raise ValueError(f"Invalid escape at {i-1}")
            else:
                buf.append(c)
        return ''.join(buf), i

    def parse_number(i):
        start = i
        neg = False
        if s[i] == '-':
            neg = True
            i += 1
        # Parse integer part
        is_float = False
        # Check for leading digit
        while i < len(s) and s[i].isdigit():
            i += 1
        if i > start or (neg and i == start + 1):
            pass
        # Handle decimal
        if i < len(s) and s[i] == '.':
            is_float = True
            i += 1
            while i < len(s) and s[i].isdigit():
                i += 1
        # Handle exponent
        if i < len(s) and s[i] in 'eE':
            is_float = True
            i += 1
            if i < len(s) and s[i] in '+-':
                i += 1
            while i < len(s) and s[i].isdigit():
                i += 1

        num_str = s[start:i]
        if is_float:
            val = float(num_str)
            return val, i
        else:
            val = int(num_str)
            return val, i

    def parse_value(i):
        i = skip_ws(i)
        if i >= len(s):
            raise ValueError("Unexpected end of input")
        c = s[i]
        if c == '"':
            return parse_string(i)
        elif c == '{':
            return parse_object(i)
        elif c == '[':
            return parse_array(i)
        elif c == 't':
            if s.startswith('true', i):
                return True, i + 4
            else:
                raise ValueError("Invalid value")
        elif c == 'f':
            if s.startswith('false', i):
                return False, i + 5
            else:
                raise ValueError("Invalid value")
        elif c == 'n':
            if s.startswith('null', i):
                return None, i + 4
            else:
                raise ValueError("Invalid value")
        else:
            return parse_number(i)

    def parse_object(i):
        # s[i] == '{'
        assert s[i] == '{'
        i += 1
        i = skip_ws(i)
        result = []
        if i < len(s) and s[i] == '}':
            i += 1
            return result, i

        while True:
            # Parse key
            i = skip_ws(i)
            key, i = parse_string(i)
            # Parse colon
            i = skip_ws(i)
            if s[i] != ':':
                raise ValueError(f"Expected ':' at {i}")
            i += 1
            # Parse value
            val, i = parse_value(i)
            result.append((key, val))
            # Parse comma or closing brace
            i = skip_ws(i)
            if i < len(s) and s[i] == ',':
                i += 1
                continue
            elif i < len(s) and s[i] == '}':
                i += 1
                return result, i
            else:
                raise ValueError(f"Expected ',' or '}}' at {i}")

    def parse_array(i):
        # s[i] == '['
        assert s[i] == '['
        i += 1
        i = skip_ws(i)
        result = []
        if i < len(s) and s[i] == ']':
            i += 1
            return result, i

        while True:
            val, i = parse_value(i)
            result.append(val)
            i = skip_ws(i)
            if i < len(s) and s[i] == ',':
                i += 1
                continue
            elif i < len(s) and s[i] == ']':
                i += 1
                return result, i
            else:
                raise ValueError(f"Expected ',' or ']' at {i}")

    val, _ = parse_value(0)
    return val


