import os, sys

def _mkdir_p(path):
    parts = []
    p = path
    while p != p.parent:
        parts.append(p.name)
        p = p.parent
    if not p.exists():
        os.mkdir(str(p))
    for name in reversed(parts):
        p = os.path.join(str(p), name)
        try:
            os.mkdir(p)
        except FileExistsError:
            pass

class SimplePath:
    def __init__(self, base):
        self.base = str(base)

    def __truediv__(self, other):
        return SimplePath(os.path.join(self.base, str(other)))

    def mkdir(self, parents=False):
        full = self.base
        # If parent doesn't exist and parents=True, we need to create it
        if parents:
            _mkdir_p(full)
        else:
            os.mkdir(full)

    def chmod(self, mode):
        os.chmod(self.base, mode)

    def write_text(self, text):
        with open(self.base, 'w') as f:
            f.write(text)

    def read_text(self):
        with open(self.base, 'r') as f:
