import os, sys

def mkdir_p(path):
    parts = []
    p = path
    while True:
        if os.path.exists(p) and os.path.isdir(p):
            break
        head = os.path.dirname(p)
        if head == p:
            # reached root or top
            break
        parts.append((p, not os.path.exists(head)))
        p = head
    created = []
    for (d, should_mkdir) in reversed(parts):
        try:
            os.mkdir(d)
            created.append(d)
        except OSError as e:
            # clean up what we've made so far
            for c in created:
                try:
                    os.rmdir(c)
                except OSError:
                    pass
            raise
    return path

def make_tempdir():
    base = "/tmp"
    pid = os.getpid()
    import itertools
    for n in itertools.count():
        name = "pytmp_%s_%d" % (pid, n)
        dpath = os.path.join(base, name)
        if os.path.exists(dpath):
            continue
        try:
            os.mkdir(dpath, 0o700)
        except OSError:
            continue
        return dpath
    raise OSError("could not create temp dir")

