    if math.isinf(a) and not math.isnan(b):
        return float('nan')
    # fmod = a - b * trunc(a/b)
    q = a / b
    t = math.trunc(q)
    r = a - b * t
    # Handle -0.0 case: if result is -0.0 but should be +0.0 or vice versa
