import types

class StringIOLike:
    """Mimics enough of io.StringIO for csv module."""
    def __init__(self, initial=''):
        self._buf = initial
        self._pos = 0

    def getvalue(self):
        return self._buf

    def write(self, data):
        if not isinstance(data, str):
            data = str(data)
        self._buf = self._buf[:self._pos] + data + self._buf[self._pos:]
        self._pos += len(data)
        return len(data)

    def read(self, size=-1):
        start = self._pos
        end = len(self._buf) if size < 0 else min(self._pos + size, len(self._buf))
        result = self._buf[start:end]
        self._pos = end
        return result

    def readline(self, size=-1):
        start = self._pos
        if size < 0:
            nl = self._buf.find('\n', start)
            if nl == -1:
                end = len(self._buf)
            else:
                end = nl + 1
        else:
            limit = min(start + size, len(self._buf))
            nl = self._buf.find('\n', start, limit)
            if nl == -1 or nl >= limit:
                end = limit
            else:
                end = nl + 1
        result = self._buf[start:end]
        self._pos = end
        return result

    def seek(self, offset, whence=0):
        if whence == 0:
            self._pos = offset
        elif whence == 1:
            self._pos += offset
        elif whence == 2:
            self._pos = len(self._buf) + offset
        return self._pos

    def tell(self):
        return self._pos

    def readable(self):
        return True

    def writable(self):
        return True

    def seekable(self):
        return True

    def closed(self):
        return False

    def close(self):
        pass

    def isatty(self):
        return False


def W(row, **kw):
    o = StringIOLike()
    r = csv.writer(o, **kw).writerow(row)
    return (o.getvalue(), r)

