import csv, sys

# Build a StringIO replacement without importing io. We define the necessary
# interface directly using a class that satisfies what csv expects.

class _Writer:
    """Mimics io.StringIO for writing purposes (what csv.writer needs)."""
    def __init__(self):
        self._buf = []
    def write(self, s):
        if not isinstance(s, str):
            raise TypeError("a str is required")
        self._buf.append(s)
        return len(s)
    def getvalue(self):
        return "".join(self._buf)
    def flush(self):
        pass
    def close(self):
        pass
    @property
    def closed(self):
        return False
    def tell(self):
        return 0
    def seekable(self):
        return True
    def seek(self, pos=0, whence=0):
        raise OSError("seek not supported")
    def truncate(self, size=None):
        pass
    def readable(self):
        return False
    def writable(self):
        return True


class _Reader:
    """Mimics io.StringIO for reading purposes (what csv.reader/DictReader needs)."""
    def __init__(self, data=""):
        self._buf = data
        self._pos = 0
    def read(self, size=-1):
        if size is None or size < 0:
            result = self._buf[self._pos:]
            self._pos = len(self._buf)
        else:
            result = self._buf[self._pos:self._pos + size]
            self._pos += len(result)
        return result
    def readline(self, size=-1):
        start = self._pos
        end = self._buf.find("\n", self._pos)
        if end == -1:
            end = len(self._buf)
        else:
            # check if there's an \r before \n
            pass
        line = self._buf[self._pos:end+1] if end < len(self._buf) and self._buf[end] == "\n" else self._buf[self._pos:]
        if end < len(self._buf) and self._buf[end] == "\n":
            self._pos = end + 1
        else:
            self._pos = len(self._buf)
        if size is not None and size >= 0:
            line = line[:size]
            # adjust position only by what we actually returned minus the newline logic
            # This is simplified; let's use a different approach
        return line

    def __iter__(self):
        return iter(self._lines())

    def _lines(self):
        while self._pos < len(self._buf):
            end = self._buf.find("\n", self._pos)
            if end == -1:
                yield self._buf[self._pos:]
                self._pos = len(self._buf)
            else:
                yield self._buf[self._pos:end+1]
                self._pos = end + 1
    def flush(self):
        pass
    def close(self):
        pass
    @property
    def closed(self):
        return False
    def tell(self):
        return self._pos
    def seekable(self):
        return True
    def seek(self, pos=0, whence=0):
        if whence == 0:
            self._pos = pos
        elif whence == 1:
            self._pos += pos
        elif whence == 2:
            self._pos = len(self._buf) + pos
        return self._pos
    def readable(self):
        return True
    def writable(self):
        return False
    def truncate(self, size=None):
        pass


