        row = parse_line(lines[idx], delimiter)
        d = {}
        if len(row) == len(fieldnames):
            for f, val in zip(fieldnames, row):
                d[f] = val
        elif len(row) > len(fieldnames):
            # ExtraData exception mimicry? 
            # Original catches Exception and returns tuple.
            # But DictReader usually raises Error.
            # For now, handle strictly.
            raise ValueError("line %d: expected %d fields, saw %d" % (idx+1, len(fieldnames), len(row)))
        else:
            # Missing fields: fill with restval (None)
            for f, val in zip(fieldnames, row):
                d[f] = val
            for f in fieldnames[len(row):]:
                d[f] = None
        rows.append(d)
        idx += 1

    return rows

