import csv

# We need to replace io.StringIO with a minimal equivalent that supports the
# operations used: writing strings via .write(), reading via .read(), and 
# tracking position for seek.

class _StrIO:
    def __init__(self, initial=''):
        self._buf = []
        self._pos = 0
        if initial:
            self._buf.append(initial)
            self._end = len(initial)
        else:
            self._end = 0

    def write(self, s):
        # Append to buffer and update end
        if not self._buf:
            self._buf.append(s)
            self._end += len(s)
        elif isinstance(self._buf[-1], str):
            self._buf[-1] = self._buf[-1] + s
            self._end += len(s)
        else:
            self._buf.append(s)
            self._end += len(s)
        return len(s)

    def read(self, size=-1):
        # Get full content as one string first
        if not self._buf:
            content = ''
        else:
            # Join all string parts
            parts = []
            for p in self._buf:
                if isinstance(p, str):
                    parts.append(p)
            content = ''.join(parts)

        start = self._pos
        if size is None or size < 0:
            out = content[start:]
            self._pos = len(content)
        else:
            out = content[start:start+size]
            self._pos = start + len(out)
        return out

    def getvalue(self):
        if not self._buf:
            return ''
        parts = []
        for p in self._buf:
            if isinstance(p, str):
                parts.append(p)
        return ''.join(parts)

    def tell(self):
        return self._pos

    def seek(self, offset, whence=0):
        content = self.getvalue()
        if whence == 0:
            newpos = offset
        elif whence == 1:
            newpos = self._pos + offset
        elif whence == 2:
            newpos = len(content) + offset
        self._pos = max(0, newpos)
        return self._pos

    def close(self):
        pass


