# Need to simulate csv module functionality without importing csv or io.
# Let's implement a minimal CSV-like behavior that matches the expected output.

def _csv_write_row(row, delimiter=',', lineterminator='\r\n'):
    """Write a single row and return (output_string, writerow_result)."""
    o = []
    for i, field in enumerate(row):
        if i > 0:
            o.append(delimiter)
        s = str(field)
        # Quote if contains special chars
        needs_quote = False
        for ch in s:
            if ch == delimiter or ch == '\n' or ch == '\r':
                needs_quote = True
                break
        if needs_quote:
            s = '"' + s.replace('"', '""') + '"'
        o.append(s)
    o.append(lineterminator)
    out = ''.join(o)
    return (out, None)


def _csv_writerows(rows, delimiter=',', lineterminator='\r\n'):
    o = []
    result = None
    for row in rows:
        r = _csv_write_row(row, delimiter=delimiter, lineterminator=lineterminator)
        o.append(r[0])
        result = r[1]
    return (''.join(o), result)


def _read_csv_line(line, delimiter=',', quotechar='"'):
    """Parse a single line into fields."""
    fields = []
    cur = []
    in_quotes = False
    i = 0
    while i < len(line):
        c = line[i]
        if in_quotes:
            if c == quotechar:
                if i + 1 < len(line) and line[i + 1] == quotechar:
                    cur.append(quotechar)
                    i += 2
                else:
                    in_quotes = False
                    i += 1
            else:
                cur.append(c)
                i += 1
        else:
            if c == quotechar:
                in_quotes = True
                i += 1
            elif c == delimiter:
                fields.append(''.join(cur))
                cur = []
                i += 1
            else:
                cur.append(c)
                i += 1
    fields.append(''.join(cur))
    return fields


def _read_csv_all(data, delimiter=',', quotechar='"'):
    """Read all lines from string data and return list of lists."""
    # Handle \r\n, \n, \r as line terminators
    # Split by newlines but handle quoted fields spanning multiple lines
    fields_result = []
    i = 0
    n = len(data)
    cur_fields = []
    cur_field = []
    in_quotes = False

    while i < n:
        c = data[i]
        if in_quotes:
            if c == quotechar:
                if i + 1 < n and data[i + 1] == quotechar:
                    cur_field.append(quotechar)
                    i += 2
                else:
                    in_quotes = False
                    i += 1
            elif c == '\n' or c == '\r':
                cur_field.append(c)
                i += 1
                # Check for \r\n
                if c == '\r' and i < n and data[i] == '\n':
                    i += 1
            else:
                cur_field.append(c)
                i += 1
        else:
            if c == quotechar:
                in_quotes = True
                i += 1
            elif c == delimiter:
                cur_fields.append(''.join(cur_field))
                cur_field = []
                i += 1
            elif c == '\n':
                cur_fields.append(''.join(cur_field))
                cur_field = []
                if cur_fields != [''] or len(fields_result) == 0:
                    # Add the line unless it's completely empty (just newline)
                    # Actually, let's always add it
                    fields_result.append(cur_fields)
                    cur_fields = []
                i += 1
            elif c == '\r':
                cur_fields.append(''.join(cur_field))
                cur_field = []
                if cur_fields != [''] or len(fields_result) == 0:
                    fields_result.append(cur_fields)
                    cur_fields = []
                i += 1
                if i < n and data[i] == '\n':
                    i += 1
            else:
                cur_field.append(c)
                i += 1

    # Last field/line
    if cur_fields != [''] or cur_field != [] or len(fields_result) == 0 and (cur_fields or cur_field):
        if cur_field or cur_fields:
            cur_fields.append(''.join(cur_field))
            fields_result.append(cur_fields)

    # Filter out rows that are just one empty string (empty lines)
    # Actually, let's be careful - we need to match csv.reader behavior
    return [f for f in fields_result if not (len(f) == 1 and f[0] == '')]


