        delimiter = kw.get('delimiter', ',')
        # Parse first non-empty line as fieldnames
        lines_data = data
        if not lines_data.strip('\r\n'):
            return []

        # Get field names from first line
        first_line_end = len(lines_data)
        j = 0
        in_q = False
        while j < len(lines_data):
            c = lines_data[j]
            if in_q:
                if c == '"':
                    if j + 1 < len(lines_data) and lines_data[j + 1] == '"':
                        j += 2
                    else:
