                        j += 1
                else:
                    j += 1
            else:
                if c == '"':
                    in_q = True
                    j += 1
                elif c == '\n':
                    first_line_end = j
                    break
                elif c == '\r':
                    first_line_end = j
                    break
                else:
                    j += 1

        first_line = lines_data[:first_line_end]
        fieldnames = _read_csv_line(first_line, delimiter=delimiter)

        # Parse remaining lines
        rest = lines_data[first_line_end:]
        if rest.startswith('\n'):
            rest = rest[1:]
        elif rest.startswith('\r\n'):
            rest = rest[2:]
        elif rest.startswith('\r'):
            rest = rest[1:]

        results = []
        if rest:
            rows = _read_csv_all(rest, delimiter=delimiter)
            for row in rows:
                d = {}
                for i, name in enumerate(fieldnames):
                    if i < len(row):
                        d[name] = row[i]
                    else:
                        d[name] = ''
                results.append(d)
