            self._data = data
            self._pos = 0
            self._lines = None
            self._line_idx = 0
        def _ensure_lines(self):
            if self._lines is None:
                # Split by '\n' but keep track; csv.reader expects readline to return lines including newline
                # Actually csv module uses .readline() or iterates. Let's implement readline that mimics real file behavior.
                # For simplicity, we pre-split on '\n' and add it back.
