                # We need to return each line with trailing '\n' except possibly the last if no trailing newline
                newlines = []
                for i, p in enumerate(parts):
                    if i < len(parts) - 1:
                        newlines.append(p + '\n')
                    else:
                        newlines.append(p)
                self._lines = newlines
        def readline(self, size=None):
            self._ensure_lines()
            if self._line_idx >= len(self._lines):
                return ''
            line = self._lines[self._line_idx]
            self._line_idx += 1
            if size is not None and size >= 0:
                line = line[:size+1] if len(line) > size else line
            return line
        def read(self, size=-1):
            self._ensure_lines()
            rem = ''.join(self._lines[self._line_idx:])
            if size == -1:
                res = rem
                self._line_idx = len(self._lines)
            else:
                res = rem[:size]
                # Advance line_idx appropriately
                consumed = len(res)
                while self._line_idx < len(self._lines) and consumed > 0:
                    l = self._lines[self._line_idx]
                    if consumed >= len(l):
                        consumed -= len(l)
                        self._line_idx += 1
                    else:
                        break
            return res
        def __iter__(self):
            self._ensure_lines()
            return iter(self._lines[self._line_idx:])

