import csv

class StringIOLike:
    def __init__(self, data=''):
        self._data = list(data) if isinstance(data, str) else list(data)
        self._pos = 0

    def write(self, s):
        # find the insertion position based on current pos
        insert_at = self._pos
        for c in s:
            self._data.insert(insert_at, c)
            insert_at += 1
        self._pos = insert_at
        return len(s)

    def getvalue(self):
        return ''.join(self._data)

    def seek(self, pos):
        self._pos = pos
        return self._pos

    def tell(self):
        return self._pos

    def read(self, n=-1):
        if n < 0:
            result = ''.join(self._data[self._pos:])
            self._pos = len(self._data)
        else:
            end = min(self._pos + n, len(self._data))
            result = ''.join(self._data[self._pos:end])
            self._pos = end
        return result

    def readline(self, size=None):
        if size is None:
            nl_pos = self._data.find('\n', self._pos)
            if nl_pos == -1:
                result = ''.join(self._data[self._pos:])
                self._pos = len(self._data)
            else:
                result = ''.join(self._data[self._pos:nl_pos+1])
                self._pos = nl_pos + 1
        else:
            nl_pos = self._data.find('\n', self._pos, self._pos + size)
            if nl_pos == -1 or nl_pos > self._pos + size - 1:
                end = min(self._pos + size, len(self._data))
                result = ''.join(self._data[self._pos:end])
                self._pos = end
            else:
                result = ''.join(self._data[self._pos:nl_pos+1])
                self._pos = nl_pos + 1
        return result

    def close(self):
        pass

def W(row, **kw):
    o = StringIOLike()
    r = csv.writer(o, **kw).writerow(row)
    return (o.getvalue(), r)

