import sys, csv

class StringIO:
    def __init__(self, initial="", newline=None):
        self._buf = []
        if initial:
            self._buf.append(initial)
        self._pos = 0
        self._closed = False
        self._newline = newline

    @property
    def closed(self):
        return self._closed

    def close(self):
        self._closed = True

    def flush(self):
        pass

    def isatty(self):
        return False

    def read(self, size=-1):
        if self._closed:
            raise ValueError("I/O operation on closed file")
        s = ''.join(self._buf)
        if size is None or size < 0:
            result = s[self._pos:]
            self._pos = len(s)
        else:
            result = s[self._pos:self._pos+size]
            self._pos += len(result)
        return result

    def readline(self, size=-1):
        if self._closed:
            raise ValueError("I/O operation on closed file")
        s = ''.join(self._buf)
        start = self._pos
        if start >= len(s):
            return ''
        # Find next newline
        idx = s.find('\n', start)
        if idx == -1:
            if size >= 0 and (len(s) - start) > size:
                end = start + size
            else:
                end = len(s)
            result = s[start:end]
            self._pos = end
        else:
            if size >= 0 and (idx - start + 1) > size:
                end = start + size
            else:
                end = idx + 1
            result = s[start:end]
            self._pos = end
        return result

    def readlines(self, hint=-1):
        lines = []
        while True:
            line = self.readline()
            if not line:
                break
            lines.append(line)
        return lines

    def write(self, s):
        if self._closed:
            raise ValueError("I/O operation on closed file")
        self._buf.append(s)
        return len(s)

    def writelines(self, lines):
        if self._closed:
            raise ValueError("I/O operation on closed file")
        for line in lines:
            self.write(line)

    def getvalue(self):
        return ''.join(self._buf)

    def truncate(self, size=None):
        if self._closed:
            raise ValueError("I/O operation on closed file")
        s = ''.join(self._buf)
        if size is None:
            self._buf = [s[:self._pos]]
        else:
            self._buf = [s[:size]]
        if size is not None and self._pos > size:
            self._pos = size

    def seek(self, offset, whence=0):
        if self._closed:
            raise ValueError("I/O operation on closed file")
        s = ''.join(self._buf)
        if whence == 0:
            newpos = offset
        elif whence == 1:
            newpos = self._pos + offset
        elif whence == 2:
            newpos = len(s) + offset
        else:
            raise ValueError('whence must be 0, 1, or 2')
        if newpos < 0:
            raise ValueError('negative position')
        self._pos = newpos
        return self._pos

    def tell(self):
        if self._closed:
            raise ValueError("I/O operation on closed file")
        return self._pos

    def __iter__(self):
        saved_pos = self._pos
        while True:
            line = self.readline()
            if not line:
                break
            yield line

    def __enter__(self):
        return self

    def __exit__(self, *args):
        self.close()


