class _Reader:
    """Simulates iterating over lines like io.StringIO would."""
    def __init__(self, data):
        # Build list of lines as StringIO would yield them (with \n attached)
        self.lines = []
        i = 0
        while i < len(data):
            j = data.find('\n', i)
            if j == -1:
                self.lines.append(data[i:])
                break
            else:
                self.lines.append(data[i:j + 1])
                i = j + 1
        self._i = 0
    def __iter__(self):
        return self
    def __next__(self):
        if self._i >= len(self.lines):
            raise StopIteration
        l = self.lines[self._i]
        self._i += 1
        return l

