def safe_repr(s):
    # Convert string to its repr-equivalent without using repr() on the string itself
    # We need to produce a Python literal that, when passed to int(), equals s
    # and produces byte-identical output when printed.

    # We'll manually build the repr of the string:
    # - If it contains no special chars, just quote it with single or double quotes
    # - Handle backslashes, quotes, newlines, tabs, etc.

    result = []
    for c in s:
        cp = ord(c)
        if c == '\\':
            result.append('\\\\')
        elif c == '\n':
            result.append('\\n')
        elif c == '\t':
            result.append('\\t')
        elif c == '\r':
            result.append('\\r')
        elif c == "'":
            # Check if we can use double quotes instead
            result.append("'")
        elif c == '"':
            result.append('"')
        elif 0x20 <= cp < 0x7f:
            result.append(c)
        elif cp == 0x0b:
            result.append('\\x0b')
        elif cp == 0x0c:
            result.append('\\x0c')
        elif cp == 0xa0:
            result.append('\\xa0')
        elif cp < 0x20:
            result.append('\\x%02x' % cp)
        else:
            result.append('\\u%04x' % cp)

    return "'" + ''.join(result) + "'"

