# Helper function to replicate int() parsing behavior without using repr() on non-ASCII strings
def parse_int_str(s: str) -> str:
    """Return the string result of int(s), exactly as Python would."""
    s = s.strip()  # int() strips leading/trailing whitespace

    if not s:
        raise ValueError("empty string for int()")

    # Check for underscores in valid positions (between digits, not at start/end unless combined with base prefix)
    # Python's int() allows underscores between digits
    # But first handle sign and prefixes

    # Determine sign
    idx = 0
    negative = False
    if s[0] in ('+', '-'):
        negative = (s[0] == '-')
        idx = 1

    rest = s[idx:]

    if not rest:
        raise ValueError("invalid literal for int(): sign only")

    # Check for prefixes
    base = 10
    if rest.lower().startswith('0x') and len(rest) > 2:
        base = 16
        digits_part = rest[2:]
    elif rest.lower().startswith('0b') and len(rest) > 2:
        base = 2
        digits_part = rest[2:]
    elif rest.lower().startswith('0o') and len(rest) > 2:
        base = 8
        digits_part = rest[2:]
    else:
        digits_part = rest

    if not digits_part:
        raise ValueError("invalid literal for int(): no digits after prefix")

    # Validate all characters are valid for this base
    valid_chars = set()
    if base <= 10:
        for i in range(base):
            valid_chars.add(str(i))
    else:
        for i in range(10):
            valid_chars.add(str(i))
        for i in range(base - 10):
            valid_chars.add(chr(ord('a') + i))
            valid_chars.add(chr(ord('A') + i))

    # Check each character in digits_part is valid (underscore allowed but not consecutively or at ends in some cases)
    # Python rules: underscores can appear between digits, but not at start/end, not consecutive
    cleaned = []
    prev_underscore = False
    for c in digits_part:
        if c == '_':
            if not cleaned or prev_underscore or c == '_' and (not cleaned or cleaned[-1] == '_'):
                raise ValueError("invalid literal for int(): bad underscore placement")
            if prev_underscore:
                raise ValueError("invalid literal for int(): consecutive underscores")
            prev_underscore = True
            continue
        if c not in valid_chars:
            raise ValueError(f"invalid literal for int(): invalid character {c!r}")
        cleaned.append(c)
        prev_underscore = False

    # If digits end with underscore, that's also invalid
    if digits_part.endswith('_') or digits_part.startswith('_'):
        raise ValueError("invalid literal for int(): bad underscore placement")

    # Calculate the integer value
    try:
        val = int(''.join(cleaned), base)
    except ValueError:
        raise ValueError("invalid literal for int()")

    if negative:
        val = -val

    return str(val)


