def custom_repr(s):
    # Build repr of a string without using the built-in repr (to avoid unicode tables issue)
    if s == '':
        return "''"
    out = []
    use_double = False
    for c in s:
        if c == '"':
            use_double = True
            break
    quote = '"' if use_double else "'"
    out.append(quote)
    for c in s:
        o = ord(c)
        if c == '\\':
            out.append('\\\\')
        elif use_double and c == '"':
            out.append('\\"')
        elif not use_double and c == "'":
            out.append("\\'")
        elif o < 32 or o == 127:
            # Control characters: use \x, \t, \n, \r, etc.
            if c == '\t':
                out.append('\\t')
            elif c == '\n':
                out.append('\\n')
            elif c == '\r':
                out.append('\\r')
            elif o >= 32:
                pass  # shouldn't happen given check
            else:
                out.append('\\x%02x' % o)
        else:
            out.append(c)
    out.append(quote)
    return ''.join(out)

