def _eval_case(expr):
    # Parse the expression safely using compile and ast
    import ast

    tree = ast.parse(expr, mode='eval')

    # Whitelist of allowed names
    allowed_names = {'float', 'int', 'str', 'bool', 'None', 'True', 'False'}

    def is_safe(node):
        if isinstance(node, ast.Expression):
            return is_safe(node.body)
        elif isinstance(node, ast.Constant):
            return True
        elif isinstance(node, ast.Num):
            return True
        elif isinstance(node, ast.Str):
            return True
        elif isinstance(node, ast.Name):
            return node.id in allowed_names
        elif isinstance(node, ast.BinOp):
            return is_safe(node.left) and is_safe(node.right)
        elif isinstance(node, ast.UnaryOp):
            return is_safe(node.operand)
        elif isinstance(node, ast.Compare):
            for comp in (node.left,) + node.comparators:
                if not is_safe(comp):
                    return False
            return True
        elif isinstance(node, ast.List):
            return all(is_safe(e) for e in node.elts)
        elif isinstance(node, ast.Tuple):
            return all(is_safe(e) for e in node.elts)
        elif isinstance(node, ast.Set):
            return all(is_safe(e) for e in node.elts)
        elif isinstance(node, ast.Call):
            if isinstance(node.func, ast.Name) and node.func.id in allowed_names:
                return all(is_safe(a) for a in node.args)
            return False
        else:
            return False

    if not is_safe(tree):
        raise ValueError("unsafe expression")

    # Evaluate
    result = eval(compile(tree, '<expr>', 'eval'), {'__builtins__': {}})
    return result


