def _eval_node(node):
    if isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.UnaryOp):
        op = _eval_op(node.op)
        operand = _eval_node(node.operand)
        if op is not None:
            return op(operand)
        else:
            raise ValueError("Unsupported unary operator")
    elif isinstance(node, ast.BinOp):
        left = _eval_node(node.left)
        right = _eval_node(node.right)
        op = node.op
        if isinstance(op, ast.Add):
            return left + right
        elif isinstance(op, ast.Sub):
            return left - right
        elif isinstance(op, ast.Mult):
            return left * right
        elif isinstance(op, ast.Div):
            return left / right
        elif isinstance(op, ast.Mod):
            return left % right
        else:
            raise ValueError("Unsupported binary operator")
    elif isinstance(node, ast.Compare):
        left = _eval_node(node.left)
        ops = node.ops
        comparators = node.comparators
        result = True
        for i in range(len(ops)):
            right = _eval_node(comparators[i])
            op_func = _get_compare_func(ops[i])
            if not op_func(left, right):
                result = False
                break
            left = right
        return result
    elif isinstance(node, ast.Call):
        func_name = getattr(node.func, 'id', None)
        args = [_eval_node(a) for a in node.args]
        kwargs = {}
        for kw in node.keywords:
            if kw.arg is None:
                raise ValueError("Unsupported **kwargs in call")
            kwargs[kw.arg] = _eval_node(kw.value)
        if func_name == 'float':
            return float(*args, **kwargs)
        elif func_name == 'int':
            return int(*args, **kwargs)
        elif func_name == 'sorted':
            return sorted(*args, **kwargs)
        else:
            raise ValueError("Unsupported function call: %s" % func_name)
    elif isinstance(node, ast.List):
        return [_eval_node(e) for e in node.elts]
    elif isinstance(node, ast.Tuple):
        return tuple(_eval_node(e) for e in node.elts)
    elif isinstance(node, ast.Set):
        return set(_eval_node(e) for e in node.elts)
    elif isinstance(node, ast.Dict):
        return {_eval_node(k): _eval_node(v) for k, v in zip(node.keys, node.values)}
    elif isinstance(node, ast.Name):
        name = node.id
        if name == 'True':
            return True
        elif name == 'False':
            return False
        elif name == 'None':
            return None
        else:
            raise NameError("name '%s' is not defined" % name)
    elif isinstance(node, ast.Attribute):
        raise AttributeError("Attribute access not supported")
    else:
        raise TypeError("Unsupported AST node type: %s" % type(node).__name__)

def _eval_op(op):
    if isinstance(op, ast.USub):
        return lambda x: -x
    elif isinstance(op, ast.UAdd):
        return lambda x: +x
    elif isinstance(op, ast.Not):
        return lambda x: not x
    else:
        return None

def _get_compare_func(op):
    if isinstance(op, ast.Lt):
        return lambda a, b: a < b
    elif isinstance(op, ast.LtE):
        return lambda a, b: a <= b
    elif isinstance(op, ast.Gt):
        return lambda a, b: a > b
    elif isinstance(op, ast.GtE):
