import sys

def elf_target(path, is_static):
    try:
        with open(path, 'rb') as f:
            header = f.read(20)
        if len(header) < 4 or header[:4] != b'\x7fELF':
            return 'not-an-ELF'

        if is_static:
            arch = 'static-elf'
        else:
            arch = 'dynamic-elf'

        # Determine architecture from e_machine (offset 18, 2 bytes little-endian on x86)
        machine = int.from_bytes(header[18:20], 'little')
        if machine == 3:
            arch += '-i386'
        elif machine == 62:
            arch += '-x86_64'
        elif machine == 20:
            arch += '-arm'
        elif machine == 40:
            arch += '-ppc'
        else:
            arch += f'-unknown({machine})'

        return arch
    except (FileNotFoundError, PermissionError, OSError):
        return 'not-an-elf-file'

