def _eval_node(node):
    if isinstance(node, ast.Constant):
        # Handle bytes literals (type is bytes) and int/str/etc
        return node.value
    elif isinstance(node, ast.List):
        return [_eval_node(elt) for elt in node.elts]
    elif isinstance(node, ast.Tuple):
        return tuple(_eval_node(elt) for elt in node.elts)
    elif isinstance(node, ast.UnaryOp):
        op = type(node.op).__name__
        val = _eval_node(node.operand)
        if op == 'Not':
            return not val
        elif op == 'USub':
            return -val
        elif op == 'UAdd':
            return val
    elif isinstance(node, ast.BinOp):
        left = _eval_node(node.left)
        right = _eval_node(node.right)
        op_type = type(node.op)
        if op_type is ast.Add:
            return left + right
        elif op_type is ast.Sub:
            return left - right
        elif op_type is ast.Mult:
            return left * right
        elif op_type is ast.FloorDiv:
            return left // right
        elif op_type is ast.Mod:
            return left % right
    elif isinstance(node, ast.Call):
        func = node.func
        args = [_eval_node(a) for a in node.args]
        kwargs = {}
        for kw in node.keywords:
            kwargs[_get_name(kw.arg)] = _eval_node(kw.value)
        return _call_func(func, args, kwargs)
    elif isinstance(node, ast.Attribute):
        value = _eval_node(node.value)
        attr = node.attr
        return getattr(value, attr)
    elif isinstance(node, ast.Name):
        name = node.id
        if name == '__builtins__':
            raise NameError("not allowed")
        # Allow None, True, False which are constants but may appear as names in older AST
        raise NameError("name '%s' is not defined" % name)
    elif isinstance(node, ast.Compare):
        left = _eval_node(node.left)
        result = True
        for op, comp in zip(node.ops, node.comparators):
            right = _eval_node(comp)
            if isinstance(op, ast.Eq):
                curr = left == right
            elif isinstance(op, ast.NotEq):
                curr = left != right
            elif isinstance(op, ast.Lt):
                curr = left < right
            elif isinstance(op, ast.LtE):
                curr = left <= right
            elif isinstance(op, ast.Gt):
                curr = left > right
            elif isinstance(op, ast.GtE):
                curr = left >= right
            elif isinstance(op, ast.In):
                curr = left in right
            elif isinstance(op, ast.NotIn):
                curr = left not in right
            else:
                raise NotImplementedError("comparison op %s" % type(op).__name__)
            if not curr:
                return False
            left = right
        return result
    elif isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            result = True
            for v in node.values:
                result = _eval_node(v)
                if not result:
                    break
            return result
        elif isinstance(node.op, ast.Or):
            result = False
            for v in node.values:
                result = _eval_node(v)
                if result:
                    break
            return result
    raise NotImplementedError("AST node type: %s" % type(node).__name__)


