def safe_eval(expr):
    """Evaluate a restricted expression without using eval."""
    tree = ast.parse(expr, mode="eval")

    def get_name(node):
        if isinstance(node, ast.Name):
            return node.id
        elif isinstance(node, ast.Attribute):
            return getattr(node, "attr", None)
        return None

    def evaluate(node):
        if isinstance(node, ast.Expression):
            return evaluate(node.body)
        elif isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.BinOp):
            left = evaluate(node.left)
            right = evaluate(node.right)
            if isinstance(node.op, ast.Add):
                return left + right
            elif isinstance(node.op, ast.Sub):
                return left - right
            elif isinstance(node.op, ast.Mult):
                return left * right
            elif isinstance(node.op, ast.Div):
                return left / right
            else:
                raise NotImplementedError("Unsupported binary operator")
        elif isinstance(node, ast.UnaryOp):
            operand = evaluate(node.operand)
            if isinstance(node.op, ast.USub):
                return -operand
            elif isinstance(node.op, ast.UAdd):
                return +operand
            else:
                raise NotImplementedError("Unsupported unary operator")
        elif isinstance(node, ast.BoolOp):
            values = [evaluate(v) for v in node.values]
            if isinstance(node.op, ast.And):
                result = True
                for v in values:
                    if not v:
                        return v
                return values[-1]
            elif isinstance(node.op, ast.Or):
                result = False
                for v in values:
                    if v:
                        return v
                return values[0]
            else:
                raise NotImplementedError("Unsupported boolop")
        elif isinstance(node, ast.Compare):
            left = evaluate(node.left)
            for op, comparator in zip(node.ops, node.comparators):
                right = evaluate(comparator)
                if isinstance(op, ast.Eq):
                    res = left == right
                elif isinstance(op, ast.NotEq):
                    res = left != right
                elif isinstance(op, ast.Lt):
                    res = left < right
                elif isinstance(op, ast.LtE):
                    res = left <= right
                elif isinstance(op, ast.Gt):
                    res = left > right
                elif isinstance(op, ast.GtE):
                    res = left >= right
                elif isinstance(op, ast.Is):
                    res = left is right
                elif isinstance(op, ast IsNot):
                    res = left is not right
                elif isinstance(op, ast.In):
                    res = left in right
                elif isinstance(op, ast.NotIn):
                    res = left not in right
                else:
                    raise NotImplementedError("Unsupported comparison operator")
                if not res:
                    return False
                left = right
            return True
        elif isinstance(node, ast.Call):
            func = evaluate(node.func)
            args = [evaluate(a) for a in node.args]
            kwargs = {kw.arg: evaluate(kw.value) for kw in node.keywords}
            return func(*args, **kwargs)
        elif isinstance(node, ast.Attribute):
            value = evaluate(node.value)
            return getattr(value, node.attr)
        elif isinstance(node, ast.Name):
            if node.id in _GLOBALS:
                return _GLOBALS[node.id]
            raise NameError("name '%s' is not defined" % node.id)
        elif isinstance(node, ast.List):
            return [evaluate(e) for e in node.elts]
        elif isinstance(node, ast.Tuple):
            return tuple(evaluate(e) for e in node.elts)
        elif isinstance(node, ast.Dict):
            d = {}
            for k, v in zip(node.keys, node.values):
                if k is not None:
                    d[evaluate(k)] = evaluate(v)
                else:
                    # dict unpacking (Python 3.5+)
                    key_val, val_val = zip(*evaluate(v).items())
                    d.update(zip(key_val, val_val))
            return d
        elif isinstance(node, ast.Subscript):
            value = evaluate(node.value)
            slice_ = evaluate(node.slice)
            return value[slice_]
        elif isinstance(node, ast.Index):
            return evaluate(node.value)
        elif isinstance(node, ast.Slice):
            lower = evaluate(node.lower) if node.lower else None
            upper = evaluate(node.upper) if node.upper else None
            step = evaluate(node.step) if node.step else None
            return slice(lower, upper, step)
        else:
            raise NotImplementedError("Unsupported AST node type: %s" % type(node).__name__)

    return evaluate(tree)


