    m = re.match(r"^(\S+)\.(\w+)\((.*)\)$", expr)
    if not m:
        raise ValueError("Cannot parse expression: %s" % expr)

    obj_str = m.group(1)
    method_name = m.group(2)
    args_str = m.group(3)

    # Evaluate the object
    if obj_str.startswith("b'") and obj_str.endswith("'"):
        obj = obj_str[2:-1].encode('latin-1')
    elif obj_str.startswith('b"') and obj_str.endswith('"'):
        obj = obj_str[2:-1].encode('latin-1')
    elif obj_str.startswith("'") and obj_str.endswith("'"):
        obj = obj_str[1:-1]
    else:
        try:
            obj = int(obj_str)
        except ValueError:
            raise ValueError("Cannot evaluate object: %s" % obj_str)

    # Parse arguments
    if args_str.strip() == '':
        args = []
    else:
        args = [_parse_arg(a.strip()) for a in _split_args(args_str)]

    # Call the method
    try:
        method = getattr(obj, method_name)
        result = method(*args)
        return ('value', result)
    except Exception as ex:
        return ('error', type(ex).__name__, str(ex))


def _split_args(s):
    # Split comma-separated args, respecting quotes and brackets
    args = []
    current = []
    depth = 0
    in_str = None
    i = 0
    while i < len(s):
        c = s[i]
        if in_str:
            current.append(c)
            if c == in_str and (i == 0 or s[i-1] != '\\'):
                in_str = None
        else:
            if c in "'\"":
                in_str = c
                current.append(c)
            elif c == '[':
                depth += 1
                current.append(c)
            elif c == ']':
                depth -= 1
                current.append(c)
            elif c == ',' and depth == 0:
                args.append(''.join(current))
                current = []
            else:
                current.append(c)
        i += 1
    if current:
        args.append(''.join(current))
    return args


def _parse_arg(a):
    a = a.strip()
    if a.startswith("b'") and a.endswith("'"):
        return a[2:-1].encode('latin-1')
    elif a.startswith('b"') and a.endswith('"'):
        return a[2:-1].encode('latin-1')
    elif a.startswith("'") and a.endswith("'"):
        return a[1:-1]
    elif a.startswith('"') and a.endswith('"'):
        return a[1:-1]
    elif a.startswith('['):
        # List
        inner = a[1:-1].strip()
        if not inner:
            return []
        items = [_parse_arg(x.strip()) for x in _split_args(inner)]
        return items
    else:
        try:
            return int(a)
        except ValueError:
            pass
        try:
            return float(a)
        except ValueError:
            pass
        return a


