from collections.abc import Set as _AbcSet

class _FS(tuple):
    __slots__ = ()
    def __new__(cls, it):
        return super().__new__(cls, tuple(it))
    def __repr__(self):
        s = set(self)
        return '{' + ', '.join(repr(x) for x in sorted(s)) + '}'
    def __eq__(self, o):
        if isinstance(o, _FS):
            return frozenset(self) == frozenset(o)
        if not isinstance(o, (set, frozenset)):
            try:
                h = hash(o)
            except TypeError:
                return NotImplemented
            return set(o) == frozenset(self)
        return frozenset(self) == frozenset(o)
    def __hash__(self):
        return hash(frozenset(self))
    def __le__(self, o):
        return frozenset(self) <= frozenset(o)
    def __ge__(self, o):
        return frozenset(self) >= frozenset(o)
    def __lt__(self, o):
        return frozenset(self) < frozenset(o)
    def __gt__(self, o):
        return frozenset(self) > frozenset(o)
    def __ne__(self, o):
        eq = self.__eq__(o)
        return eq if eq is not NotImplemented else True
    # subset/superset ops
    def isdisjoint(self, other):
        return frozenset(self).isdisjoint(other)
    def __contains__(self, item):
        return frozenset(self).__contains__(item)
    def copy(self):
        return _FS(self)

