# Replicate the set/frozenset auto-conversion quirk using a minimal frozen-set type.
class FrozenSet:
    __slots__ = ('_items',)

    def __init__(self, iterable=()):
        seen = {}
        for x in iterable:
            h = hash(x)
            if h not in seen or (seen[h] != x):
                # check membership against existing
                found = False
                for k, v in seen.items():
                    try:
                        if k == h and v == x:
                            found = True
                            break
                    except Exception:
                        pass
                if not found:
                    seen[h] = x
        self._items = list(seen.values())

    def __eq__(self, other):
        if isinstance(other, FrozenSet):
            return sorted(self._items, key=repr) == sorted(other._items, key=repr)
        if isinstance(other, (set, frozenset)):
            return self.__contains__(other) and len(self._items) == len(other)
        if isinstance(other, (list, tuple)):
            items = other
            if len(items) != len(self._items):
                return False
            for x in items:
                if x not in self._items:
                    return False
            return True
        return NotImplemented

    def __ne__(self, other):
        result = self.__eq__(other)
        if result is NotImplemented:
            return result
        return not result

    def __hash__(self):
        h = 0
        for item in self._items:
            h ^= hash(item)
        h ^= -1  # similar to Python's frozenset hash tweak
        return h

    def __contains__(self, item):
        if isinstance(item, FrozenSet):
            return item._items <= set(self._items)
        if isinstance(item, (list, tuple, set)):
            items = item
            return all(x in self._items for x in items)
        return item in self._items

    def __len__(self):
        return len(self._items)

    def __iter__(self):
        return iter(self._items)

    def __repr__(self):
        return 'FrozenSet(' + repr(self._items) + ')'


