import sys

def _make_frozenset_from_iter(iterable):
    """
    Build an object that behaves like a frozenset for hashing and equality,
    but is not the builtin frozenset.
    """
    items = tuple(sorted(iterable, key=repr)) if any(isinstance(x, str) for x in list(iterable)) else tuple(sorted(iterable)) if all(isinstance(x, int) or isinstance(x, float) for x in list(iterable)) else tuple(list(iterable))

    class _FS:
        __slots__ = ('_items', '_hash')

        def __init__(self, items):
            self._items = items
            self._hash = hash(items)

        def __eq__(self, other):
            if not hasattr(other, '_items'):
                return NotImplemented
            return self._items == other._items

        def __ne__(self, other):
            result = self.__eq__(other)
            if result is NotImplemented:
                return result
            return not result

        def __hash__(self):
            return self._hash

        def __iter__(self):
            return iter(self._items)

        def __contains__(self, item):
            return item in self._items

        def __len__(self):
            return len(self._items)

        def __repr__(self):
            return 'frozenset(' + repr(list(self._items)) + ')'

    return _FS(items)

