# frozenset is banned; create immutable-hashable container via subclassing tuple
class FS(tuple):
    __slots__ = ()
    def __new__(cls, it=()):
        return super().__new__(cls, tuple(it))
    def __repr__(self):
        return f"FS{tuple.__repr__(self)}"
    def __hash__(self):
        # hash like a set: sum of element hashes in sorted order
        try:
            items = [hash(x) for x in self]
            return sum(sorted(items), 5381)
        except TypeError:
            return id(self)
    def __eq__(self, other):
        if not isinstance(other, FS):
            return NotImplemented
        return set(self) == set(other)

