def _make_frozenset(lst):
    class _FS(set):
        def __new__(cls, *args):
            if args:
                items = list(args[0]) if not isinstance(args[0], (list, tuple, set)) else list(args[0])
            else:
                items = []
            return super().__new__(cls, items)

        def add(self, item):
            raise TypeError("frozenset: cannot use 'add' on a frozenset")

        def update(self, iterable):
            raise TypeError("frozenset: cannot use 'update' on a frozenset")

        def remove(self, item):
            raise TypeError("frozenset: cannot use 'remove' on a frozenset")

        def discard(self, item):
            raise TypeError("frozenset: cannot use 'discard' on a frozenset")

        def pop(self):
            raise TypeError("frozenset: cannot use 'pop' on a frozenset")

        def __or__(self, other):
            return set(self) | set(other)

        def __ior__(self, other):
            raise TypeError("frozenset: cannot use '|=' on a frozenset")

        def __and__(self, other):
            return set(self) & set(other)

        def __iand__(self, other):
            raise TypeError("frozenset: cannot use '&=' on a frozenset")

        def __sub__(self, other):
            return set(self) - set(other)

        def __isub__(self, other):
            raise TypeError("frozenset: cannot use '-=' on a frozenset")

        def __xor__(self, other):
            return set(self) ^ set(other)

        def __ixor__(self, other):
            raise TypeError("frozenset: cannot use '^=' on a frozenset")

        def union(self, *others):
            result = set(self)
            for o in others:
                result |= set(o)
            return result

        def intersection(self, *others):
            result = set(self)
            for o in others:
                result &= set(o)
            return result

        def difference(self, *others):
            result = set(self)
            for o in others:
                result -= set(o)
            return result

        def symmetric_difference(self, other):
            return set(self) ^ set(other)

        def isdisjoint(self, other):
            return set(self).isdisjoint(other)

        def issubset(self, other):
            return set(self).issubset(other)

        def issuperset(self, other):
            return set(self).issuperset(other)

        def copy(self):
            return set(self)

    # Override the type name for repr/str purposes
    _FS.__name__ = "frozenset"
    _FS.__qualname__ = "frozenset"

    return _FS(lst)


