def do_glob(pattern):
    """Emulate glob.glob with recursive support for the specific pattern we need."""
    # Split the pattern
    # The pattern is 'src/lypning/assets/**/*.jsonl'

    results = []

    # The base directory part before **
    if '/**/' in pattern:
        idx = pattern.index('/**/')
        base = pattern[:idx]
        rest = pattern[idx + len('/**/'):]  # rest is '*.jsonl'

        def recursive_walk(dirpath, suffix_pattern):
            # Find all files matching suffix_pattern in dirpath and subdirectories
            try:
                entries = os.listdir(dirpath)
            except OSError:
                return
            for entry in entries:
                full_path = os.path.join(dirpath, entry)
                if os.path.isdir(full_path):
                    recursive_walk(full_path, suffix_pattern)
                else:
                    # Check if entry matches suffix_pattern
                    if match_simple(entry, suffix_pattern):
                        results.append(full_path)

        recursive_walk(base, rest)
    elif pattern.endswith('.**'):
        # not relevant for our case
        pass
    else:
        # No **, simple glob
        parts = pattern.split('/')
        current_dirs = ['.']
        for i, part in enumerate(parts):
            new_dirs = []
            for d in current_dirs:
                try:
                    entries = os.listdir(d)
                except OSError:
                    continue
                for entry in entries:
                    if match_simple(entry, part):
                        full = os.path.join(d, entry)
                        if i == len(parts) - 1:
                            if os.path.isfile(full):
                                results.append(full)
                        else:
                            if os.path.isdir(full):
                                new_dirs.append(full)
            current_dirs = new_dirs

    return sorted(results)


def match_simple(name, pattern):
    """Match a single path component against a glob pattern (without /)."""
    if pattern == '*':
        return True
    if pattern.startswith('*.') and name.endswith(pattern[2:]):
        return True
    if name == pattern:
        return True
    # Simple wildcard matching
    return _fnmatch_no_import(name, pattern)


def _fnmatch_no_import(name, pattern):
    """Simple fnmatch without importing fnmatch module."""
    import re
    # Convert glob pattern to regex
    regex = ''
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == '*':
            regex += '.*'
        elif c == '?':
            regex += '.'
        else:
            regex += re.escape(c)
        i += 1
    return re.match('^' + regex + '$', name) is not None


