def decode_surrogateescape(raw_bytes):
    result_chars = []
    i = 0
    while i < len(raw_bytes):
        c = raw_bytes[i]
        if c > 127:
            result_chars.append(chr(0xDC80 + c))
            i += 1
        elif c < 0x80:
            try:
                # Try to handle multi-byte UTF-8 sequences
                if c >= 0xC0 and c <= 0xDF:
                    if i + 1 < len(raw_bytes) and (raw_bytes[i+1] & 0xC0) == 0x80:
                        code = ((c & 0x1F) << 6) | (raw_bytes[i+1] & 0x3F)
                        result_chars.append(chr(code))
                        i += 2
                        continue
                    else:
                        result_chars.append(chr(0xDC80 + c))
                        i += 1
                elif c >= 0xE0 and c <= 0xEF:
                    if i + 2 < len(raw_bytes) and (raw_bytes[i+1] & 0xC0) == 0x80 and (raw_bytes[i+2] & 0xC0) == 0x80:
                        code = ((c & 0x0F) << 12) | ((raw_bytes[i+1] & 0x3F) << 6) | (raw_bytes[i+2] & 0x3F)
                        result_chars.append(chr(code))
                        i += 3
                        continue
                    else:
                        result_chars.append(chr(0xDC80 + c))
                        i += 1
                elif c >= 0xF0 and c <= 0xF4:
                    if i + 3 < len(raw_bytes) and (raw_bytes[i+1] & 0xC0) == 0x80 and (raw_bytes[i+2] & 0xC0) == 0x80 and (raw_bytes[i+3] & 0xC0) == 0x80:
                        code = ((c & 0x07) << 18) | ((raw_bytes[i+1] & 0x3F) << 12) | ((raw_bytes[i+2] & 0x3F) << 6) | (raw_bytes[i+3] & 0x3F)
                        result_chars.append(chr(code))
                        i += 4
                        continue
                    else:
                        result_chars.append(chr(0xDC80 + c))
                        i += 1
                else:
                    result_chars.append(chr(0xDC80 + c))
                    i += 1
            except Exception:
                result_chars.append(chr(0xDC80 + c))
                i += 1
        else:
            result_chars.append(chr(c))
            i += 1
    return ''.join(result_chars)

