                # But let's handle properly: if it looks like start of multi-byte but malformed,
                # we should still try to decode. For safety, let's handle common cases.
                # If not enough continuation bytes, fall back to surrogateescape
                result.append('\udc' + format(b, '02x'))
                i += 1
            else:
                cp = ((b & 0x1F) << 6) | (data[i+1] & 0x3F)
                result.append(chr(cp))
                i += 2
        elif 0xE0 <= b < 0xF0:
            if i + 2 >= n or (data[i+1] & 0xC0) != 0x80 or (data[i+2] & 0xC0) != 0x80:
                result.append('\udc' + format(b, '02x'))
                i += 1
            else:
                cp = ((b & 0x0F) << 12) | ((data[i+1] & 0x3F) << 6) | (data[i+2] & 0x3F)
                result.append(chr(cp))
                i += 3
        elif 0xF0 <= b < 0xF8:
            if i + 3 >= n or (data[i+1] & 0xC0) != 0x80 or (data[i+2] & 0xC0) != 0x80 or (data[i+3] & 0xC0) != 0x80:
                result.append('\udc' + format(b, '02x'))
                i += 1
            else:
                cp = ((b & 0x07) << 18) | ((data[i+1] & 0x3F) << 12) | ((data[i+2] & 0x3F) << 6) | (data[i+3] & 0x3F)
                result.append(chr(cp))
                i += 4
        else:
            # Bytes 0x80-0xBF and 0xF8-0xFF are never valid leads; surrogateescape them
            result.append('\udc' + format(b, '02x'))
            i += 1
    return ''.join(result)


def surrogateescape_encode(s: str) -> bytes:
    """Encode a string that may contain surrogates from \\udc80-\\udcff using surrogateescape."""
    out = bytearray()
    for ch in s:
        cp = ord(ch)
        if 0xDC80 <= cp <= 0xDCFF:
            out.append(cp - 0xDC80)
        elif cp < 0x80:
            out.append(cp)
        elif cp < 0x800:
            out.append(0xC0 | (cp >> 6))
            out.append(0x80 | (cp & 0x3F))
        elif cp < 0x10000:
            out.append(0xE0 | (cp >> 12))
            out.append(0x80 | ((cp >> 6) & 0x3F))
            out.append(0x80 | (cp & 0x3F))
        else:
            out.append(0xF0 | (cp >> 18))
            out.append(0x80 | ((cp >> 12) & 0x3F))
            out.append(0x80 | ((cp >> 6) & 0x3F))
            out.append(0x80 | (cp & 0x3F))
    return bytes(out)


