def json_dumps(obj):
    # obj is a dict with one key 'stdout' mapping to a string
    key = list(obj.keys())[0]
    val = obj[key]
    escaped = ''
    for ch in val:
        cp = ord(ch)
        if ch == '"':
            escaped += '\\"'
        elif ch == '\\':
            escaped += '\\\\'
        elif ch == '\n':
            escaped += '\\n'
        elif ch == '\r':
            escaped += '\\r'
        elif ch == '\t':
            escaped += '\\t'
        elif ch == '\b':
            escaped += '\\b'
        elif ch == '\f':
            escaped += '\\f'
        elif cp < 0x20:
            escaped += '\\u%04x' % cp
        elif 0xDC80 <= cp <= 0xDCFF:
            escaped += '\\udc%02x' % (cp - 0xDC80)
        else:
            escaped += ch
    return '{"' + key + '": "' + escaped + '"}'


def json_loads(s):
    # Parse a simple JSON object {"key": "value"}
    assert s[0] == '{'
    end = s.rfind('}')
    inner = s[1:end]
    colon_idx = inner.find(':')
    key_part = inner[:colon_idx].strip()
    val_part = inner[colon_idx+1:].strip()
    key = key_part.strip('"')
    val_str = val_part[1:-1]  # remove quotes
    # Unescape
    result = []
    i = 0
    while i < len(val_str):
        c = val_str[i]
        if c == '\\':
            nxt = val_str[i+1]
            if nxt == 'u':
                hexpart = val_str[i+2:i+6]
                cp = int(hexpart, 16)
                result.append(chr(cp))
                i += 6
            elif nxt == 'n':
                result.append('\n')
                i += 2
            elif nxt == 'r':
                result.append('\r')
                i += 2
            elif nxt == 't':
                result.append('\t')
                i += 2
            elif nxt == 'b':
                result.append('\b')
                i += 2
            elif nxt == 'f':
                result.append('\f')
                i += 2
            elif nxt == '"':
                result.append('"')
                i += 2
            elif nxt == '\\':
                result.append('\\')
                i += 2
            else:
                result.append(c)
                i += 1
        else:
            result.append(c)
            i += 1
    val = ''.join(result)
    return {key: val}


