# For each byte: if 0x80 <= byte <= 0xff, it maps to chr(0xDC00 + byte)
# Otherwise, it's decoded as UTF-8 (which for ASCII bytes is just chr(byte))

def decode_surrogateescape(data):
    result = []
    i = 0
    n = len(data)
    while i < n:
        b = data[i]
        if b >= 0x80:
            # Surrogateescape: map byte to U+DC00..U+DCFF
            result.append(chr(0xDC00 + b))
            i += 1
        else:
            # Decode as UTF-8. Since all bytes < 0x80 in our case are valid UTF-8 single-byte sequences,
            # but let's handle it properly.
            if b < 0x20:
                # Control characters are fine
                result.append(chr(b))
                i += 1
            elif b == 0x7f:
                result.append(chr(0x7f))
                i += 1
            elif b < 0x80:
                result.append(chr(b))
                i += 1
            elif b < 0xC0:
                # Invalid start - shouldn't happen in our data
                result.append(chr(0xDC00 + b))
                i += 1
            elif b < 0xE0:
                # 2-byte sequence
                if i + 1 < n and data[i + 1] & 0xC0 == 0x80:
                    c = ((b & 0x1F) << 6) | (data[i + 1] & 0x3F)
                    result.append(chr(c))
                    i += 2
                else:
                    # Invalid
                    result.append(chr(0xDC00 + b))
                    i += 1
            elif b < 0xF0:
                # 3-byte sequence
                if (i + 2 < n and data[i + 1] & 0xC0 == 0x80 and data[i + 2] & 0xC0 == 0x80):
                    c = ((b & 0x0F) << 12) | ((data[i + 1] & 0x3F) << 6) | (data[i + 2] & 0x3F)
                    result.append(chr(c))
                    i += 3
                else:
                    result.append(chr(0xDC00 + b))
                    i += 1
            else:
                # 4-byte sequence or invalid
                if (i + 3 < n and data[i + 1] & 0xC0 == 0x80 and data[i + 2] & 0xC0 == 0x80 and data[i + 3] & 0xC0 == 0x80):
                    c = ((b & 0x07) << 18) | ((data[i + 1] & 0x3F) << 12) | ((data[i + 2] & 0x3F) << 6) | (data[i + 3] & 0x3F)
                    if 0xD800 <= c <= 0xDFFF:
                        # Surrogate - replace
                        result.append('\ufffd')
                    else:
                        result.append(chr(c))
                    i += 4
                else:
                    result.append(chr(0xDC00 + b))
                    i += 1
    return ''.join(result)

def encode_surrogateescape(s):
    result = bytearray()
    for ch in s:
        cp = ord(ch)
        if 0xDC00 <= cp <= 0xDCFF:
            result.append(cp - 0xDC00)
        else:
            # Encode as UTF-8
            if cp < 0x80:
                result.append(cp)
            elif cp < 0x800:
                result.append(0xC0 | (cp >> 6))
                result.append(0x80 | (cp & 0x3F))
            elif cp < 0x10000:
                result.append(0xE0 | (cp >> 12))
                result.append(0x80 | ((cp >> 6) & 0x3F))
                result.append(0x80 | (cp & 0x3F))
            else:
                result.append(0xF0 | (cp >> 18))
                result.append(0x80 | ((cp >> 12) & 0x3F))
                result.append(0x80 | ((cp >> 6) & 0x3F))
                result.append(0x80 | (cp & 0x3F))
    return bytes(result)

