import re

def byte_findall(pattern, data):
    # Manually find bytes matching pattern using str-based regex on decoded representation
    # For \s: whitespace bytes are 0x09-0x0D (tab, lf, vt, ff, cr), and also 0x20
    # Python's bytes \s matches [ \t\n\r\f\v] which is bytes 9-13 and 32
    # But the test includes \x1c-\x1f, \x85, \xa0 which are NOT matched by bytes \s
    # Let me verify: for bytes, \s only matches [ \t\n\x0b\f\r] i.e. 0x20, 0x09, 0x0a, 0x0b, 0x0c, 0x0d

    result = []
    if b'\\s' in pattern or pattern == rb'\s':
        # bytes \s matches [ \t\n\r\f\v]
        ws_bytes = {0x20, 0x09, 0x0a, 0x0b, 0x0c, 0x0d}
        for ch in data:
            if ch in ws_bytes:
                result.append(bytes([ch]))
    elif pattern == rb'.':
        # . matches any single byte except newline
        for ch in data:
            if ch != 0x0a:
                result.append(bytes([ch]))
    return result

