def frozen_dataclass(fns):
    def decorator(cls):
        field_names = list(fns)
        def __init__(self, *args, **kwargs):
            # Handle positional and keyword args
            all_args = list(args)
            if len(all_args) < len(field_names):
                for i in range(len(all_args), len(field_names)):
                    name = field_names[i]
                    if name in kwargs:
                        all_args.append(kwargs.pop(name))
                    else:
                        raise TypeError("__init__ missing required argument: %s" % name)
            elif len(all_args) > len(field_names):
                raise TypeError("__init__() takes %d positional arguments but %d were given" % (len(field_names)+1, len(all_args)+1))
            if kwargs:
                extra = [k for k in kwargs if k not in field_names]
                if extra:
                    raise TypeError("__init__() got an unexpected keyword argument '%s'" % extra[0])
                # merge kwargs with defaults for fields that have default_factory or default
                for name in field_names:
                    if name in kwargs:
                        idx = field_names.index(name)
                        if idx >= len(all_args):
                            pass  # should not happen due to above check
                # Actually, we need to properly merge positional and keyword
                # Let me redo this logic
            # Re-implement properly
            self._field_values = {}
            for i, name in enumerate(field_names):
                if i < len(all_args):
                    val = all_args[i]
                elif name in kwargs:
                    val = kwargs[name]
                else:
                    # use default
                    if hasattr(cls, '_defaults') and name in cls._defaults:
                        dflt = cls._defaults[name]
                        if callable(dflt):
                            val = dflt()
                        else:
                            val = dflt
                    else:
                        raise TypeError("__init__ missing required argument: %s" % name)
                object.__setattr__(self, name, val)

            def __repr__(self):
                return "%s(%s)" % (type(self).__name__, ", ".join("%s=%r" % (n, getattr(self, n)) for n in field_names))

            def __eq__(self, other):
                if not isinstance(other, type(self)):
                    return NotImplemented
                return all(getattr(self, n) == getattr(other, n) for n in field_names)

            def __hash__(self):
                return hash(tuple(getattr(self, n) for n in field_names))

            def __setattr__(self, name, value):
                raise AttributeError("frozen instance attribute cannot be modified")

            cls.__init__ = __init__
            cls.__repr__ = __repr__
            cls.__eq__ = __eq__
            cls.__hash__ = __hash__
            cls.__setattr__ = __setattr__
        return cls
    return decorator


