def _dc(cls, fields_spec):
    # fields_spec: list of (name, default_factory_or_default, frozen)
    names = [f[0] for f in fields_spec]

    def __init__(self, *args):
        if len(args) != len(fields_spec):
            raise TypeError(f"__init__ missing {len(fields_spec) - len(args)} required positional argument(s)")
        for i, (name, default, factory) in enumerate(fields_spec):
            val = args[i] if i < len(args) else (factory() if factory is not None else default)
            object.__setattr__(self, name, val)

    def __repr__(self):
        parts = []
        for name, _, _ in fields_spec:
            v = getattr(self, name)
            parts.append(f"{name}={v!r}")
        return f"{cls.__name__}({', '.join(parts)})"

    def __eq__(self, other):
        if type(other) is not type(self):
            return NotImplemented
        for name, _, _ in fields_spec:
            if getattr(self, name) != getattr(other, name):
                return False
        return True

    def __hash__(self):
        h = 0
        for name, _, _ in fields_spec:
            h ^= hash((getattr(self, name),))
        return h

    cls.__init__ = __init__
    cls.__repr__ = __repr__
    cls.__eq__ = __eq__
    cls.__hash__ = __hash__
    cls._frozen = True

    # Make it behave as a dataclass-like class
    class _Meta(type(cls)):
        pass

    cls.__class__ = _Meta
    return cls


