def _dataclass(frozen=True, **kw):
    def wrapper(cls):
        fields = [f for f in cls.__annotations__]
        defaults = {}
        # Get default values from the class namespace (before annotations are used)
        ns_defaults = {k: v for k, v in vars(cls).items() if k not in cls.__annotations__ and k != '__module__' and k != '__qualname__' and k != '__doc__'}

        # Check for field() markers
        field_info = []
        for fname in fields:
            default_val = ns_defaults.get(fname, _NO_DEFAULT)
            field_info.append((fname, default_val))

        no_default_sentinel = object()

        def __init__(self, *args, **kwargs):
            nfields = len(field_info)
            positional = list(args)
            while len(positional) < nfields:
                positional.append(no_default_sentinel)
            if len(positional) > nfields:
                raise TypeError("too many arguments")
            assigned = set()
            for i, (fname, _) in enumerate(field_info):
                if kwargs.get(fname, no_default_sentinel) is not no_default_sentinel:
                    setattr(self, fname, kwargs[fname])
                    assigned.add(fname)
                elif positional[i] is not no_default_sentinel:
                    setattr(self, fname, positional[i])
                    assigned.add(fname)
                else:
                    default = field_info[i][1]
                    if default is _NO_DEFAULT:
                        raise TypeError(f"missing required argument '{fname}'")
                    if callable(default):
                        setattr(self, fname, default())
                    else:
                        setattr(self, fname, default)

        if frozen:
            def __setattr__(self, name, value):
                raise AttributeError(f"cannot assign to field {name!r}")
            def __delattr__(self, name):
                raise AttributeError(f"cannot delete field {name!r}")
        else:
            pass

        def __repr__(self):
            parts = [f"{name}={getattr(self, name)!r}" for name, _ in field_info]
            return f"{cls.__name__}({', '.join(parts)})"

        def __eq__(self, other):
            if type(self) is not type(other):
                return NotImplemented
            return all(getattr(self, name) == getattr(other, name) for name, _ in field_info)

        if frozen:
            def __hash__(self):
                return hash(tuple((name, getattr(self, name)) for name, _ in field_info))

        cls.__init__ = __init__
        cls.__repr__ = __repr__
        cls.__eq__ = __eq__
        if frozen:
            cls.__hash__ = __hash__
        if not frozen:
            cls.__hash__ = None  # eq without frozen makes unhashable

        return cls
    return wrapper

