def _make_class(name, field_defs, frozen):
    """field_defs: list of (field_name, default_value_or_None_for_required, is_callable_default)"""
    attrs = {}

    def __init__(self, *args, **kwargs):
        nfields = len(field_defs)
        positional = list(args)
        while len(positional) < nfields:
            positional.append(_NO_DEFAULT)
        if len(positional) > nfields:
            raise TypeError("too many arguments")
        for i, (fname, default, is_callable) in enumerate(field_defs):
            if fname in kwargs:
                val = kwargs[fname]
            elif positional[i] is not _NO_DEFAULT:
                val = positional[i]
            else:
                if default is _NO_DEFAULT:
                    raise TypeError(f"missing required argument '{fname}'")
                if is_callable:
                    val = default()
                else:
                    val = default
            object.__setattr__(self, fname, val)

    if frozen:
        def __setattr__(self, name, value):
            raise AttributeError(f"cannot assign to field {name!r}")
        def __delattr__(self, name):
            raise AttributeError(f"cannot delete field {name!r}")
        def __hash__(self):
            return hash(tuple((name, object.__getattribute__(self, name)) for name, _, _ in field_defs))
        attrs['__setattr__'] = __setattr__
        attrs['__delattr__'] = __delattr__
        attrs['__hash__'] = __hash__
    else:
        def __hash__(self):
            return None
        attrs['__hash__'] = None

    def __eq__(self, other):
        if type(self) is not type(other):
            return NotImplemented
        return all(object.__getattribute__(self, name) == object.__getattribute__(other, name) for name, _, _ in field_defs)

    def __repr__(self):
        parts = [f"{name}={object.__getattribute__(self, name)!r}" for name, _, _ in field_defs]
        return f"{name_}({', '.join(parts)})"

    attrs['__init__'] = __init__
    attrs['__eq__'] = __eq__
    name_ = name
    attrs['__repr__'] = __repr__

    cls = type(name, (), attrs)
    # Add annotations
    cls.__annotations__ = {name: int if "models" in name else str for name, _, _ in field_defs}
    return cls

