import os, sys

def b64decode(s, validate=False):
    # Mimic base64.b64decode for the simple ASCII cases we need
    s = bytes(s)
    if validate:
        # Strict mode: reject non-base64 characters (except padding '=')
        for c in s:
            ch = chr(c)
            if not (ch.isalnum() or ch in '+/'):
                raise ValueError("Non-base64 digit found")
    # Remove padding for length check (base64 requires len % 4 == 0 after considering padding)
    pad = 0
    while s and s[-1] == ord('='):
        pad += 1
        s = s[:-1]
    if len(s) % 4 != 0:
        raise ValueError("Invalid base64-encoded string: number of data characters (%d) cannot be 1 more than a multiple of 4" % len(s))
    # Standard base64 alphabet
    alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    result = bytearray()
    bits = []
    for c in s:
        if c not in [ord(ch) for ch in alphabet]:
            continue
        idx = alphabet.index(chr(c))
        bits.append(idx)
    # Convert groups of 4 base64 chars to 3 bytes
    i = 0
    while i < len(bits):
        chunk = bits[i:i+4]
        if len(chunk) == 4:
            val = (chunk[0] << 18) | (chunk[1] << 12) | (chunk[2] << 6) | chunk[3]
            b1 = (val >> 16) & 0xFF
            b2 = (val >> 8) & 0xFF
            b3 = val & 0xFF
            # Account for padding
            if pad >= 2:
                result.append(b1)
            elif pad >= 1:
                result.append(b1); result.append(b2)
            else:
                result.append(b1); result.append(b2); result.append(b3)
        i += 4
    return bytes(result)

for v in (False, 0, None, '', b''):
    try:
        r = repr(b64decode(b'aGk=', validate=v))
    except Exception as e:
        r = '%s: %s' % (type(e).__name__, str(e)[:52])
    print('  validate=%-6r -> %s' % (v, r))

