import re
from functools import wraps

# Preserve docstrings, names, etc.
def _preserving(f):
    f.__name__ = getattr(f, '__name__', 'func')
    return f

class _Match:
    pass

@_preserving
def match(pattern, string, flags=0):
    """Return an object if pattern matches in string."""
    return re.match(pattern, string, flags)

@_preserving
def search(pattern, string, flags=0):
    """Scan through string looking for a match to the regex; returns Match object or None"""
    return re.search(pattern, string, flags)

@_preserving
def compile(pattern, flags=0):
    """Compile a regular expression and return a Regex object.

    If the input pattern is already a compiled pattern, it is returned as-is.
    """
    return re.compile(pattern, flags)

@_preserving
def sub(pattern, repl, string, count=0, flags=0):
    """Replace all occurrences of pattern in string with repl.

    Note that non-overlapping occurrences of pattern are replaced left-to-right.
    Replacements are counted, starting at 0 (count=0 means no limit).

    The replacement argument repl can be a string or a function. If it is a string,
    escape sequences are processed as in replace. Otherwise, it must be a function
    that takes a single Match object as an argument, and returns the replacement
    string.
    """
    return re.sub(pattern, repl, string, count, flags)

@_preserving
def split(pattern, string, maxsplit=0, flags=0):
    """Split string by the occurrences of pattern.

    If captures are used in the pattern, then the text of all groups are also
    returned as part of the resulting list. If maxsplit is nonzero, at most
    maxsplit splits occur, returning a list of at most maxsplit+1 elements.
    """
    return re.split(pattern, string, maxsplit, flags)

@_preserving
def findall(pattern, string, flags=0):
    """Return a list of all non-overlapping matches in string.

    If one capturing group is present in the pattern, return a list of strings
    corresponding to each occurrence of this group. If multiple groups are
    present, return a list of tuples containing the strings corresponding to
    each group.
    """
    return re.findall(pattern, string, flags)

@_preserving
def escape(string):
    """Escape special characters in string."""
    return re.escape(string)

@_preserving
def purge():
    """Purge internal caches of regex objects."""
    re.purge()

