import re

class FakeMatch:
    def __init__(self, groups, span=None, string=None):
        self._groups = groups  # dict or list
        self._span = span if span is not None else (0, len(string) if string else 0)
        self._string = string

    def group(self, *args):
        if not args:
            return self._get(0)
        if len(args) == 1:
            g = args[0]
            # Check if g is True/False (for [True]/[False])
            if isinstance(g, bool):
                raise IndexError("no such group")
            if isinstance(g, int):
                return self._get(g)
            else:
                raise TypeError("unhashable type: '%s'" % type(g).__name__)
        else:
            return tuple(self.group(a) for a in args)

    def groups(self, default=None):
        result = []
        keys = self._group_keys()
        for k in range(len(keys)):
            try:
                val = self._get(k)
                result.append(val)
            except (IndexError, KeyError):
                result.append(default)
        return tuple(result)

    def _group_keys(self):
        if isinstance(self._groups, dict):
            return sorted([k for k in self._groups.keys() if isinstance(k, int)])
        elif isinstance(self._groups, list):
            return list(range(len(self._groups)))
        return []

    def _get(self, idx):
        if isinstance(self._groups, dict):
            if idx in self._groups:
                return self._groups[idx]
            raise IndexError("no such group")
        elif isinstance(self._groups, list):
            if 0 <= idx < len(self._groups):
                return self._groups[idx]
            raise IndexError("no such group")
        raise IndexError("no such group")

    def span(self, *args):
        if not args:
            return self._span
        g = args[0]
        if isinstance(g, bool):
            raise IndexError("no such group")
        # For simplicity, return the full span for group 0, and (0,0) for others
        if g == 0:
            return self._span
        return (0, 0)

    def __getitem__(self, key):
        if isinstance(key, bool):
            raise IndexError("no such group")
        return self.group(key)


