def _parse_args(s):
    """Parse comma-separated arguments, respecting strings and parens."""
    args = []
    if not s or not s.strip():
        return args

    current = ''
    depth = 0
    in_string = False
    string_quote = None
    i = 0
    while i < len(s):
        c = s[i]
        if in_string:
            if c == '\\' and i + 1 < len(s):
                current += c + s[i+1]
                i += 2
                continue
            elif c == string_quote:
                in_string = False
                current += c
            else:
                current += c
        else:
            if c in ('"', "'"):
                in_string = True
                string_quote = c
                current += c
            elif c == '(':
                depth += 1
                current += c
            elif c == ')':
                depth -= 1
                current += c
            elif c == ',' and depth == 0:
                args.append(current.strip())
                current = ''
            else:
                current += c
        i += 1

    if current.strip():
        args.append(current.strip())

    # Now convert each arg string to actual value
    parsed_args = []
    for a in args:
        parsed_args.append(_parse_arg_value(a))

    return parsed_args


def _parse_arg_value(s):
    """Convert a string representation of an argument to its actual value."""
    s = s.strip()
    if not s:
        return None

    # Check for string literals
    if (s.startswith("'") and s.endswith("'")) or (s.startswith('"') and s.endswith('"')):
        quote = s[0]
        inner = s[1:-1]
        # Process escape sequences
        result = ''
        i = 0
        while i < len(inner):
            if inner[i] == '\\' and i + 1 < len(inner):
                nxt = inner[i+1]
                if nxt == 'n':
                    result += '\n'
                elif nxt == 't':
                    result += '\t'
                elif nxt == 'r':
                    result += '\r'
                elif nxt == '\\':
                    result += '\\'
                elif nxt == quote:
                    result += quote
                elif nxt == 'x' and i + 3 < len(inner):
                    hexcode = inner[i+2:i+4]
                    result += chr(int(hexcode, 16))
                    i += 2
                elif nxt == 'N' and inner[i+2:i+3] == '{':
                    # \N{CHARNAME}
                    end_brace = inner.find('}', i)
                    charname = inner[i+3:end_brace]
                    result += _unicode_charname(charname)
                    i = end_brace
                else:
                    result += '\\' + nxt
                i += 2
            else:
                result += inner[i]
                i += 1
        return result

    # Check for numbers
    try:
        if '.' in s:
            return float(s)
        else:
            return int(s)
    except ValueError:
        pass

    # Check for special values
    if s == 'True':
        return True
    if s == 'False':
        return False
    if s == 'None':
        return None
    if s == 'lambda m: None':
        return lambda m: None
    if s == 'lambda m: 1':
        return lambda m: 1
    if s.startswith('re.'):
        # This might be re.I, re.M, etc.
        return _parse_re_flag(s)

    # Fallback: return as string
    return s


def _unicode_charname(name):
    """Convert unicode character name to character."""
    # Simple lookup for common ones
    known = {
        'BULLET': '\u2022',
        'ZERO': '\u0000',
        'SPACE': '\u0020',
    }
    if name in known:
        return known[name]
    # Try to import unicodedata
    try:
        import unicodedata
        return unicodedata.lookup

