def safe_eval(code, globals_dict=None):
    import ast
    tree = ast.parse(code, mode='eval')

    class Evaluator(ast.NodeVisitor):
        def __init__(self, g):
            self.g = g

        def visit_Expression(self, node):
            return self.visit(node.body)

        def visit_Name(self, node):
            return self.g[node.id]

        def visit_Attribute(self, node):
            value = self.visit(node.value)
            return getattr(value, node.attr)

        def visit_Call(self, node):
            func = self.visit(node.func)
            args = []
            for a in node.args:
                args.append(self.visit(a))
            keywords = {}
            for kw in node.keywords:
                keywords[kw.arg] = self.visit(kw.value)
            return func(*args, **keywords)

        def visit_Constant(self, node):
            return node.value

        def visit_BinOp(self, node):
            left = self.visit(node.left)
            right = self.visit(node.right)
            op = type(node.op).__name__
            ops = {
                'Add': lambda a,b: a+b,
                'Sub': lambda a,b: a-b,
                'Mult': lambda a,b: a*b,
                'Div': lambda a,b: a/b,
                'FloorDiv': lambda a,b: a//b,
                'Mod': lambda a,b: a%b,
                'Pow': lambda a,b: a**b,
                'LShift': lambda a,b: a<<b,
                'RShift': lambda a,b: a>>b,
                'BitOr': lambda a,b: a|b,
                'BitAnd': lambda a,b: a&b,
                'BitXor': lambda a,b: a^b,
            }
            return ops[op](left, right)

        def visit_UnaryOp(self, node):
            operand = self.visit(node.operand)
            if isinstance(node.op, ast.Not):
                return not operand
            elif isinstance(node.op, ast.USub):
                return -operand
            elif isinstance(node.op, ast.UAdd):
                return +operand
            elif isinstance(node.op, ast.Invert):
                return ~operand

        def visit_BoolOp(self, node):
            # Simplified handling
            if isinstance(node.op, ast.And):
                result = True
                for v in node.values:
                    result = self.visit(v)
                    if not result:
                        return result
                return result
            elif isinstance(node.op, ast.Or):
                result = False
                for v in node.values:
                    result = self.visit(v)
                    if result:
                        return result
                return result

        def visit_List(self, node):
            return [self.visit(e) for e in node.elts]

        def visit_Tuple(self, node):
            return tuple(self.visit(e) for e in node.elts)

        def visit_Index(self, node):
            # Python 2 style, probably not needed
            return self.visit(node.value)

        def generic_visit(self, node):
            raise NotImplementedError(f"Unsupported node type: {type(node).__name__}")

    try:
        ev = Evaluator(globals_dict or {})
        return ev(tree)
    except Exception as e:
        raise e

