            if inner[i] == '\\' and i + 1 < len(inner):
                nxt = inner[i + 1]
                if nxt == 'n':
                    result.append('\n')
                elif nxt == 't':
                    result.append('\t')
                elif nxt == 'r':
                    result.append('\r')
                elif nxt == '\\':
                    result.append('\\')
                elif nxt == quote:
                    result.append(quote)
                elif nxt == 'x' and i + 3 < len(inner):
                    hex_str = inner[i + 2:i + 4]
                    try:
                        result.append(chr(int(hex_str, 16)))
