            else:
                processed_args.append(arg_val)

        if func_name == 'sub':
            return re.sub(*processed_args)
        elif func_name == 'split':
            return re.split(*processed_args)
        elif func_name == 'findall':
            return re.findall(*processed_args)
        elif func_name == 'match':
            pattern = processed_args[0]
            flags = 0
            for a in processed_args[1:]:
                if isinstance(a, int):
                    flags |= a
                    break
            if len(processed_args) >= 2:
                string = processed_args[1]
            else:
                string = ''
            return re.match(pattern, string, flags)
        elif func_name == 'compile':
            return re.compile(*processed_args)
        elif func_name == 'escape':
            return re.escape(*processed_args)
        elif func_name == 'purge':
            return re.purge()
        else:
            raise AttributeError("Unknown re function: %s" % func_name)


