def _ast_eval(node, names):
    import ast
    if isinstance(node, ast.Call):
        func_result = _ast_eval(node.func, names)
        args = [_ast_eval(a, names) for a in node.args]
        kwargs = {k.arg: _ast_eval(v, names) for k, v in node.keywords}
        return func_result(*args, **kwargs)
    elif isinstance(node, ast.Attribute):
        value = _ast_eval(node.value, names)
        return getattr(value, node.attr)
    elif isinstance(node, ast.Name):
        if node.id == 're':
            return fake_re
        else:
            raise NameError(name=node.id)
    elif isinstance(node, (ast.Str, ast.Num)):
        return node.s if isinstance(node, ast.Str) else node.n
    elif isinstance(node, ast.Tuple):
        return tuple(_ast_eval(el, names) for el in node.elts)
    elif isinstance(node, ast.List):
        return [_ast_eval(el, names) for el in node.elts]
    elif isinstance(node, ast.UnaryOp):
        operand = _ast_eval(node.operand, names)
        if isinstance(node.op, ast.USub):
            return -operand
        elif isinstance(node.op, ast.Not):
            return not operand
    elif isinstance(node, ast.BinOp):
        left = _ast_eval(node.left, names)
        right = _ast_eval(node.right, names)
        if isinstance(node.op, ast.Add):
            return left + right
        elif isinstance(node.op, ast.Mult):
            return left * right
        elif isinstance(node.op, ast.Pow):
            return left ** right
    else:
        raise TypeError(f"Unsupported AST node: {type(node).__name__}")

