STD = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"


def described_decode(s, alphabet=STD):
    # "a 6-bit accumulator decode that skips '=' and newlines"
    acc = 0
    nbits = 0
    out = bytearray()
    for ch in s.decode('latin1'):
        if ch in '=\n\r':
            continue
        i = alphabet.find(ch)
        if i < 0:
            continue   # lenient default: skip non-alphabet
        acc = (acc << 6) | i
        nbits += 6
        if nbits >= 8:
            nbits -= 8
            out.append((acc >> nbits) & 0xFF)
    return bytes(out)


