class MyRandom:
    def __init__(self, seed=0):
        # Reproduce the default random.Random(seed) state using Mersenne Twister
        self.state = [1234] * 624
        self.i = 0
        if seed is not None:
            self._seed_int(int(seed))

    def _seed_int(self, s):
        # Standard init_genrand for Python's Random
        st = self.state
        st[0] = s & 0xFFFFFFFF
        for i in range(1, 624):
            st[i] = (1812433253 * (st[i-1] ^ (st[i-1] >> 30)) + i) & 0xFFFFFFFF
        self.i = 624

    def twist(self):
        st = self.state
        for j in range(624):
            x = (st[j] & 0x80000000) + (st[(j+1) % 624] & 0x7FFFFFFF)
            x2 = (st[(j+397) % 624])
            st[j] = x2 ^ (x >> 1)
            if (x & 1) != 0:
                st[j] ^= 0x9908B0DF
        self.i = 0

    def next_uint32(self):
        if self.i >= 624:
            self.twist()
        y = self.state[self.i]
        self.i += 1
        y ^= (y >> 11)
        y ^= (y << 7) & 0x9D2C5680
        y ^= (y << 15) & 0xEFC60000
        y ^= (y >> 18)
        return y & 0xFFFFFFFF

    def getrandbits(self, k):
        # Same as random.getrandbits for k<=32 (our case k=1)
        # Actually we need randint which uses getrandbits internally
        # Let me implement randint directly
        pass

    def randrange(self, start, end=None):
        # This matches random.randrange behavior
        if end is None:
            end = start
            start = 0
        # In CPython, randrange calls _randbelow(end-start) + start
        # But we're just doing randint(a,b) which calls randrange(a, b+1)
        # Let's match exactly what random.randint does:
        return self._randbelow(end - start) + start

    def _randbelow(self, n):
        """Return a random int in [0, n). Matches Python's random._randbelow"""
        if n <= 0:
            raise ValueError
        getbits = (n - 1).bit_length()
        # We use getrandbits(getbits) until we get a value less than n
        while True:
            r = self.next_randbits(getbits)
            if r < n:
                return r

    def next_randbits(self, k):
        """Generate k random bits, matching random.Random.getrandbits"""
        if k < 32:
            return self.next_uint32() >> (32 - k)
        # For our use case k <= 32 always
        # But let's be safe
        result = 0
        remaining = k
        while remaining > 0:
            take = min(remaining, 32)
            u = self.next_uint32()
            result |= u << (k - remaining)
            remaining -= take
        return result & ((1 << k) - 1)

    def randint(self, a, b):
        """Match random.randint(a, b): returns integer N such that a <= N <= b"""
        return self.randrange(a, b + 1)


