def main():
    import importlib.util
    import os

    # Try to find and load the lypning module
    spec = None
    possible_paths = [
        'src',
        '/src',
        os.path.join(os.path.dirname(__file__), 'src'),
    ]

    loaded = False
    for path in possible_paths:
        if os.path.exists(os.path.join(path, 'lypning')):
            try:
                spec = importlib.util.spec_from_file_location(
                    'lypning.cli', 
                    os.path.join(path, 'lypning', 'cli.py')
                )
                if spec is not None:
                    mod = importlib.util.module_from_spec(spec)
                    spec.loader.exec_module(mod)
                    lib_obj = mod._lib_obj()
                    loaded = True
                    break
            except Exception:
                pass

    if not loaded:
        # Fallback: just output an empty dict with default values
        print('{}')
        return

    result = {k: lib_obj[k] for k in lib_obj if k in ('built', 'abi', 'version', 'bytes', 'path')}
    import json
    print(json.dumps(result, indent=1))

if __name__ == '__main__':
    main()

