def _apply_grouping(digits, grouping, sep):
    """Apply locale-based digit grouping."""
    if not digits:
        return digits
    if not grouping:
        # glibc returns 3 for standard English grouping, or a list of ints
        # If grouping is empty/None, no grouping
        return digits

    # grouping can be a tuple/list of ints, where 0 means repeat last
    # First element is the size of the first group from right
    # Subsequent elements are sizes of subsequent groups moving left
    # 0 means repeat the previous group size
    # CHAR_MAX (0xFF or 255) means stop grouping

    if isinstance(grouping, int):
        group_sizes = [grouping]
    else:
        group_sizes = list(grouping)

    result_groups = []
    idx = len(digits)
    gi = 0
    used_sep = False

    while idx > 0:
        if gi >= len(group_sizes):
            # No more group sizes defined; add all remaining digits
            result_groups.append(digits[:idx])
            break

        size = group_sizes[gi]
        if size == 0:
            continue  # This shouldn't happen per spec, but handle gracefully
        if size == 0xFF or size == 255:
            # Stop grouping
            result_groups.append(digits[:idx])
            break

        start = max(0, idx - size)
        result_groups.append(digits[start:idx])
        idx = start
        gi += 1
        used_sep = True

    # Reverse the groups and join with separator
    result_groups.reverse()
    return sep.join(result_groups)


