                    sign_char = ''
                elif not neg:
                    sign_char = '+' if sgn == '+' else ('' if sgn in ('', '-') else ' ')

                result = sign_char + prefix + core

                total_w = int(w) if w else 0
                if z and not a:
                    pad_char = '0'
                    fill_pos = 0
                else:
                    pad_char = ' '
                    fill_pos = None

                if total_w > len(result):
                    padding = total_w - len(result)
                    if not a or a == '>':
                        result = ' ' * padding + result
                    elif a == '<':
                        result = result + ' ' * padding
                    elif a == '^':
                        left = padding // 2
                        right = padding - left
                        result = ' ' * left + result + ' ' * right
                    elif a == '=':
                        # Fill between sign and digits
                        if sign_char:
                            idx = len(sign_char)
                            result = sign_char + '0' * padding + result[idx:]
                        else:
                            result = '0' * padding + result

                return result
            else:
                # Fallback: just format without 'n'
                return format(v, base_spec)

