import hashlib

def _hashlib_new(name, data=b''):
    # Use the constructor-based approach if available, otherwise fall back to module-level new
    try:
        if name == 'md5':
            h = hashlib.md5(data)
        elif name == 'sha1':
            h = hashlib.sha1(data)
        elif name == 'sha256':
            h = hashlib.sha256(data)
        elif name == 'sha512':
            h = hashlib.sha512(data)
        else:
            raise ValueError("Unsupported algorithm")
        return h
    except AttributeError:
        return hashlib.new(name, data)

for n in ('md5', 'sha1', 'sha256', 'sha512'):
    h = _hashlib_new(n)
    print(n, h.name, h.digest_size, h.block_size, repr(h.digest())[:30])

