        return hashlib.md5()
    elif name == 'sha1':
        return hashlib.sha1()
    elif name == 'sha256':
        return hashlib.sha256()
    elif name == 'sha512':
        return hashlib.sha512()
    else:
        raise ValueError("Unknown hash algorithm: " + name)

