def _read_response_file(fp, chunk_size=16384):
    data = b''
    while True:
        chunk = fp.read(chunk_size)
        if not chunk:
            break
        data += chunk
    return data


def _find_http_root(line_bytes):
    s = line_bytes.decode('utf-8', errors='ignore')
    for m in ('http://', 'https://'):
        idx = s.find(m)
        if idx != -1:
            start = idx
            end = len(s)
            for i in range(start + len(m), len(s)):
                c = s[i]
                if c.isspace():
                    end = i
                    break
            return s[start:end].strip()
    return None


def http_get(url, timeout=60, tok=None):
    # Use the socket module and standard library only.
    import socket as _socket
    from urllib.parse import urlparse as _urlparse

    parsed = _urlparse(url)
    scheme = (parsed.scheme or 'http').lower()
    host = parsed.hostname
    port = parsed.port
    if port is None:
        port = 443 if scheme == 'https' else 80
    path = parsed.path or '/'
    query = parsed.query
    if query:
        full_path = f"{path}?{query}"
    else:
        full_path = path

    sock = _socket.create_connection((host, port), timeout=timeout)
    try:
        if scheme == 'https':
            import ssl as _ssl
            context = _ssl.create_default_context()
            try:
                sock = context.wrap_socket(sock, server_hostname=host)
            except _ssl.SSLError:
                pass
        headers = {
            "Host": host if port not in (443, 80) or scheme != 'https' or scheme != 'http' else host,
            "User-Agent": "Python/3",
            "Accept": "*/*",
            "Connection": "close"
        }
        if tok:
            headers["Authorization"] = f"Bearer {tok}"

        header_lines = [f"GET {full_path} HTTP/1.1"]
        host_value = host if (port != (443 if scheme == 'https' else 80)) or (scheme == 'https' and port == 443) or (scheme == 'http' and port == 80) else f"{host}:{port}"
        header_lines.insert(1, f"Host: {host}")
        del header_lines[0]
        header_lines.append(f"GET {full_path} HTTP/1.1")
        header_lines[0] = f"GET {full_path} HTTP/1.1"
        # Build properly
        lines = [f"GET {full_path} HTTP/1.1"]
        lines.append(f"Host: {host}")
        if port != (443 if scheme == 'https' else 80):
            lines[-1] = f"Host: {host}:{port}"
        for k, v in headers.items():
            if k.lower() != 'host':
                lines.append(f"{k}: {v}")
        lines.append("")
        lines.append("")
        req_data = "\r\n".join(lines).encode('ascii')
        sock.sendall(req_data)

        # Read response
        buf = bytearray()
        while True:
            try:
                chunk = sock.recv(16384)
            except Exception:
                break
            if not chunk:
                break
            buf.extend(chunk)
            # Check if we've received all body
            text_so_far = buf.decode('latin-1')
            sep_idx = text_so_far.find('\r\n\r\n')
            if sep_idx == -1:
                continue
            head = text_so_far[:sep_idx]
            rest_after_head = len(buf) - (sep_idx + 4)
            head_lines = head.split('\r\n')
            content_length = None
            transfer_encoding = ''
            status_line = head_lines[0]
            for hl in head_lines[1:]:
                kl = ':' in hl
                if kl:
                    hk, hv = hl.split(':', 1)
                    hk_lower = hk.strip().lower()
                    hv = hv.strip()
                    if hk_lower == 'content-length':
                        try:
                            content_length = int(hv)
                        except ValueError:
                            pass
                    elif hk_lower == 'transfer-encoding':
                        transfer_encoding = hv.lower()
                    elif hk_lower == 'location':
                        new_url = hv.strip()
                        # Follow redirect
                        sock.close()
                        return http_get(new_url, timeout=timeout, tok=tok)

            if content_length is not None:
                expected = content_length
                received = rest_after_head
                if received >= expected:
                    # Done
                    body_start = sep_idx + 4
                    return bytes(buf[body_start:body_start + expected])
                else:
                    # Need more
                    need = expected - received
                    # Continue reading until we have enough
                    while True:
                        more = sock.recv(min(need, 16384))
                        if not more:
                            break
                        buf.extend(more)
                        received += len(more)
                        if received >= expected:
                            break
                    body_start = sep_idx + 4
                    return bytes(buf[body_start:body_start + expected])
            elif 'chunked' in transfer_encoding:
                # Read chunked encoding
                body_start = sep_idx + 4
                result = bytearray()
                pos = body_start
                while True:
                    # Find next \r\n from pos to read chunk size line
                    crlf = buf.find(b'\r\n', pos)
                    if crlf == -1:
                        # Need more data
                        more = sock.recv(16384)
                        if not more:
                            break
                        buf.extend(more)
                        continue
                    size_str = buf[pos:crlf].decode('ascii').split(';')[0].strip()
                    if not size_str:
                        # Might be empty terminator; keep waiting
                        more = sock.recv(16384)
                        if not more:
                            break
                        buf.extend(more)
                        continue
                    try:
                        chunk_size = int(size_str, 16)
                    except ValueError:
                        # Could be a continuation line or bad parse; advance
                        pos = crlf + 2
                        continue
                    if chunk_size == 0:
                        # Final chunk; skip trailing \r\n
                        # The two \r\n after 0 are at crlf+2 and crlf+4
                        # We can stop
                        break
                    # Now body starts at crlf+2, length chunk_size, then \r\n
                    body_begin = crlf + 2
                    body_end = body_begin + chunk_size
                    while len(buf) < body_end + 2:
                        more = sock.recv(16384)
                        if not more:
                            break
                        buf.extend(more)
                    if len(buf) >= body_end + 2:
                        result.extend(buf[body_begin:body_end])
                        pos = body_end + 2
                    else:
                        # Incomplete; break
                        result.extend(buf[body_begin:])
                        break
                return bytes(result)
            else:
                # No content-length, no chunked: read to close
                body_start = sep_idx + 4
                # Since Connection: close, when recv returns b'', we're done
                # Keep reading until EOF
                while True:
                    more = sock.recv(16384)
                    if not more:
                        break
                    buf.extend(more)
                return bytes(buf[body_start:])
    finally:
        sock.close()


