    # Determine the exception type name
    # FileNotFoundError is subclass of OSError, but we need to get its __name__
    # Without using type(e).__name__, we can check isinstance or compare class objects
    exc_type = type(e)
    if exc_type is FileNotFoundError:
        type_name = "FileNotFoundError"
    elif exc_type is PermissionError:
        type_name = "PermissionError"
    elif exc_type is IsADirectoryError:
        type_name = "IsADirectoryError"
    elif exc_type is NotADirectoryError:
        type_name = "NotADirectoryError"
    elif exc_type is InterruptedError:
        type_name = "InterruptedError"
    elif exc_type is ConnectionError:
        type_name = "ConnectionError"
    elif exc_type is ChildProcessError:
        type_name = "ChildProcessError"
    elif exc_type is BlockingIOError:
        type_name = "BlockingIOError"
    else:
        type_name = "OSError"

    print("caught", type_name, e.errno)
