import sys

def _safe_repr(obj):
    if isinstance(obj, str):
        s = obj
        result = []
        i = 0
        while i < len(s):
            c = s[i]
            cp = ord(c)
            if cp == 10:
                result.append('\\n')
            elif cp == 13:
                result.append('\\r')
            elif cp == 9:
                result.append('\\t')
            elif cp == 34:
                result.append('\\"')
            elif cp == 39:
                result.append("\\'")
            elif cp == 92:
                result.append('\\\\')
            elif cp >= 32 and cp != 127:
                # printable ASCII or non-ASCII above 31 (except DEL handled below)
                if cp > 127:
                    result.append(c)
                else:
                    result.append(c)
            elif cp == 0:
                result.append('\\0')
            elif cp <= 0xff:
                result.append('\\x%02x' % cp)
            else:
                result.append('\\u%04x' % cp)
            i += 1
        return "'" + ''.join(result) + "'"
    elif isinstance(obj, bytes):
        s = obj
        result = []
        for b in s:
            if b == 10:
                result.append('\\n')
            elif b == 13:
                result.append('\\r')
            elif b == 9:
                result.append('\\t')
            elif b == 34:
                result.append('\\"')
            elif b == 39:
                result.append("\\'")
            elif b == 92:
                result.append('\\\\')
            elif 32 <= b <= 126:
                result.append(chr(b))
            else:
                result.append('\\x%02x' % b)
        return "b'" + ''.join(result) + "'"
    else:
        # Fallback to built-in repr for non-str/non-bytes
        return repr(obj)

# Override the default repr for our formatted strings using a custom formatter
def _fmt_str(s):
    """Format a string with quotes, using safe repr."""
    return _safe_repr(s)

