                result.append('\\x%02x' % code)
        elif code < 128 and (code >= 33 and code <= 126):
            # Printable ASCII
            result.append(ch)
        elif ch == '\xa0':
            # Explicitly represent U+00A0 as \xa0 to avoid relying on repr's unicode tables
            result.append('\\xa0')
        elif code < 0x100:
            # Other latin-1 printable or non-printable - use \x notation for safety? 
