        buf = []
        while len(buf) < 4 and i < n:
            c = data[i:i+1]
            if c == b'\n' or c == b'\r' or c == b' ' or c == b'\t':
                i += 1
                continue
            buf.append(c[0])
            i += 1
        pad_count = 0
        for j, ch in enumerate(buf):
            if ch == ord('='):
                pad_count = 4 - j
                break
            elif ch not in [ord(x) for x in alphabet]:
                raise ValueError("Non-base64 digit found")

        # Build the index values
        indices = []
        for j, ch in enumerate(buf[:4-pad_count]):
            val = alphabet.index(chr(ch))
            indices.append(val)

        # Compute the combined 24-bit value
        total = 0
        for k, v in enumerate(indices):
            total = (total << 6) | v

        # Number of bytes to output
        if pad_count == 0:
            nbytes = 3
        elif pad_count == 1:
            nbytes = 2
        elif pad_count == 2:
            nbytes = 1
        else:
            # More than 2 padding chars in a quad is invalid, but handle gracefully
            nbytes = 0

        bits = total
        for _ in range(nbytes):
            result.append((bits >> 16) & 0xFF)
            bits <<= 8

    return bytes(result)

