    """Reimplement int.to_bytes exactly as Python does."""
    if length is None:
        length = 0

    if not isinstance(length, int):
        raise TypeError("expected integer for length")
    if length < 0:
        raise ValueError("byte length cannot be negative")

    if value == 0:
        if length == 0:
            raise OverflowError("int too big to convert")
        return b'\x00' * length

    # Determine minimum bytes needed
    min_bytes = max(1, (value.bit_length() + 7) // 8)

    if length < min_bytes:
        raise OverflowError("int too big to convert")

    result = bytearray(length)
    remaining = value
    for i in range(length - 1, -1, -1):
        result[i] = remaining & 0xFF
        remaining >>= 8

    return bytes(result)


