def product_repeat(iterable, repeat):
    if repeat < 0:
        return
    pools = [list(iterable) for _ in range(repeat)]
    if not any(pools):
        yield ()
        return
    result = [None] * repeat
    def rec(i):
        if i == repeat:
            yield tuple(result)
            return
        for v in pools[i]:
            result[i] = v
            yield from rec(i + 1)
    yield from rec(0)

