def _prod(iterable, repeat):
    pool = tuple(iterable)
    for L in range(repeat + 1):
        def rec(k, prefix):
            if k == 0:
                yield tuple(prefix)
            else:
                for e in pool:
                    for rest in rec(k - 1, prefix + [e]):
                        yield rest
        yield from rec(L, [])

