def safe_eval(expr):
    """Evaluate an expression without using the built-in eval."""
    # We need to parse and evaluate simple expressions.
    # Since we only have a small set of known expressions, let's handle them
    # with ast module which is standard library.
    import ast

    def eval_node(node):
        if isinstance(node, ast.Expression):
            return eval_node(node.body)
        elif isinstance(node, ast.Call):
            func_name = ast.unparse(node.func) if hasattr(ast, 'unparse') else None
            if hasattr(ast, 'unparse'):
                func_name = ast.unparse(node.func)
            else:
                func_name = node.func.id if isinstance(node.func, ast.Name) else None

            args = []
            for arg in node.args:
                args.append(eval_node(arg))

            keywords = {}
            for kw in node.keywords:
                keywords[kw.arg] = eval_node(kw.value)

            func = ns[func_name] if func_name in ns.builtins_ else None
            if func is None:
                raise ValueError(f"Unknown function: {func_name}")
            return func(*args, **keywords)
        elif isinstance(node, ast.List):
            return [eval_node(elt) for elt in node.elts]
        elif isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.Str):  # Python < 3.8
            return node.s
        elif isinstance(node, ast.Num):  # Python < 3.8
            return node.n
        elif isinstance(node, ast.Bytes):
            return node.s
        elif isinstance(node, ast.Tuple):
            return tuple(eval_node(elt) for elt in node.elts)
        elif isinstance(node, ast.Dict):
            return {eval_node(k): eval_node(v) for k, v in zip(node.keys, node.values)}
        elif isinstance(node, ast.Name):
            return ns[node.id]
        else:
            raise ValueError(f"Unsupported AST node: {type(node).__name__}")

    tree = ast.parse(expr, mode='eval')
    return eval_node(tree)

