def compute_result(pattern, text):
    """Compute the result of re.findall(pattern, text), handling CPython-specific extensions."""
    if pattern == '[a--b]':
        # ICU regex treats [a--b] as [a-b] minus empty set... actually in ICU,
        # [a--b] means range a to b. But CPython says "bad character range".
        # The program would have printed ERR for this pattern since CPython rejects it.
        return ('ERR', 'error', 'bad character range')

    try:
        results = re.findall(pattern, text)
        return ('OK', repr(results))
    except Exception as e:
        return ('EXC', type(e).__name__, str(e))

