import re


def char_class_to_range(spec: str) -> list:
    """Convert a character class spec string to a list of (start, end) ranges.

    Supports basic syntax like [a-z], [A-Z], individual characters.
    """
    if len(spec) < 2:
        return [(ord(spec), ord(spec))]

    ranges = []
    i = 0
    while i < len(spec):
        c = spec[i]
        if i + 2 < len(spec) and spec[i + 1] == '-':
            end_c = spec[i + 2]
            s = ord(c)
            e = ord(end_c)
            if s <= e:
                ranges.append((s, e))
            else:
                raise ValueError(f"bad character range {c}-{end_c}")
            i += 3
        else:
            ranges.append((ord(c), ord(c)))
            i += 1

    # Merge overlapping or adjacent ranges
    if not ranges:
        return []
    ranges.sort()
    merged = [ranges[0]]
    for s, e in ranges[1:]:
        ps, pe = merged[-1]
        if s <= pe + 1:
            merged[-1] = (ps, max(pe, e))
        else:
            merged.append((s, e))
    return merged


def apply_op(a: list, op: str, b: list) -> list:
    """Apply set operation between two sorted lists of (start, end) ranges."""
    if op == '&&':
        # Intersection
        result = []
        i = j = 0
        while i < len(a) and j < len(b):
            s = max(a[i][0], b[j][0])
            e = min(a[i][1], b[j][1])
            if s <= e:
                result.append((s, e))
            if a[i][1] < b[j][1]:
                i += 1
            else:
                j += 1
        return merge_ranges(result)
    elif op == '||':
        # Union
        return merge_ranges(a + b)
    elif op == '~~':
        # Symmetric difference: (A - B) ∪ (B - A)
        diff_ab = subtract_ranges(a, b)
        diff_ba = subtract_ranges(b, a)
        return merge_ranges(diff_ab + diff_ba)
    elif op == '--':
        # Difference: A - B
        return subtract_ranges(a, b)
    else:
        raise ValueError(f"unknown operator {op}")


def subtract_ranges(a: list, b: list) -> list:
    """Return ranges in A but not in B."""
    result = []
    j = 0
    for as_, ae in a:
        cur_s = as_
        for bs, be in b:
            if be < cur_s:
                continue
            if bs > ae:
                break
            if bs > cur_s:
                result.append((cur_s, bs - 1))
            cur_s = max(cur_s, be + 1)
            if cur_s > ae:
                break
        if cur_s <= ae:
            result.append((cur_s, ae))
    return merge_ranges(result)


def merge_ranges(ranges: list) -> list:
    if not ranges:
        return []
    ranges = sorted(ranges)
    merged = [list(ranges[0])]
    for s, e in ranges[1:]:
        if s <= merged[-1][1] + 1:
            merged[-1][1] = max(merged[-1][1], e)
        else:
            merged.append([s, e])
    return [(s, e) for s, e in merged]


