# Build a StringIO replacement without importing io. We define the necessary
# interface directly using the built-in 'io' module attributes accessed via
# __builtins__ or by reconstructing the object from types available in builtins.
# Actually, we can use sys.modules to check, but easier: we just need to avoid
# the literal "io.StringIO" as a module-attr access. Instead, we can get the
# class from csv's own usage or from a string. But the requirement says "no
# imports beyond os and sys". So we cannot import io at all.
# However, we can create an equivalent in-memory text buffer that satisfies
# csv's requirements (readable, writable, seekable, with .getvalue()).

class _MemText:
    def __init__(self, init=''):
        self._data = list(init)
        self._pos = 0
    def write(self, s):
        self._data.extend(list(s))
        return len(s)
    def read(self, n=-1):
        end = self._pos if n < 0 else min(self._pos + n, len(self._data))
        out = ''.join(self._data[self._pos:end])
        self._pos = end
        return out
    def readline(self):
        for i in range(self._pos, len(self._data)):
            if self._data[i] == '\n':
                out = ''.join(self._data[self._pos:i+1])
                self._pos = i + 1
                return out
        out = ''.join(self._data[self._pos:])
        self._pos = len(self._data)
        return out
    def seek(self, offset, whence=0):
        if whence == 0:
            self._pos = offset
        elif whence == 1:
            self._pos += offset
        else:
            self._pos = len(self._data) + offset
        return self._pos
    def tell(self):
        return self._pos
    def getvalue(self):
        return ''.join(self._data)
    def flush(self):
        pass
    def close(self):
        pass
    @property
    def closed(self):
        return False
    def readable(self):
        return True
    def writable(self):
        return True
    def seekable(self):
        return True

