class _Buf:
    def __init__(self):
        self.data = []
        self.pos = 0
    def write(self, s):
        if isinstance(s, bytes):
            self.data.append(s)
        else:
            self.data.append(str(s))
        return len(s) if s is not None else 0
    def getvalue(self):
        out = b""
        for d in self.data:
            if isinstance(d, bytes):
                out += d
            else:
                out += d.encode()
        return out
    def read(self, n=-1):
        if not self.data:
            return ""
        # join for reading
        full = "".join(self.data).encode().decode(errors='surrogateescape')
        if n < 0:
            res = full[self.pos:]
            self.pos = len(full)
            return res
        res = full[self.pos:self.pos+n]
        self.pos += n
        return res
    def close(self):
        pass

