# Reproduce StringIO functionality for the specific uses in this program
class FakeStringIO:
    def __init__(self, initial=""):
        self._value = str(initial)

    def getvalue(self):
        return self._value

    # For writer: we need to collect what's written
    def write(self, s):
        self._value += s
        return len(s)

    def close(self):
        pass

    def read(self, size=-1):
        return self._value

    def iter(self):
        # Simulate iteration over lines
        lines = self._value.split('\n')
        if lines and lines[-1] == '':
            lines.pop()
        for line in lines:
            yield line + '\n' if not line.endswith('\r\n') else line
            # Actually, let's be more careful
            # The csv reader expects to iterate over lines
            # Let's just yield each line with its newline preserved
        return
        yield from ()

    # Better approach for iter
    def __iter__(self):
        value = self._value
        idx = 0
        while idx < len(value):
            # Find next newline
            nl = value.find('\n', idx)
            if nl == -1:
                yield value[idx:]
                break
            else:
                yield value[idx:nl+1]
                idx = nl + 1

