import os, sys

class StringIO:
    def __init__(self, s=""):
        self._s = s if isinstance(s, str) else ""
        self._pos = 0

    def getvalue(self):
        return self._s

    def write(self, s):
        self._s += s
        self._pos = len(self._s)

    def read(self, n=-1):
        if n == -1 or n >= len(self._s) - self._pos:
            data = self._s[self._pos:]
            self._pos = len(self._s)
        else:
            data = self._s[self._pos:self._pos+n]
            self._pos += n
        return data

    def readline(self, size=None):
        start = self._pos
        idx = self._s.find("\n", start)
        if idx == -1:
            line = self._s[start:]
            self._pos = len(self._s)
        else:
            end = idx + 1
            line = self._s[start:end]
            self._pos = end
        if size is not None and size > 0:
            return line[:size]
        return line

    def seek(self, pos, whence=0):
        if whence == 0:
            self._pos = pos
        elif whence == 1:
            self._pos += pos
        elif whence == 2:
            self._pos = len(self._s) + pos
        return self._pos

    def tell(self):
        return self._pos

    def close(self):
        pass


def csv_writer_write(writer_state, row, **kwargs):
    delimiter = writer_state.get("delimiter", ",")
    quotechar = writer_state.get("quotechar", '"')
    quoting = writer_state.get("quoting", 0)  # QUOTE_MINIMAL
    lineterminator = writer_state.get("lineterminator", "\r\n")

    def escape_field(field):
        field_str = str(field)
        if quoting == 1:  # QUOTE_ALL
            return quotechar + field_str.replace(quotechar, quotechar*2) + quotechar
        else:  # QUOTE_MINIMAL
            needs_quote = False
            for c in field_str:
                if c == delimiter or c == quotechar or c == '\r' or c == '\n':
                    needs_quote = True
                    break
            if needs_quote:
                return quotechar + field_str.replace(quotechar, quotechar*2) + quotechar
            else:
                return field_str

    parts = []
    for i, field in enumerate(row):
        parts.append(escape_field(field))

    return delimiter.join(parts) + lineterminator


def W(row, **kw):
    o = StringIO()
    result_line = csv_writer_write(kw, row)
    o.write(result_line)
    return (o.getvalue(), None)


