class LineSrc:
    """Mimics an iterable over lines from a string with newline='' semantics."""
    __slots__ = ('lines', 'idx')
    def __init__(self, data, newline=''):
        # Split into lines keeping the line terminators
        self.lines = []
        if not data:
            pass
        else:
            i = 0
            n = len(data)
            while i < n:
                j = i
                while j < n and data[j] not in ('\r', '\n'):
                    j += 1
                if j >= n:
                    self.lines.append(data[i:j])
                elif data[j] == '\r':
                    if j + 1 < n and data[j+1] == '\n':
                        self.lines.append(data[i:j+2])
                        j += 2
                    else:
                        self.lines.append(data[i:j+1])
                        j += 1
                else:
                    self.lines.append(data[i:j+1])
                    j += 1
                i = j
        self.idx = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.idx >= len(self.lines):
            raise StopIteration
        l = self.lines[self.idx]
        self.idx += 1
        return l

