import csv, sys


class _StringIO:
    """A minimal StringIO replacement for use with csv module."""
    def __init__(self, initial_value=''):
        self._data = initial_value
        self._pos = 0

    def write(self, s):
        # For writing, append and keep track
        self._data = self._data[:self._pos] + s + self._data[self._pos:]
        return len(s)

    def read(self, n=-1):
        if n == -1:
            result = self._data[self._pos:]
            self._pos = len(self._data)
            return result
        else:
            result = self._data[self._pos:self._pos+n]
            self._pos += n
            return result

    def readline(self, n=-1):
        if self._pos >= len(self._data):
            return ''
        remaining = self._data[self._pos:]
        if n == -1:
            nl_pos = remaining.find('\n')
            if nl_pos == -1:
                result = remaining
                self._pos = len(self._data)
            else:
                result = remaining[:nl_pos+1]
                self._pos += nl_pos+1
            return result
        else:
            end = min(n, len(remaining))
            nl_pos = remaining.find('\n', 0, end)
            if nl_pos != -1 and nl_pos < end:
                result = remaining[:nl_pos+1]
                self._pos += nl_pos+1
            else:
                result = remaining[:end]
                self._pos += end
            return result

    def getvalue(self):
        return self._data

    def close(self):
        pass

    def __iter__(self):
        return self

    def __next__(self):
        line = self.readline()
        if not line:
            raise StopIteration
        return line


