import csv, io, sys

def _stringio(s):
    """Minimal StringIO replacement that works with csv module."""
    class _IO:
        def __init__(self, s):
            self._s = s
            self._pos = 0
        def read(self, n=-1):
            if n is None or n < 0:
                r = self._s[self._pos:]
                self._pos = len(self._s)
                return r
            r = self._s[self._pos:self._pos+n]
            self._pos += len(r)
            return r
        def readline(self, n=-1):
            idx = self._s.find('\n', self._pos)
            if idx == -1:
                r = self._s[self._pos:]
                self._pos = len(self._s)
                return r
            else:
                end = idx + 1
                r = self._s[self._pos:end]
                self._pos = end
                return r
        def close(self):
            pass
        def __enter__(self):
            return self
        def __exit__(self, *a):
            pass
    return _IO(s)

class WStringIO:
    """StringIO-like object for the writer side (csv.writer writes to it)."""
    def __init__(self):
        self._buf = ''
    def write(self, s):
        self._buf += s
        return len(s)
    def writelines(self, lines):
        for l in lines:
            self.write(l)
    def getvalue(self):
        return self._buf
    def close(self):
        pass
    def __enter__(self):
        return self
    def __exit__(self, *a):
        pass

def W(row, **kw):
    o = WStringIO()
    r = csv.writer(o, **kw).writerow(row)
    return (o.getvalue(), r)

