        def quote_field(f):
            s = str(f)
            if f is None:
                s = ""
            elif isinstance(f, float):
                if f == int(f) and abs(f) < 1e16:
                    # Python repr of float
                    s = repr(f)
                else:
                    s = repr(f)
            else:
                s = str(f)

            needs_quote = False
            if quoting == QUOTE_ALL:
                needs_quote = True
            else:
                if delimiter in s or '\n' in s or '\r' in s or s.startswith('"') or s.endswith('"'):
                    needs_quote = True

            if needs_quote:
                return '"' + s.replace('"', '""') + '"'
            return s

