results = []


def safe_eval(expr):
    # Parse the expression and evaluate it manually
    if expr.startswith('math.'):
        func_name = expr[5:]
        args_str = func_name.split('(')[1]
        func_name = func_name.split('(')[0]

        # Parse arguments
        if not args_str.strip():
            args = []
        else:
            args = parse_args(args_str)

        try:
            if func_name == 'floor':
                return math.floor(*args)
            elif func_name == 'ceil':
                return math.ceil(*args)
            elif func_name == 'trunc':
                return math.trunc(*args)
            elif func_name == 'isqrt':
                return math.isqrt(*args)
            elif func_name == 'factorial':
                return math.factorial(*args)
            elif func_name == 'sqrt':
                return math.sqrt(*args)
            elif func_name == 'gcd':
                return math.gcd(*args)
            elif func_name == 'fabs':
                return math.fabs(*args)
            else:
                raise Exception(f"Unknown function: {func_name}")
        except Exception as ex:
            raise ex
    else:
        raise Exception(f"Cannot parse: {expr}")


def parse_args(s):
    s = s.strip()
    if not s:
        return []

    args = []
    current = ''
    depth = 0

    for c in s:
        if c == '(' :
            depth += 1
            current += c
        elif c == ')':
            depth -= 1
            current += c
        elif c == ',' and depth == 0:
            args.append(current.strip())
            current = ''
        else:
            current += c

    if current.strip():
        args.append(current.strip())

    parsed_args = []
    for a in args:
        parsed_args.append(parse_value(a))

    return parsed_args


def parse_value(s):
    s = s.strip()
    if s == 'float("nan")':
        return float('nan')
    elif s == 'float("inf")':
        return float('inf')
    elif s == 'float("-inf")':
        return float('-inf')
    elif s == '"a"':
        return 'a'
    elif s == '-1':
        return -1
    elif s == '4.0':
        return 4.0
    elif s == '1.0':
        return 1.0
    elif s == '1':
        return 1
    elif s == '2':
        return 2
    else:
        # Try to parse as number or string
        if s.startswith('"') and s.endswith('"'):
            return s[1:-1]
        else:
            # Try int, then float
            try:
                return int(s)
            except ValueError:
                return float(s)


