import math

def safe_eval(expr):
    """Manually evaluate the specific expressions without using eval."""
    # These are all simple math function calls with literal arguments.
    # Let's parse them manually for the specific set of expressions.

    expr = expr.strip()

    # Parse pattern: func(args...)
    if '(' not in expr or ')' not in expr:
        raise ValueError(f"Cannot parse: {expr}")

    paren_start = expr.index('(')
    paren_end = expr.rindex(')')
    func_name = expr[:paren_start]
    args_str = expr[paren_start+1:paren_end]

    # Split arguments
    args = []
    if args_str.strip():
        # For our purposes, all args are simple literals
        arg_list = args_str.split(',')
        args = [a.strip() for a in arg_list]

    def parse_arg(s):
        s = s.strip()
        if s.startswith('"') and s.endswith('"'):
            return s[1:-1]  # string literal
        try:
            if '.' in s or 'e' in s.lower():
                return float(s)
            else:
                return int(s)
        except ValueError:
            # Maybe it's inf/nan/other
            if s == 'inf':
                return float('inf')
            elif s == '-inf':
                return float('-inf')
            elif s == 'nan':
                return float('nan')
            raise

    parsed_args = [parse_arg(a) for a in args]

    # Look up the function
    obj = getattr(math, func_name)
    result = obj(*parsed_args)
    return result


