def tokenize(s):
    i = 0
    tokens = []
    while i < len(s):
        c = s[i]
        if c.isspace():
            i += 1
        elif c.isdigit() or (c == '-' and (i + 1 < len(s) and s[i+1].isdigit())):
            j = i
            if c == '-':
                j += 1
            while j < len(s) and s[j].isdigit():
                j += 1
            num_str = s[i:j]
            try:
                num = int(num_str)
            except ValueError:
                num = float(num_str)
            tokens.append(('NUM', num))
            i = j
        elif c == '+' :
            j = i + 1
            while j < len(s) and s[j].isdigit():
                j += 1
            num_str = s[i:j]
            try:
                num = int(num_str)
            except ValueError:
                num = float(num_str)
            tokens.append(('NUM', num))
            i = j
        elif c in '+-*/()':
            tokens.append((c, c))
            i += 1
        elif c == '.':
            tokens.append(('.', '.'))
            i += 1
        elif c.isalpha() or c == '_':
            j = i
            while j < len(s) and (s[j].isalnum() or s[j] == '_'):
                j += 1
            word = s[i:j]
            tokens.append(('NAME', word))
            i = j
        elif c == '"':
            j = i + 1
            buf = []
            while j < len(s) and s[j] != '"':
                if s[j] == '\\':
                    j += 1
                    if j < len(s):
                        buf.append(s[j])
                else:
                    buf.append(s[j])
                j += 1
            tokens.append(('STR', ''.join(buf)))
            i = j + 1
        else:
            tokens.append(('ERR', c))
            i += 1
    return tokens


