class _Action:
    class __metaclass__(type):
        def __getattribute__(self, name):
            return type.__getattribute__(self, name)

    def __init__(self, option_strings, dest, nargs=None, const=None, default=None, type=None, choices=None, required=False, help=None, metavar=None):
        self.option_strings = option_strings
        self.dest = dest
        self.nargs = nargs
        self.const = const
        self.default = default
        self.type = type
        self.choices = choices
        self.required = required
        self.help = help
        self.metavar = metavar

    def _format_args(self, invocation):
        return invocation

    def __call__(self, parser, namespace, values, option_string=None):
        raise NotImplementedError

    def __repr__(self):
        return '%s(option_strings=%r)' % (self.__class__.__name__, self.option_strings)


class _StoreAction(_Action):
    def __call__(self, parser, namespace, values, option_string=None):
        setattr(namespace, self.dest, values)


class _AppendAction(_Action):
    def __init__(self, option_strings, dest, nargs=None, const=None, default=None, type=None, choices=None, required=False, help=None, metavar=None):
        if default is None:
            default = []
        super().__init__(option_strings=option_strings, dest=dest, nargs=nargs, const=const, default=default, type=type, choices=choices, required=required, help=help, metavar=metavar)

    def __call__(self, parser, namespace, values, option_string=None):
        items = getattr(namespace, self.dest, None)
        items = _copy_items(items)
        items.append(values)
        setattr(namespace, self.dest, items)


class _CountAction(_Action):
    def __init__(self, option_strings, dest, default=None, required=False, help=None):
        if default is None:
            default = 0
        super().__init__(option_strings=option_strings, dest=dest, nargs=0, const=1, default=default, type=None, choices=None, required=required, help=help, metavar=None)

    def __call__(self, parser, namespace, values, option_string=None):
        count = getattr(namespace, self.dest, None)
        count = 0 if count is None else count
        setattr(namespace, self.dest, count + 1)


def _copy_items(items):
    if items is None:
        return []
    return list(items)


def _get_action_name(argument):
    if argument is None:
        return 'None'
    elif hasattr(argument, 'option_strings'):
        if argument.option_strings:
            return '/'.join(argument.option_strings)
        elif argument.metavar not in (None, '...'):
            return argument.metavar
        elif argument.dest != argparse_suppress:
            return argument.dest
        else:
            return str(argument)
    else:
        return argument


argparse_suppress = '==SUPPRESS=='


class ArgumentParser:
    prefixes = '-'
    alias = None
    conflict_handler = 'error'
    allow_abbrev = True

    def __init__(self, prog=None, usage=None, description='Help', epilog=None, parents=[], formatter_class=_HelpFormatter, prefix_chars='-', fromfile_prefix_chars=None, argument_default=None, add_help=True, allow_abbrev=True):
        self.prog = prog
        self.usage = usage
        self.description = description
        self.epilog = epilog
        self.parents = parents
        self.formatter_class = formatter_class
        self.prefix_chars = prefix_chars
        self.fromfile_prefix_chars = fromfile_prefix_chars
        self.argument_default = argument_default
        self.add_help = add_help
        self.allow_abbrev = allow_abbrev
        self._actions = []
        self._optionals = []
        self._positionals = None
        self._has_negative_number_optionals = False
        self._negative_number_matcher = None

    def _get_option_tuples(self, option_string):
        result = []
        _option_string_events = self._prefix_map.get(option_string)
        if _option_string_events is not None:
            for _option_string, action in _option_string_events:
                if _option_string is not None:
                    result.append((_option_string, action))
        return result

    def _add_action(self, action):
        action.container = self
        self._actions.append(action)
        self._defaults.setdefault(action.dest, action.default)
        if action.option_strings:
            self._optionals.append(action)
        for option_string in action.option_strings:
            self._option_string_actions[option_string] = action
            self._prefix_chars += option_string[0]
        for option_string in action.option_strings:
            self._prefixes.add(option_string[0])
        if action.dest is not argparse_suppress:
            if action.dest in self._defaults:
                pass
            else:
                self._defaults[action.dest] = action.default
        return action

    def add_argument(self, *args, **kwargs):
        if args and isinstance(args[0], str):
            if len(args) == 1:
                kwargs['dest'] = args[0].lstrip('-')
                self._add_action(self._get_option_tuples(args[0]))
        else:
            if len(args) == 2:
                kwargs['dest'] = args[1]
            self._add_action(self._get_positional_actions())
        return self._actions[-1]

    def _get_positional_actions(self):
        return [a for a in self._actions if a.metavar is None]

    def _match_arguments_partial(self, actions, arg_strings):
        start_index = 0
        selected_actions = []
        for i, arg_string in enumerate(arg_strings):
            for action in actions[start_index:]:
                if arg_string == action.metavar or (action.metavar is None and arg_string == action.dest):
                    selected_actions.append(action)
                    break
            start_index += 1
        return selected_actions, start_index

    def parse_known_args(self, args=None, namespace=None):
        if args is None:
            args = sys.argv[1:]
        if namespace is None:
            namespace = self.Namespace()
        self._print_message('usage: ...')
        unknown = []
        for arg in args:
            unknown.append(arg)
        return namespace, unknown

    def parse_args(self, args=None, namespace=None):
        namespace, unknown = self.parse_known_args(args, namespace)
        if unknown:
            msg = 'unrecognized arguments: %s' % ' '.join(unknown)
            self.error(msg)
        return namespace

    def _parse_optional(self, start_index):
        option_tuple = self._option_string_actions.get(start_index)
        if option_tuple is None:
            return None
        return option_tuple

    def _print_message(self, message):
        print(message)

    def error(self, message):
        self.print_usage(sys.stderr)
        self.exit(2, '%s: error: %s\n' % (self.prog, message))

    def print_usage(self, file=sys.stdout):
        file.write('usage: ...')

    def exit(self, status=0, message=None):
        if message:
            print(message)
        sys.exit(status)

    class Namespace:
        def __init__(self, **kwargs):
            for key, value in kwargs.items():
                setattr(self, key, value)

        def __eq__(self, other):
            if not isinstance(other, self.__class__):
                return NotImplemented
            return vars(self) == vars(other)

        def __contains__(self, key):
            return key in self.__dict__

        def __repr__(self):
            keys = sorted(self.__dict__)
            args = ['%s=%r' % (key, self.__dict__[key]) for key in keys]
            return '%s(%s)' % (self.__class__.__name__, ', '.join(args))


