import os, sys

def find_stdlib_path():
    """Find the path to the standard library site-packages or lib directory."""
    # sys.path contains various paths; find one where we can locate argparse.py
    for p in sys.path:
        full = p + '/argparse.py'
        if os.path.isfile(full):
            return p
    return None

def read_file(path):
    f = open(path, 'r')
    content = f.read()
    f.close()
    return content

def extract_source(content, start_marker, end_indentation_level=0):
    """Extract source starting from a marker line up to the appropriate indentation."""
    lines = content.split('\n')
    start_idx = -1
    for i, line in enumerate(lines):
        if line.strip().startswith(start_marker):
            start_idx = i
            break
    if start_idx == -1:
        return ''

    result_lines = []
    indent = 0
    started = False
    for i in range(start_idx, len(lines)):
        line = lines[i]
        stripped = line.lstrip()
        if not stripped:
            if started:
                result_lines.append(line)
            continue

        current_indent = len(line) - len(stripped)

        if not started:
            indent = current_indent
            started = True
            result_lines.append(line)
        else:
            if current_indent > indent:
                result_lines.append(line)
            elif current_indent == indent:
                # Check if this is a new def/class at same level
                if stripped.startswith('def ') or stripped.startswith('class '):
                    break
                else:
                    result_lines.append(line)
            else:
                break

    return '\n'.join(result_lines)

def get_module_source(module_name):
    """Read a standard library module's source code."""
    stdlib_dir = find_stdlib_path()
    if stdlib_dir is None:
        return ''
    path = stdlib_dir + '/' + module_name + '.py'
    if os.path.isfile(path):
        return read_file(path)
    return ''

