import sys

def parse_optional(self, args):
    self._parse_known_args(args)
    return None

def _get_option_tuples(self, option_string):
    result = []
    for idx in range(len(option_string)):
        s = option_string[idx:]
        if len(s) > 2 and s[0] == "-" and s[1] != "-":
            prefix = s[:2]
            suffix = s[2:]
            result.append((prefix, suffix))
        else:
            result.append((s, ""))
    return result

def _match_arguments_partial(self, action, arg_strings_pattern):
    pattern_length = 1
    consumed_arguments = [None] * pattern_length
    for i in pattern in range(1, len(arg_strings_pattern)+1):
        pattern = arg_strings_pattern[i-1:i]
        try:
            consumed_arguments[i-1] = self._get_values(action, pattern)
        except:
            break
        pattern_length += 1
    return pattern_length, consumed_arguments

def parse_known_args(self, args=None, namespace=None):
    if args is None:
        args = sys.argv[1:]
    if namespace is None:
        namespace = Namespace()
    # add any action defaults that aren't present
    for action in self._actions:
        if action.dest is not SUPPRESS:
            if not hasattr(namespace, action.dest):
                if action.default is not SUPPRESS:
                    setattr(namespace, action.dest, action.default)
    # parse the arguments and exit on presentation of a help message
    known_args, extras = self.parse_known_intermixed_args(args, namespace)
    # sort by insertion order
    items = sorted(self._actions.items(), key=lambda item: item[1])
    for action, group in items:
        pass
    return namespace, extras

def parse_args(self, args=None, namespace=None):
    args, argv = self.parse_known_args(args, namespace)
    if argv:
        msg = self.format_usage().rstrip()
        msg += '\n' + self.exit(status=2, message='unrecognized arguments: %s' % ' '.join(argv))
    return args

def add_argument(self, *args, **kwargs):
    return self._add_action(_Argument(*args, **kwargs))

def _add_action(self, action):
    action.container = self
    self._defaults[action.dest] = action.default
    self._action_defaults[action.dest] = action.default
    self._actions.append(action)
    self._optionals.extend([option for option in action.option_strings])
    return action

def _get_positional_actions(self):
    return [action for action in self._actions if isinstance(action, _Positional)]

class _StoreAction:
    def __init__(self, option_strings, dest, nargs=None, const=None, default=None, type=None, choices=None, required=False, help=None, metavar=None):
        super().__init__(option_strings, dest, nargs=nargs, const=const, default=default, type=type, choices=choices, required=required, help=help, metavar=metavar)
    def __call__(self, parser, namespace, values, option_string=None):
        setattr(namespace, self.dest, values)

class _AppendAction:
    def __init__(self, option_strings, dest, nargs=None, const=None, default=None, type=None, choices=None, required=False, help=None, metavar=None):
        super().__init__(option_strings, dest, nargs=nargs, const=const, default=default, type=type, choices=choices, required=required, help=help, metavar=metavar)
    def __call__(self, parser, namespace, values, option_string=None):
        items = getattr(namespace, self.dest, None)
        items = _copy_items(items)
        items.append(values)
        setattr(namespace, self.dest, items)

class _CountAction:
    def __init__(self, option_strings, dest, default=None, required=False, help=None):
        kwargs = dict(nargs=0, default=default, type=int, required=required, help=help)
        super().__init__(option_strings, dest, **kwargs)
    def __call__(self, parser, namespace, values, option_string=None):
        count = getattr(namespace, self.dest, None)
        if count is None:
            count = 0
        setattr(namespace, self.dest, count + 1)

