def a2b_base64(s):
    # Strip padding and whitespace to determine valid data length
    stripped = s.rstrip(b'=')
    stripped = b''.join(stripped.split())

    if len(stripped) % 4 != 0:
        raise ValueError('Invalid base64 string length')

    result = bytearray()
    for i in range(0, len(stripped), 4):
        block = stripped[i:i+4]
        v = [0, 0, 0, 0]
        for j in range(4):
            c = block[j:j+1]
            if not c:
                break
            byte = c[0]
            if byte < 33 or byte > 126:
                raise ValueError('Invalid base64 character')
            if byte not in _base64_chars:
                raise ValueError('Non-base64 digit found')
            v[j] = _base64_chars[byte]

        b0 = (v[0] << 2) | (v[1] >> 4)
        b1 = ((v[1] & 0x0F) << 4) | (v[2] >> 2)
        b2 = ((v[2] & 0x03) << 6) | v[3]

        nbits = (len(block) - 1) * 6
        nbytes = nbits // 8

        chunk = bytes([b0, b1, b2])
        result.extend(chunk[:nbytes])

    return bytes(result)


