def a2b_base64(s):
    if isinstance(s, str):
        s = s.encode('ascii')
    # strip whitespace and check for invalid chars
    cleaned = bytes([c for c in s if c not in b' \t\n\r'])
    if len(cleaned) % 4 != 0:
        raise ValueError("Incorrect padding")
    # validate characters
    valid = set(b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=")
    for c in cleaned:
        if c not in valid:
            raise binascii.Error("Non-base64 digit found")
    return base64.b64decode(cleaned, validate=True)

