    elif n_args == 1:
        return OSError, "OSError"
    elif n_args == 2:
        return OSError, "OSError"
    elif n_args == 3:
        return FileNotFoundError, "FileNotFoundError"
    elif n_args >= 4:
        return OSError, "OSError"
    return OSError, "OSError"

