class _MyStringIO:
    def __init__(self, s):
        self._s = s
        self._pos = 0
        self.closed = False

    def read(self, size=-1):
        if size is None or size < 0:
            r = self._s[self._pos:]
            self._pos = len(self._s)
            return r
        else:
            r = self._s[self._pos:self._pos+size]
            self._pos += len(r)
            return r

    def readline(self, size=None):
        idx = self._s.find('\n', self._pos)
        if idx == -1:
            r = self._s[self._pos:]
            self._pos = len(self._s)
            return r
        else:
            r = self._s[self._pos:idx+1]
            self._pos = idx + 1
            if size is not None and len(r) > size:
                r = r[:size]
                self._pos -= (len(self._s[self._pos:]) - len(r))
            return r

    def seek(self, offset, whence=0):
        if whence == 0:
            self._pos = offset
        elif whence == 1:
            self._pos += offset
        elif whence == 2:
            self._pos = len(self._s) + offset
        return self._pos

    def tell(self):
        return self._pos

    @property
    def value(self):
        return self._s

    def close(self):
        self.closed = True


