class _StringIO:
    def __init__(self, s):
        self._s = s
        self._pos = 0

    def read(self, n=None):
        if n is None:
            res = self._s[self._pos:]
            self._pos = len(self._s)
            return res
        else:
            res = self._s[self._pos:self._pos + n]
            self._pos += len(res)
            return res

    def readline(self, n=None):
        if self._pos >= len(self._s):
            return ''
        end = self._s.find('\n', self._pos)
        if end == -1:
            line = self._s[self._pos:]
            self._pos = len(self._s)
        else:
            line = self._s[self._pos:end + 1]
            self._pos = end + 1
        if n is not None and len(line) > n:
            overflow = line[n:]
            line = line[:n]
            self._pos -= len(overflow)
        return line

    def close(self):
        pass

    def __enter__(self):
        return self

    def __exit__(self, *args):
        pass


