import csv

class _FakeIO:
    def __init__(self, data):
        self._data = data
        self._pos = 0
        self._lines = None
        self._line_idx = 0

    def read(self, size=None):
        if size is None:
            result = self._data[self._pos:]
            self._pos = len(self._data)
            return result
        else:
            end = min(self._pos + size, len(self._data))
            result = self._data[self._pos:end]
            self._pos = end
            return result

    def readline(self, size=None):
        if self._pos >= len(self._data):
            return ''
        if size is None:
            # find next newline
            nl = self._data.find('\n', self._pos)
            if nl == -1:
                result = self._data[self._pos:]
                self._pos = len(self._data)
            else:
                result = self._data[self._pos:nl+1]
                self._pos = nl+1
            return result
        else:
            end = min(self._pos + size, len(self._data))
            nl = self._data.find('\n', self._pos, end)
            if nl != -1 and nl < end:
                end = nl + 1
            result = self._data[self._pos:end]
            self._pos = end
            return result

    def __iter__(self):
        return self

    def __next__(self):
        line = self.readline()
        if not line:
            raise StopIteration
        return line


