import operator

def safe_eval(code):
    """Evaluate a simple expression involving % formatting or format() calls."""
    code = code.strip()

    # Pattern 1: 'format(2.0,"d")' -> ('2.0', 'd')
    if code.startswith('format(') and code.endswith(')'):
        inner = code[7:-1]
        # Split by the comma that separates arguments at top level
        depth = 0
        in_string = False
        string_char = None
        split_idx = -1
        for i, ch in enumerate(inner):
            if in_string:
                if ch == string_char:
                    in_string = False
            else:
                if ch in ('"', "'"):
                    in_string = True
                    string_char = ch
                elif ch == '(':
                    depth += 1
                elif ch == ')':
                    depth -= 1
                elif ch == ',' and depth == 0:
                    split_idx = i
                    break
        if split_idx == -1:
            raise ValueError("No comma found")
        arg1 = inner[:split_idx].strip()
        arg2 = inner[split_idx+1:].strip()

        # Parse arg1 (a number or string)
        if arg1.startswith('"') or arg1.startswith("'"):
            val = arg1[1:-1]
        else:
            val = float(arg1)

        # Parse arg2 (a string)
        fmt_spec = arg2[1:-1]

        return format(val, fmt_spec)

    # Pattern 2: '"%d" % 2.7'
    # Find the % operator between two operands
    percent_idx = code.find('%')
    if percent_idx != -1 and not code.startswith('format'):
        left = code[:percent_idx].strip()
        right = code[percent_idx+1:].strip()

        # left should be a string literal like "%d"
        if left.startswith('"') or left.startswith("'"):
            fmt_str = left[1:-1]
        else:
            raise ValueError("Expected string literal on left of %")

        # Parse right operand
        if right.startswith('"') or right.startswith("'"):
            val = right[1:-1]
        elif right.startswith('['):
            val = [x.strip() for x in right[1:-1].split(',')]
            try:
                val = [int(x) for x in val]
            except ValueError:
                pass
        elif right.lower() == 'none':
            val = None
        elif right.lower() == 'true':
            val = True
        elif right.lower() == 'false':
            val = False
        elif right.startswith('float('):
            inner_right = right[6:-1]
            if inner_right.lower() == 'nan':
                import math
                val = float('nan')
            elif inner_right.lower() == 'inf':
                import math
                val = float('inf')
            else:
                val = float(inner_right)
        else:
            try:
                val = int(right)
            except ValueError:
                try:
                    val = float(right)
                except ValueError:
                    val = right

        return fmt_str % val

    raise ValueError("Cannot parse: " + code)


