def safe_eval_expression(expr):
    """Evaluate simple expressions without using eval."""
    # Handle "%d" % value and similar
    # Handle format(value, spec) and "{:spec}".format(value)

    # Patterns:
    # 1. '"<fmt>" % <value>'
    # 2. 'format(<value>, "<spec>")'
    # 3. '"{: <spec>}".format(<value>)' or '"{:<spec>}".format(<value>)'

    # Let's parse based on the specific cases we know about

    # Case 1: percent formatting
    if expr.startswith('"') and ('%' in expr) and not expr.startswith('format'):
        # Extract format string and value expression
        # Find the closing quote of the format string
        q1 = expr.index('"', 1) + 1  # position after first opening quote
        # Actually let's find it properly
        # expr looks like: '"%d" % 2.7'
        # Find the second " which closes the format string
        close_q = expr.index('"', 1)
        fmt_str = expr[1:close_q]
        rest = expr[close_q+1:].strip()

        # rest should be something like: % 2.7
        if not rest.startswith('%'):
            return None

        val_expr = rest[1:].strip()

        # Parse the value expression
        value = parse_value(val_expr)

        # Apply percent formatting
        try:
            result = (fmt_str % value)
            return repr(result)
        except Exception as e:
            return "%s: %s" % (type(e).__name__, e)

    # Case 2: format(value, spec)
    if expr.startswith('format('):
        # Extract arguments
        inner = expr[7:-1]  # remove 'format(' and ')'
        # Split by comma at top level
        # But we need to be careful with nested quotes
        parts = split_args(inner)
        if len(parts) == 2:
            val_expr = parts[0].strip()
            spec = parts[1].strip().strip('"').strip("'")
            value = parse_value(val_expr)
            try:
                result = format(value, spec)
                return repr(result)
            except Exception as e:
                return "%s: %s" % (type(e).__name__, e)

    # Case 3: "{:spec}".format(value)
    if '.format(' in expr and expr.endswith(')'):
        # Extract the format string part before .format(
        dot_idx = expr.rfind('.format(')
        fmt_part = expr[:dot_idx]
        # Should look like: '"{:d}"'
        fmt_str = fmt_part.strip().strip('"').strip("'")

        # Extract the argument
        arg_start = dot_idx + 8  # length of '.format('
        arg_end = len(expr) - 1  # before final )
        val_expr = expr[arg_start:arg_end].strip()

        value = parse_value(val_expr)

        # Apply str.format
        try:
            result = (fmt_str).format(value)
            return repr(result)
        except Exception as e:
            return "%s: %s" % (type(e).__name__, e)

    return None


def split_args(s):
    """Split a string by commas at the top level, respecting quotes and parens."""
    parts = []
    depth = 0
    in_str = False
    quote_char = ''
    current = []

    for ch in s:
        if in_str:
            current.append(ch)
            if ch == quote_char and (len(current) == 1 or current[-2] != '\\'):
                in_str = False
        else:
            if ch in ('"', "'"):
                in_str = True
                quote_char = ch
                current.append(ch)
            elif ch == '(':
                depth += 1
                current.append(ch)
            elif ch == ')':
                depth -= 1
                current.append(ch)
            elif ch == ',' and depth == 0:
                parts.append(''.join(current))
                current = []
            else:
                current.append(ch)

    if current:
        parts.append(''.join(current))

    return parts


def parse_value(expr):
    """Parse a simple Python value expression."""
    expr = expr.strip()

    # Handle float("nan"), float("inf")
    if expr.startswith('float('):
        inner = expr[6:-1]  # remove float( and )
        inner_val = inner.strip()
        if inner_val == '"nan"' or inner_val == "'nan'":
            import math
            return float('nan')
        elif inner_val == '"inf"' or inner_val == "'inf'":
            return float('inf')
        else:
            return float(inner_val)

    # Handle negative zero: -0.0
    if expr == '-0.0':
        return -0.0

    # Handle scientific notation
    if 'e' in expr.lower():
        try:
            return float(expr)
        except:
            pass

    # Handle integer literals
    try:
        return int(expr)
    except:
        pass

    # Handle float literals
    try:
        return float(expr)
    except:
        pass

    # Handle None
    if expr == 'None':
        return None

    # Handle strings
    if (expr.startswith('"') and expr.endswith('"')) or \
       (expr.startswith("'") and expr.endswith("'")):
        return expr[1:-1]

    # Handle lists like [1]
    if expr.startswith('[') and expr.endswith(']'):
        inner = expr[1:-1].strip()
        return [parse_value(x) for x in inner.split(',')]

    # Handle booleans
    if expr == 'True':
        return True
    if expr == 'False':
        return False

    # Fallback: try int/float again
    try:
        return int(expr)
    except:
        pass
    try:
        return float(expr)
    except:
        pass

    raise ValueError("Cannot parse: %s" % expr)


