import re

def eval_expression(expr):
    # Pattern 1: 'string_format_spec' % value
    # Matches a string literal followed by % and a value
    m = re.match(r"^\"(.*)\"\s*%\s*(.*)$", expr)
    if m:
        fmt_str = m.group(1)
        val_str = m.group(2).strip()

        # Parse the value
        val = parse_value(val_str)
        return fmt_str % val

    # Pattern 2: format(value, "format_spec")
    # Matches format( ... ) with two arguments
    m = re.match(r"^format\((.*),\s*\"(.*)\"\)$", expr)
    if m:
        val_str = m.group(1).strip()
        fmt_str = m.group(2)

        # Parse the value
        val = parse_value(val_str)
        return format(val, fmt_str)

    raise ValueError(f"Unsupported expression pattern: {expr}")

def parse_value(s):
    s = s.strip()

    # Check for float('inf'), -float('inf'), float('nan')
    if s == "float(\"inf\")":
        return float("inf")
    elif s == "-float(\"inf\")":
        return float("-inf")
    elif s == "float(\"nan\")":
        return float("nan")

    # Check for other quoted strings (e.g., "a")
    if s.startswith('"') and s.endswith('"'):
        return s[1:-1]

    # Check for None
    if s == "None":
        return None

    # Check for True/False
    if s == "True":
        return True
    if s == "False":
        return False

    # Check for lists (simple case [1])
    if s.startswith('[') and s.endswith(']'):
        inner = s[1:-1].strip()
        # Handle simple integer list
        try:
            return [parse_value(item.strip()) for item in inner.split(',')]
        except:
            pass

    # Try int
    try:
        # If it looks like an integer (possibly with sign)
        if re.match(r'^-?\d+$', s):
            return int(s)
        # If it looks like a float
        elif re.match(r'^-?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$', s):
            return float(s)
    except:
        pass

    # Fallback: try float generally
    try:
        return float(s)
    except:
        pass

    raise ValueError(f"Cannot parse value: {s}")

