def parse_value(s):
    s = s.strip()
    if s == 'None':
        return None
    if s == 'True':
        return True
    if s == 'False':
        return False
    if s.startswith('float(') and s.endswith(')'):
        inner = s[len('float('):-1].strip()
        if inner.lower() == 'nan':
            return float('nan')
        if inner.lower() == 'inf':
            return float('inf')
        if inner.lower() == '-inf':
            return float('-inf')
        return None
    if s.startswith('"') or s.startswith("'"):
        return s  # Keep as string representation, handle specially
    if s.startswith('[') and s.endswith(']'):
        return s  # List representation
    # Numbers
    try:
        if '.' in s or 'e' in s.lower():
            return float(s)
        else:
            return int(s)
    except ValueError:
        pass

    # If it looks like a string literal
    if len(s) >= 2 and s[0] == s[-1] and s[0] in ('"', "'"):
        content = s[1:-1]
        # Handle escape sequences
        return unescape_string(content)

    return None


def unescape_string(s):
    result = []
    i = 0
    while i < len(s):
        if s[i] == '\\' and i + 1 < len(s):
            next_char = s[i+1]
            if next_char == 'n':
                result.append('\n')
                i += 2
            elif next_char == 't':
                result.append('\t')
                i += 2
            elif next_char == '\\':
                result.append('\\')
                i += 2
            elif next_char == "'":
                result.append("'")
                i += 2
            elif next_char == '"':
                result.append('"')
                i += 2
            else:
                result.append(s[i])
                i += 1
        else:
            result.append(s[i])
            i += 1
    return ''.join(result)


def split_args(s):
    parts = []
    depth = 0
    current = []
    i = 0
    while i < len(s):
        c = s[i]
        if c == '(' or c == '[' or c == '{':
            depth += 1
        elif c == ')' or c == ']' or c == '}':
            depth -= 1
        elif c == ',' and depth == 0:
            parts.append(''.join(current))
            current = []
            i += 1
            continue
        current.append(c)
        i += 1
    if current:
        parts.append(''.join(current))
    return parts


