    if s.startswith('[') and s.endswith(']'):
        inner = s[1:-1].strip()
        items = [x.strip() for x in inner.split(',')] if inner else []
        return [_parse_value(i) for i in items]

    # Number
    try:
        return int(s)
    except ValueError:
        pass

    try:
        return float(s)
    except ValueError:
        pass

    raise NameError("cannot parse: " + s)


