# Build a safe evaluator using ast and restricted execution
def safe_eval(expr):
    """Safely evaluate simple Python expressions without eval()"""
    try:
        tree = ast.parse(expr, mode='eval')

        class SafeEvaluator(ast.NodeVisitor):
            def visit_Expression(self, node):
                return self.visit(node.body)

            def visit_Constant(self, node):
                return node.value

            def visit_Num(self, node):
                if isinstance(node.n, int):
                    return node.n
                elif isinstance(node.n, float):
                    return node.n
                else:
                    raise ValueError(f"Unsupported numeric type: {type(node.n)}")

            def visit_Str(self, node):
                return node.s

            def visit_Name(self, node):
                # Allow access to builtins we need
                names = {
                    'float': float,
                    'True': True,
                    'False': False,
                    'None': None,
                    'format': format,
                }
                if node.id in names:
                    return names[node.id]
                raise NameError(f"name '{node.id}' is not defined")

            def visit_UnaryOp(self, node):
                operand = self.visit(node.operand)
                op = node.op
                if isinstance(op, ast.USub):
                    return -operand
                elif isinstance(op, ast.UAdd):
                    return +operand
                elif isinstance(op, ast.Not):
                    return not operand
                raise ValueError(f"Unsupported unary operator: {ast.dump(op)}")

            def visit_BinOp(self, node):
                left = self.visit(node.left)
                right = self.visit(node.right)
                op = node.op
                if isinstance(op, ast.Mult):
                    return left * right
                elif isinstance(op, ast.Add):
                    return left + right
                elif isinstance(op, ast.Sub):
                    return left - right
                elif isinstance(op, ast.Div):
                    return left / right
                elif isinstance(op, ast.Mod):
                    return left % right
                raise ValueError(f"Unsupported binary operator: {ast.dump(op)}")

            def visit_Call(self, node):
                func = self.visit(node.func)
                args = [self.visit(a) for a in node.args]
                kwargs = [ast.keyword(arg=ast.Name(id=kw.arg), value=self.visit(kw.value)) for kw in node.keywords]

                # Handle float conversion
                if func == float:
                    if len(args) == 1 and not kwargs:
                        val = args[0]
                        if isinstance(val, str):
                            return float(val)
                        elif isinstance(val, (int, float)):
                            return float(val)
                        else:
                            raise TypeError(f"float() argument must be a string or a number, not '{type(val).__name__}'")
                    raise TypeError(f"float() got unexpected arguments")

                # Handle format function
                if func == format:
                    if len(args) == 2 and not kwargs:
                        obj = args[0]
                        spec = args[1]
                        return format(obj, spec)
                    raise TypeError(f"format() expected 2 arguments, got {len(args) + len(kwargs)}")

                raise ValueError(f"Unsupported function call: {ast.dump(node.func)}")

            def visit_Attribute(self, node):
                obj = self.visit(node.value)
                attr_name = node.attr

                # Handle .format() method calls on strings
                if attr_name == 'format' and isinstance(obj, str):
                    return obj.format

                raise AttributeError(f"'{type(obj).__name__}' object has no attribute '{attr_name}'")

            def visit_Index(self, node):
                return self.visit(node.value)

            def visit_Tuple(self, node):
                return tuple(self.visit(e) for e in node.elts)

            def visit_List(self, node):
                return [self.visit(e) for e in node.elts]

            def generic_visit(self, node):
                raise ValueError(f"Unsupported AST node: {ast.dump(node)}")

        return SafeEvaluator().visit(tree)
    except Exception as e:
        raise e

