def safe_eval(code):
    # This function uses ast to evaluate limited expressions
    import ast

    class Evaluator(ast.NodeVisitor):
        def __init__(self):
            self.env = {}

        def visit_Name(self, node):
            if node.id in ('float', 'format'):
                return getattr(builtins, node.id)
            else:
                raise ValueError("Unknown name: %s" % node.id)

        def visit_Constant(self, node):
            return node.value

        def visit_BinOp(self, node):
            left = self.visit(node.left)
            right = self.visit(node.right)
            if isinstance(node.op, ast.Mod):
                return left % right
            elif isinstance(node.op, ast.Pow):
                return left ** right
            elif isinstance(node.op, ast.Add):
                return left + right
            elif isinstance(node.op, ast.Sub):
                return left - right
            elif isinstance(node.op, ast.Mult):
                return left * right
            elif isinstance(node.op, ast.Div):
                return left / right
            elif isinstance(node.op, ast.FloorDiv):
                return left // right
            else:
                raise ValueError("Unsupported binary op")

        def visit_UnaryOp(self, node):
            operand = self.visit(node.operand)
            if isinstance(node.op, ast.USub):
                return -operand
            elif isinstance(node.op, ast.UAdd):
                return +operand
            else:
                raise ValueError("Unsupported unary op")

        def visit_Call(self, node):
            func = self.visit(node.func)
            args = [self.visit(a) for a in node.args]
            keywords = {kw.arg: self.visit(kw.value) for kw in node.keywords}
            if hasattr(func, '__call__'):
                return func(*args, **keywords)
            else:
                raise ValueError("Not callable")

        def visit_IfExp(self, node):
            cond = self.visit(node.test)
            if cond:
                return self.visit(node.body)
            else:
                return self.visit(node.orelse)

    tree = ast.parse(code, mode='eval')
    ev = Evaluator()
    result = ev.visit(tree.body)
    return result

