def _base64_decode(data, validate_pad=True, strict_padding=True):
    """Pure-Python equivalent of base64.b64decode(data)."""
    import re
    # First, filter out non-base64 characters. The standard library's
    # b64decode ignores non-alphabet characters (like newlines) by default.
    # We need to check padding correctly.

    # Remove all characters not in the alphabet or '='
    cleaned = bytearray()
    for c in data:
        if 0x41 <= c <= 0x5A:  # A-Z
            cleaned.append(c)
        elif 0x61 <= c <= 0x7A:  # a-z
            cleaned.append(c)
        elif 0x30 <= c <= 0x39:  # 0-9
            cleaned.append(c)
        elif c == 0x2B:  # +
            cleaned.append(c)
        elif c == 0x2F:  # /
            cleaned.append(c)
        elif c == 0x3D:  # =
            cleaned.append(c)
        else:
            # Ignore other characters (newlines, spaces, etc.)
            pass

    # Now check padding: '=' should only appear at the end
    last_non_pad = -1
    for i in range(len(cleaned)):
        if cleaned[i] != 0x3D:
            last_non_pad = i

    # Check that all '=' are at the end
    for i in range(last_non_pad + 1, len(cleaned)):
        if cleaned[i] != 0x3D:
            raise ValueError("Invalid padding")

    # Count pads
    num_pads = len(cleaned) - (last_non_pad + 1)

    # The number of base64 chars before padding must be multiple of 4 when padded,
    # or we just have n chars where n % 4 is in {0, 2, 3}
    total_b64_chars = len(cleaned)
    non_pad_chars = last_non_pad + 1

    if total_b64_chars > 0 and non_pad_chars % 4 == 1:
        raise ValueError("Invalid base64 string length")

    # Decode
    ALPHA = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    idx = {c: i for i, c in enumerate(ALPHA)}

    acc = 0
    bits = 0
    out = bytearray()

    for c in cleaned:
        if c == 0x3D:
            break
        acc = (acc << 6) | idx[c]
        bits += 6
        if bits >= 8:
            bits -= 8
            out.append((acc >> bits) & 0xFF)

    return bytes(out)


