def _product(iterable, repeat=1):
    pools = [tuple(iterable)] * repeat
    result = [[]]
    for pool in pools:
        new_result = []
        for item in result:
            for x in pool:
                new_result.append(item + [x])
        result = new_result
    for r in result:
        yield r

