import base64, sys

def _source_of(fn):
    try:
        file = fn.__code__.co_filename
        lines, index = _lines_index(file)
    except Exception:
        return "  <could not retrieve source>"
    if index is None:
        return "  <could not retrieve source>"
    indent_width = None
    for ln in range(index - 1, len(lines)):
        line = lines[ln]
        stripped = line.lstrip()
        if not stripped or stripped.startswith('#'):
            continue
        cur_indent = len(line) - len(stripped)
        if indent_width is None:
            indent_width = cur_indent
        elif cur_indent > indent_width:
            break
        else:
            if cur_indent < indent_width:
                lines = lines[:index] + [line.rstrip('\n')]
            else:
                lines[index:] = lines[index:]
            break
    # Collect the function body (from index onward until dedent to function level)
    out_lines = []
    func_indent = None
    for ln in range(index, min(index + 200, len(lines))):
        line = lines[ln]
        stripped = line.lstrip()
        if not stripped:
            out_lines.append(line.rstrip('\n'))
            continue
        cur_indent = len(line) - len(stripped)
        if func_indent is None:
            func_indent = cur_indent
        if cur_indent < func_indent and func_indent is not None:
            break
        out_lines.append(line.rstrip('\n'))
    # Trim trailing blank lines
    while out_lines and not out_lines[-1].strip():
        out_lines.pop()
    result = '\n'.join(out_lines)
    if result.endswith('\n'):
        result = result[:-1]
    return result

def _lines_index(path):
    import tokenize as _tk
