def is_word_char(c):
    """Check if character is a word character (equivalent to Python's \\w)."""
    # Python's \\w in Unicode mode: [a-zA-Z0-9_] plus any character with
    # Unicode category Lu, Ll, Lt, Lm, Lo, Mn, Mc, Nd, Pc
    code = ord(c)
    if c == '_':
        return True
    if 'a' <= c <= 'z' or 'A' <= c <= 'Z' or '0' <= c <= '9':
        return True
    # Check other Unicode categories using unicodedata
    import unicodedata
    cat = unicodedata.category(c)
    return cat in ('Lu', 'Ll', 'Lt', 'Lm', 'Lo', 'Mn', 'Mc', 'Nd', 'Pc')


def sub_nonword(s, replacement='-'):
    """Equivalent of re.sub(r'\\W+', replacement, s)"""
    result = []
    i = 0
    n = len(s)
    while i < n:
        if not is_word_char(s[i]):
            j = i
            while j < n and not is_word_char(s[j]):
                j += 1
            result.append(replacement)
            i = j
        else:
            result.append(s[i])
            i += 1
    return ''.join(result)


