# Actually, let's build a minimal character class checker.
def _category(code):
    # Return a rough category; sufficient for common Latin/German text
    # Digits: 0x30-0x39
    if 0x30 <= code <= 0x39:
        return 'Nd'
    # Uppercase A-Z
    if 0x41 <= code <= 0x5A:
        return 'Lu'
    # Lowercase a-z
    if 0x61 <= code <= 0x7A:
        return 'Ll'
    # Underscore already handled
    # Common accented Latin characters (Latin Extended-A and some others)
    if _in_accented_ranges(code):
        return 'Ll' if code >= 0xE1 else 'Lu'
    # Other letters — fallback: consider as letter if it looks alphabetic
    if _is_general_letter(code):
        return 'Ll'
    # General punctuation like hyphen-minus
    if code in (0x2D, 0x2010, 0x2011, 0x2012, 0x2013, 0x2014, 0x2015):
        return 'Pd'
    # Space
    if code == 0x20:
        return 'Zs'
    # Default
    return 'Po'


def _in_accented_ranges(code):
    # Å å Ä ä Ö ö etc., plus Ö in Swedish words
    # Latin-1 Supplement letters: 0xC0-0xFF excluding a few non-letter positions
    if 0xC0 <= code <= 0xDF:
        return True  # uppercase accented
    if 0xE0 <= code <= 0xFF:
        return True  # lowercase accented
    # Latin Extended-A: 0x100-0x17F
    if 0x100 <= code <= 0x17F:
        return True
    return False


def _is_general_letter(code):
    # Broader letter detection for cases not caught above
    # This is a fallback; for the given inputs the accented ranges cover everything needed.
    # Greek, Cyrillic, etc. could be added here but are not needed.
    return False


