def _make_cm(fn):
    class C:
        def __enter__(self):
            gen = fn()
            try:
                self._v1 = next(gen)
            except StopIteration:
                raise TypeError("generator didn't yield")
            return self._v1

        def __exit__(self, etype, evalue, tb):
            if etype is None:
                try:
                    next(self._gen)
                    return False
                except StopIteration:
                    pass
                return True
            else:
                try:
                    self._gen.throw(etype, evalue, tb)
                    raise RuntimeError("@contextmanager generator didn't stop after throw()")
                except StopIteration as si:
                    if si is not evalue and (etype is None or evalue is None):
                        return False
                    if (si is evalue) or (etype is not None and evalue is not None and si.args == (evalue,)):
                        return True
                    # suppress exception
                    import sys
                    raise
                except BaseException as new_exc:
                    if new_exc is evalue:
                        return True
                    import sys
                    raise

    def wrapper(*args, **kwargs):
        cm = C()
        cm._gen = fn(*args, **kwargs)
        return cm

    return wrapper


