    # First, strip non-alphabet chars unless validate is truthy
    if validate:
        # In strict mode, check that all characters are valid base64
        valid_chars = set(b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=')
