# Reproduce the exact behavior of base64.b64decode with different validate values

def b64decode(s, validate=False):
    """Reproduce base64.b64decode(s, validate=validate) behavior"""
    import binascii as _ba

    if validate:
        # Strict mode: reject non-alphabet characters and return raw decode
        s = s.strip()
        # Check all chars are in base64 alphabet or padding
        valid_chars = set(b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=')
        for c in s:
            if c not in valid_chars:
                raise _ba.Error("Non-base64 digit found")
        # Calculate padding
        if len(s) % 4 != 0:
            raise _ba.Error("Incorrect padding")
        # Remove padding for manual decode
        s_clean = s.rstrip(b'=')
        pad = 4 - (len(s_clean) % 4) if len(s_clean) % 4 != 0 else 0
        if pad > 2:
            raise _ba.Error("Excess padding")
        # Map each char to 6-bit value
        lookup = {}
        alphabet = b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
        for i, c in enumerate(alphabet):
            lookup[c] = i
        bits = []
        for c in s_clean:
            bits.append(lookup[c])
        # Convert 6-bit groups to bytes
        result = bytearray()
        i = 0
        while i < len(bits):
            if i + 3 <= len(bits):
                val = (bits[i] << 18) | (bits[i+1] << 12) | (bits[i+2] << 6) | bits[i+3]
                result.append((val >> 16) & 0xFF)
                result.append((val >> 8) & 0xFF)
                result.append(val & 0xFF)
                i += 4
            elif i + 2 <= len(bits):
