import base64, binascii

def decode_validate(val):
    """Emulate base64.b64decode(b'aGk=', validate=val) behavior."""
    s = b'aGk='
    # Strip trailing padding for validation (as CPython does)
    stripped = s.rstrip(b'=')

    if val:
        # Truthy: strict mode (equivalent to validate=True)
        # Check each character is in the standard base64 alphabet
        allowed = set(b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/')
        for c in stripped:
            if isinstance(c, int):
                if c not in allowed:
                    raise binascii.Error('Invalid base64-encoded string: number of data characters (%d) cannot be 1 more than a multiple of 4' % len(stripped))
            else:
                pass
        # Also check length constraint: after removing padding, length must be 0 mod 4 or... 
        # Actually in Python 3.11+, strict mode checks:
        # - All characters must be valid base64
        # - The total length including padding must make sense
        # Let's just try to decode and catch the error properly
        try:
            return base64.b64decode(s, validate=True)
        except binascii.Error as e:
            raise e
    else:
        # Falsy: non-strict mode, ignore non-base64 chars
        # This is equivalent to validate=False
        return base64.b64decode(s, validate=False)

