import binascii

def _b64decode(data, validate=False):
    # Mirror the CPython base64.b64decode logic exactly.
    if not isinstance(data, (bytes, bytearray)):
        raise TypeError("argument 1 must be bytes or buffer")
    if data is None:
        return b''
    n = len(data)
    if validate and validate is not False and validate is not 0:
        validate_val = True
    else:
        validate_val = bool(validate)

    s = bytes(data)
    if validate_val:
        try:
            binascii.a2b_base64(s, strict_mode=True)
        except (binascii.Error, TypeError) as e:
            raise binascii.Error(str(e))
        try:
            return binascii.a2b_base64(s, strict_mode=True)
        except (binascii.Error, TypeError) as e:
            raise binascii.Error(str(e))
    else:
        # Strip non-alphabet characters
        cleaned = []
        for c in s:
            if 0x30 <= c <= 0x39:      # 0-9
                cleaned.append(c)
            elif 0x41 <= c <= 0x5A:    # A-Z
                cleaned.append(c)
            elif 0x61 <= c <= 0x7A:    # a-z
                cleaned.append(c)
            elif c == 0x2B:            # +
                cleaned.append(c)
            elif c == 0x2F:            # /
                cleaned.append(c)
            elif c == 0x3D:            # =
                cleaned.append(c)
            elif c == 0x0A or c == 0x0D or c == 0x20 or c == 0x09:
                continue
            else:
                pass  # silently skip per non-validate mode behavior

        cleaned_bytes = bytes(cleaned)
        try:
            return binascii.a2b_base64(cleaned_bytes)
        except (binascii.Error, TypeError) as e:
            raise binascii.Error(str(e))


