# Inline textwrap-like behavior for the specific call used:
# textwrap.wrap(t, 80, break_long_words=False, break_on_hyphens=False)

def _wrap(t, width=80, break_long_words=False, break_on_hyphens=False):
    # Simple word-wrap that only breaks on whitespace (spaces/tabs/newlines),
    # preserving the line structure from newline characters.
    # The text does not contain tabs; it may contain newlines? No, each value is a single string without explicit newlines (they're all one line in the dict).
    # But to be safe, split by newlines first, then wrap each paragraph.

    paragraphs = t.split('\n')
    result = []
    for para in paragraphs:
        words = para.split()
        if not words:
            continue
        current = ""
        for word in words:
            if len(word) > width and not break_long_words:
                # If a single word exceeds width, just put it on its own line
                # (textwrap with break_long_words=False would still emit the word alone)
                if current:
                    result.append(current)
                    current = ""
                result.append(word)
            elif current == "":
                current = word
            else:
                test = current + " " + word
                if len(test) <= width:
                    current = test
                else:
                    result.append(current)
                    current = word
        if current:
            result.append(current)
    return result


