def wrap(text, width, break_long_words=False, break_on_hyphens=False):
    if width <= 0:
        return []
    words = text.split()
    lines = []
    cur = ""
    for w in words:
        if not cur:
            cur = w
        else:
            trial = cur + " " + w
            if len(trial) <= width:
                cur = trial
            else:
                # cannot fit in current line; must start new line
                lines.append(cur)
                if break_long_words and len(w) > width:
                    while w:
                        chunk = w[:width]
                        lines.append(chunk)
                        w = w[width:]
                    cur = ""
                elif break_on_hyphens:
                    # try to split on last hyphen before width
                    cut = None
                    for i in range(width - 1, 0, -1):
                        if w[i] == '-':
                            cut = i
                            break
                    if cut is not None:
                        lines.append(w[:cut])
                        cur = w[cut + 1:]
                    else:
                        if len(w) > width and not break_long_words:
                            # word longer than width, place it alone
                            lines.append("")
                            lines.append(w)
                            cur = ""
                        else:
                            cur = w
                else:
                    # no splitting at all
                    if len(w) > width:
                        lines.append(w)
                    else:
                        cur = w
    if cur:
        lines.append(cur)
    return lines


