import re


class RegexFlag:
    def __init__(self, value):
        self.value = value

    def __and__(self, other):
        if isinstance(other, RegexFlag):
            return self.value & other.value
        return self.value & other

    def __repr__(self):
        return f"RegexFlag({self.value})"


# Define flag constants
I = RegexFlag(2)
M = RegexFlag(8)
U = RegexFlag(32)
S = RegexFlag(16)
L = RegexFlag(64)


def compile(pattern, flags=0):
    # Create a simple pattern object
    class Pattern:
        def __init__(self, pattern, flags):
            self.pattern = pattern
            self.flags = flags

        def match(self, string, pos=0, endpos=None):
            import re as _re
            real_pattern = _re.compile(self.pattern, self.flags)
            return real_pattern.match(string, pos, endpos)

        def fullmatch(self, string, pos=0, endpos=None):
            import re as _re
            real_pattern = _re.compile(self.pattern, self.flags)
            return real_pattern.fullmatch(string, pos, endpos)

        def findall(self, string, pos=0, endpos=None):
            import re as _re
            real_pattern = _re.compile(self.pattern, self.flags)
            return real_pattern.findall(string, pos, endpos)

        def split(self, string, maxsplit=0):
            import re as _re
            real_pattern = _re.compile(self.pattern, self.flags)
            return real_pattern.split(string, maxsplit=maxsplit)

    if isinstance(flags, RegexFlag):
        flag_value = flags.value
    else:
        flag_value = flags

    return Pattern(pattern, flag_value)


# Now compute the expressions
flags1 = I.value | M.value  # 2 | 8 = 10
pattern1 = compile('a', flags1)
result1 = pattern1.flags & I.value  # 10 & 2 = 2

pattern2 = compile('a')
result2 = pattern2.flags & I.value  # 0 & 2 = 0

pattern3 = compile('a', I.value)  # flags = 2
result3 = (pattern3.flags == I.value | U.value)  # 2 == 34? No, False

result4 = 34 & I.value  # 34 & 2 = 2
result5 = I.value & 34  # 2 & 34 = 2
result6 = type(result4).__name__  # 'int'

pattern_empty = compile('')
result7 = pattern_empty.match('abc', 2, 1)
result8 = pattern_empty.fullmatch('abc', 2, 1)
result9 = pattern_empty.findall('abc', 2, 1)
result10 = pattern_empty.split('abc')

print(result1, result2, result3, result4, result5, result6)
print(result7, result8, result9, result10)

import re


def regexflag_repr(flag):
    name_map = {0: 'REGEX_FLAG_NONE', 1: 'IGNORECASE', 2: 'LOCALE', 4: 'MULTILINE', 8: 'DOTALL', 16: 'UNICODE', 32: 'VERBOSE', 256: 'DEBUG'}
    if isinstance(flag, int):
        names = []
        for value, name in sorted(name_map.items(), key=lambda kv: (kv[0] == 0, kv[0])):
            if value == 0:
                if flag == 0:
                    names.append(name)
                    break
                continue
            if value & flag:
                names.append(name)
        return '<RegexFlag.' + '|'.join(names) + '>'
    elif isinstance(flag, re.RegexFlag):
        return '<RegexFlag.' + flag.name + '>'
    else:
        raise TypeError('bad repr object')


