import json, os, sys

def _fetch(url):
    host = url.split("/", 3)[2]
    path = "/" + url.split("/", 3)[3] if "/" in url.split("/", 3)[3] else "/"
    try:
        s = __import__("socket").create_connection((host, 80), timeout=60)
    except Exception as e:
        raise OSError(str(e))
    req = "GET %s HTTP/1.1\r\nHost: %s\r\nConnection: close\r\nUser-Agent: python-stdlib-compat\r\n\r\n" % (path, host)
    s.sendall(req.encode())
    data = b""
    while True:
        chunk = s.recv(65536)
        if not chunk:
            break
        data += chunk
    s.close()
    # Parse headers and body
    sep = data.find(b"\r\n\r\n")
    if sep == -1:
        sep = data.find(b"\n\n")
        if sep == -1:
            return data
        head, body = data[:sep], data[sep + 2:]
    else:
        head, body = data[:sep], data[sep + 4:]
    # Check for chunked transfer encoding
    lower_head = head.lower().decode("iso-8859-1")
    if "transfer-encoding: chunked" in lower_head:
        # Decode chunked
        result = b""
        idx = 0
        while idx < len(body):
            line_end = body.find(b"\r\n", idx)
            if line_end == -1:
                line_end = body.find(b"\n", idx)
                if line_end == -1:
                    break
                size_str = body[idx:line_end].strip()
                idx = line_end + 1
            else:
                size_str = body[idx:line_end].strip()
                idx = line_end + 2
            if not size_str:
                continue
            try:
                chunk_size = int(size_str.split(b";")[0], 16)
            except ValueError:
                break
            if chunk_size == 0:
                break
            result += body[idx:idx + chunk_size]
            idx += chunk_size
            # Skip trailing CRLF after chunk
            if idx < len(body) and body[idx:idx+2] == b"\r\n":
                idx += 2
            elif idx < len(body) and body[idx:idx+1] == b"\n":
                idx += 1
        return result
    else:
        return body

