import json,re,os

def safe_glob(pattern):
    base, sub = os.path.split(pattern)
    if not sub:
        return []
    parts = base.split(os.sep)
    # walk the fixed part of the path first
    current = '.'
    for i in range(len(parts)):
        candidate = os.path.join(current, parts[i]) if i > 0 else parts[i]
        # if this segment contains a wildcard, list matching dirs/files
        if '*' in parts[i] or '?' in parts[i]:
            # list directory entries at 'current' level
            try:
                entries = sorted(os.listdir(current))
            except OSError:
                return []
            import re as _re
            rx = _re.translate(parts[i])
            matches = [e for e in entries if _re.fullmatch(rx, e)]
            out = [os.path.join(candidate, m) for m in matches]
            # continue building under each match with remaining segments
            remaining = parts[i+1:]
            result = []
            for o in out:
                if not remaining:
                    # it's a file/directory at final level? we still have to match 'sub'
                    result.append(o)
                else:
                    res2 = _recurse(o, remaining, sub)
                    result.extend(res2)
            return result
        else:
            # ensure existence and is dir (unless last piece which might be file pattern but no wildcard here)
            if not os.path.isdir(candidate):
                return []
            current = candidate
    # now match the final sub component against current dir
    try:
        entries = sorted(os.listdir(current))
    except OSError:
        return []
    import re as _re
    rx = _re.translate(sub)
    matches = [e for e in entries if _re.fullmatch(rx, e)]
    return [os.path.join(current, m) for m in matches]


def _recurse(base, segments, final_sub):
    import re as _re
    if not segments:
        try:
            entries = sorted(os.listdir(base))
        except OSError:
            return []
        rx = _re.translate(final_sub)
        matches = [e for e in entries if _re.fullmatch(rx, e)]
        return [os.path.join(base, m) for m in matches]
    seg = segments[0]
    rest = segments[1:]
    if '*' in seg or '?' in seg:
        try:
            entries = sorted(os.listdir(base))
        except OSError:
            return []
        rx = _re.translate(seg)
        matches = [e for e in entries if _re.fullmatch(rx, e)]
        out = []
        for m in matches:
            candidate = os.path.join(base, m)
            if os.path.isdir(candidate):
                out.extend(_recurse(candidate, rest, final_sub))
        return out
    else:
        candidate = os.path.join(base, seg)
        if not os.path.isdir(candidate):
            return []
        return _recurse(candidate, rest, final_sub)


