import base64, inspect

def get_source(obj):
    """Get the source of a function/object without using inspect.getsource on module attributes."""
    try:
        import types
        if isinstance(obj, types.FunctionType):
            import linecache
            filename = obj.__code__.co_filename
            start_line = obj.__code__.co_firstlineno
            # Read the file and extract the function
            with open(filename, 'r') as f:
                lines = f.readlines()

            # Find the end of the function by dedentation
            result = []
            in_function = False
            func_indent = None

            for i in range(start_line - 1, len(lines)):
                line = lines[i]
                stripped = line.lstrip()

                if not in_function:
                    if stripped.startswith('def ') or stripped.startswith('async def '):
                        result.append(line)
                        in_function = True
                        # Determine the indentation level of the def
                        indent = len(line) - len(stripped)
                        func_indent = indent
                else:
                    if not stripped:
                        result.append(line)
                    elif (len(line) - len(stripped)) > func_indent:
                        result.append(line)
                    else:
                        break

            return ''.join(result)
        elif isinstance(obj, types.ModuleType):
            import linecache
            lines = linecache.getlines(obj.__file__)
            return ''.join(lines)
        else:
            raise TypeError("Cannot get source for %s" % type(obj))
    except Exception as e:
        raise

