class FakePath:
    """Minimal path implementation that replicates pathlib.Path behavior for the given inputs."""
    def __init__(self, s):
        # Normalize the string: collapse multiple slashes, remove trailing slashes (except root)
        # We store the original and a normalized version
        self._orig = s
        # Handle empty string -> '.'
        if s == '':
            self._path = '.'
        else:
            # Split by '/' and rejoin, removing empty parts except for leading
            parts = s.split('/')
            if s.startswith('/'):
                self._is_abs = True
                new_parts = [p for p in parts if p != '' or len(parts)==1]
                # For absolute paths, keep at least one component after the root
                while new_parts and new_parts[0] == '':
                    new_parts.pop(0)
                self._path = '/' + '/'.join(new_parts) if new_parts else '/'
            else:
                self._is_abs = False
                new_parts = [p for p in parts if p != '']
                if not new_parts:
                    self._path = '.'
                else:
                    self._path = '/'.join(new_parts)
        self._compute_parts()

    def _compute_parts(self):
        self._parts = ()
        p = self._path
        if p in ('.', ''):
            self._parts = ()
        elif p == '..':
            self._parts = ('..',)
        elif p.startswith('/'):
            comps = p.lstrip('/').split('/')
            self._parts = tuple(c for c in comps if c != '')
        else:
            comps = p.split('/')
            self._parts = tuple(c for c in comps if c != '')

    @property
    def name(self):
        if not self._parts:
            return ''
        return self._parts[-1]

    @property
    def suffix(self):
        n = self.name
        if not n:
            return ''
        if n == '.':
            return ''
        # Find the last dot that's not at position 0
        idx = n.rfind('.')
        if idx <= 0:
            return ''
        return n[idx:]

    @property
    def stem(self):
        n = self.name
        if not n:
            return ''
        if n == '.':
            return ''
        idx = n.rfind('.')
        if idx <= 0:
            return n
        return n[:idx]

    def with_name(self, newname):
        # Replace the last part
        if self._is_abs:
            # Absolute path: replace name in parent directory
            if len(self._parts) > 1:
                parent = '/' + '/'.join(self._parts[:-1])
                # Join parent and newname
                if newname.startswith('/'):
                    result = newname
                elif parent.endswith('/'):
                    result = parent + newname
                else:
                    result = parent + '/' + newname
            else:
                # Path is just a single component under root like /foo
                result = '/' + newname
        else:
            # Relative path
            if len(self._parts) > 1:
                parent = '/'.join(self._parts[:-1])
                if newname.startswith('/'):
                    result = newname
                else:
                    result = parent + '/' + newname
            elif len(self._parts) == 1:
                result = newname
            else:
                # Path is '.' or empty
                if newname.startswith('/'):
                    result = newname
                else:
                    result = newname

        return FakePath(result)

    def with_suffix(self, newsuf):
        # Remove old suffix and add new one
        n = self.name
        if not n:
            # If name is empty, we need to handle this case
            # For '.', name is '', so we can't really do anything meaningful
            # pathlib raises ValueError for some cases
            if self._path in ('.',):
                raise ValueError("Cannot change suffix of empty path")
            result_str = self._path
            return FakePath(result_str)

        # Remove old suffix
        idx = n.rfind('.')
        if idx > 0:
            stem_part = n[:idx]
        else:
            stem_part = n

        if newsuf:
            if not newsuf.startswith('.'):
                newsuf = '.' + newsuf
            newname = stem_part + newsuf
        else:
            newname = stem_part

        return self.with_name(newname)

    def with_stem(self, newstem):
        n = self.name
        if not n:
            if self._path in ('.',):
                raise ValueError("Cannot change stem of empty path")
            result_str = self._path
            return FakePath(result_str)

        old_suf = self.suffix
        if newstem:
            newname = newstem + old_suf
        else:
            newname = old_suf

        return self.with_name(newname)

    def __str__(self):
        return self._path


def path_to_string(s):
    """Convert a path string to what str(Path(s)) would return, matching pathlib behavior."""
    # We need to replicate exactly how pathlib normalizes paths
    # The key behaviors:
    # - Empty string becomes '.'
    # - Multiple consecutive slashes are collapsed
    # - Trailing slash removed (unless root)
    # - Root stays as '/'
    # - Single dots removed from components
    # - Parent references ('..') preserved but not resolved

    p = s
    if p == '':
        return '.'

    # Determine if absolute
    is_abs = p.startswith('/')

    # Split into components
    parts = p.split('/')

    # Filter out empty strings, but be careful with root
    new_parts = []
    for part in parts:
        if part == '' or part == '.':
            continue
        new_parts.append(part)

    if is_abs:
        if not new_parts:
            return '/'
        return '/' + '/'.join(new_parts)
    else:
        if not new_parts:
            return '.'
        return '/'.join(new_parts)


