    query = ''
    fragment = ''

    if remainder.startswith('/'):
        q_idx = remainder.find('?')
        f_idx = remainder.find('#')

        min_idx = len(remainder)
        if q_idx != -1:
            min_idx = min(min_idx, q_idx)
        if f_idx != -1:
            min_idx = min(min_idx, f_idx)

        path = remainder[:min_idx]

        after_path = remainder[min_idx:]
        if after_path.startswith('?'):
            f_idx2 = after_path.find('#')
            if f_idx2 != -1:
                query = after_path[1:f_idx2]
                fragment = after_path[f_idx2+1:]
            else:
                query = after_path[1:]
        elif after_path.startswith('#'):
            fragment = after_path[1:]
    elif remainder.startswith('?'):
        f_idx = remainder.find('#')
        if f_idx != -1:
            query = remainder[1:f_idx]
            fragment = remainder[f_idx+1:]
        else:
            query = remainder[1:]
    elif remainder.startswith('#'):
        fragment = remainder[1:]

    return (scheme, netloc, path, '', '', query, fragment)

