import sys

def parse_url(url):
    # Parse a URL without urllib
    # Handle scheme
    if "://" in url:
        scheme, rest = url.split("://", 1)
    else:
        scheme, rest = None, url

    # Find netloc (up to first /, ?, or #)
    netloc_end = len(rest)
    for i, c in enumerate(rest):
        if c == '/' or c == '?' or c == '#':
            netloc_end = i
            break

    netloc = rest[:netloc_end]
    after_netloc = rest[netloc_end:]

    # Find query and fragment
    path = after_netloc
    query = ""
    fragment = ""

    if '#' in path:
        hash_pos = path.index('#')
        fragment = path[hash_pos+1:]
        path = path[:hash_pos]

    if '?' in path:
        q_pos = path.index('?')
        query = path[q_pos+1:]
        path = path[:q_pos]

    # If no path separator but has query, path might be empty
    if not path.startswith('/') and query and not path:
        pass  # path is empty string

    return scheme, netloc, path, query, fragment


def parse_qs(qs):
    # Simple implementation of parse_qs for basic cases
    result = {}
    if not qs:
        return result
    pairs = qs.split('&')
    for pair in pairs:
        if '=' in pair:
            key, value = pair.split('=', 1)
        else:
            key, value = pair, ''

        # Unquote (basic percent-decoding and + to space)
        key = _unquote(key)
        value = _unquote(value)

        if key not in result:
            result[key] = []
        result[key].append(value)
    return result


def _unquote(s):
    # Replace + with space and decode %XX sequences
    s = s.replace('+', ' ')
    i = 0
    out = []
    while i < len(s):
        if s[i] == '%' and i + 2 < len(s) + 1:
            if i + 2 <= len(s) - 1:
                hexdigits = s[i+1:i+3]
                try:
                    codepoint = int(hexdigits, 16)
                    out.append(chr(codepoint))
                    i += 3
                    continue
                except ValueError:
                    pass
        out.append(s[i])
        i += 1
    return ''.join(out)


