    if '://' in url_str:
        scheme_end = url_str.index('://') + 3
    else:
        scheme_end = 0

    rest = url_str[scheme_end:]

    # Find query string
    if '?' in rest:
        query_index = rest.index('?')
        path_part = rest[:query_index]
        query_string = rest[query_index+1:]
    else:
        path_part = rest
        query_string = ""

    # Path part contains netloc and path
    # netloc ends at first '/' after the protocol
    if '/' in path_part:
        netloc = path_part.split('/', 1)[0]
        path = '/' + path_part.split('/', 1)[1]
    else:
        netloc = path_part
