                raise ValueError("Excess padding after base64-decoding")
            val = (qv[0] << 18) | (qv[1] << 12)
            result.append((val >> 16) & 0xFF)
        else:
            # qp >= 3: invalid, too much padding
            raise ValueError("Excess padding after base64-decoding")

    return bytes(result)


