# base64 decoder that matches CPython 3.12 behavior (validates padding strictly)

import os


def _b64_validate_and_decode(s):
    """Decode base64 data with strict validation matching CPython 3.12."""
    if isinstance(s, str):
        s = s.encode('ascii')

    # Remove whitespace
    cleaned = b''
    for c in s:
        if c == 0x09 or c == 0x0A or c == 0x0D or c == 0x20:
            continue
        cleaned += bytes([c])

    # Check for valid characters and determine length
    n = len(cleaned)
    if n == 0:
        return b''

    # All chars must be valid base64 alphabet or '='
    for i in range(n):
        c = cleaned[i]
        if not ((0x30 <= c <= 0x39) or          # 0-9
                (0x41 <= c <= 0x5a) or          # A-Z
                (0x61 <= c <= 0x7a) or          # a-z
                c == 0x2b or c == 0x2d or       # + -
                c == 0x2f or c == 0x5f or       # / _
                c == 0x3d):                     # =
            raise ValueError("Invalid base64 data")

    # Padding must only appear at the end
    pad_count = 0
    first_pad_pos = n
    for i in range(n):
        if cleaned[i] == 0x3d:
            pad_count += 1
            if first_pad_pos == n:
                first_pad_pos = i
    if pad_count > 2:
        raise ValueError("Invalid base64 padding")

    # After padding starts, no more non-padding chars should follow
    # (padding must be contiguous at end)
    for i in range(first_pad_pos, n):
        if cleaned[i] != 0x3d:
            raise ValueError("Invalid base64 padding")

    # The total length including padding must be divisible by 4
    # Actually, for standard base64, the input without whitespace should have length % 4 == 0
    if n % 4 != 0:
        raise ValueError("Invalid base64 string length")

    # Decode character values
    def char_val(c):
        if 0x30 <= c <= 0x39:
            return c - 0x30 + 26
        if 0x41 <= c <= 0x5a:
            return c - 0x41
        if 0x61 <= c <= 0x7a:
            return c - 0x61 + 26
        if c == 0x2b:
            return 62
        if c == 0x2f:
            return 63
        if c == 0x2d:
            return 62
        if c == 0x5f:
            return 63
        if c == 0x3d:
            return 0
        raise ValueError("Invalid base64 character")

    out = bytearray()
    i = 0
    while i < n:
        quad = cleaned[i:i+4]
        q_len = len(quad)
        if q_len < 4:
            raise ValueError("Invalid base64 string length")

        v0 = char_val(quad[0])
        v1 = char_val(quad[1])
        v2 = char_val(quad[2])
        v3 = char_val(quad[3])

        # Determine number of padding chars in this quad
        p = 0
        if quad[3] == 0x3d:
            p += 1
        if quad[2] == 0x3d:
            p += 1

        b0 = (v0 << 2) | (v1 >> 4)
        b1 = ((v1 & 0x0F) << 4) | (v2 >> 2)
        b2 = ((v2 & 0x03) << 6) | v3

        if p == 0:
            out.append(b0)
            out.append(b1)
            out.append(b2)
        elif p == 1:
            out.append(b0)
            out.append(b1)
        elif p == 2:
            out.append(b0)
        else:
            # p >= 3 is invalid
            raise ValueError("Invalid base64 padding")

        i += 4

    return bytes(out)


for s in [b"AA==AA==", b"aGk=aGk=", b"AA==A", b"aa=\n=", b"aGk==", b"a!G k=", b"-_--", b"====", b"AAAA=AAAA", b"QUJD", b"QQ==QQ==QQ=="]:
