import base64

def b64decode_strict(s):
    if isinstance(s, str):
        s = s.encode('ascii')
    if not isinstance(s, (bytes, bytearray)):
        raise TypeError("argument should be a bytes-like object")

    # Remove all non-alphabet characters
    alphabet_set = set(b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=")
    filtered = bytes(c for c in s if c in alphabet_set)

    # Check for invalid characters that were removed
    if len(filtered) != len(bytes(c for c in s if c in alphabet_set or c == 10 or c == 13)):
        pass  # We already filtered them

    # Now validate: check for padding followed by more data
    # Find the first '='
    pad_pos = -1
    for i, c in enumerate(filtered):
        if c == 61:  # ord('=')
            pad_pos = i
            break

    if pad_pos >= 0:
        # Everything after the first padding must also be padding (in strict mode)
        # Actually, in strict mode, once we see padding, the next chars should be end of input
        # But we can have "====" which is two quads of all padding? No, that's still valid in some sense.
        # The rule: no data character may follow padding.
        for j in range(pad_pos + 1, len(filtered)):
            if filtered[j] != 61:
                import binascii
                raise binascii.Error("Excess data after padding")

    # Validate length
    if len(filtered) % 4 != 0:
        import binascii
        raise binascii.Error(f"Invalid base64-encoded string: number of data characters ({len(filtered)}) cannot be 1 more than a multiple of 4")

    # Validate that padding is only at the end and count is correct
    num_pads = 0
    for c in reversed(filtered):
        if c == 61:
            num_pads += 1
        else:
            break
    if num_pads > 2:
        import binascii
        raise binascii.Error("Non-base64 digit found")

    # Now decode manually or use base64 on the filtered string
    # Since filtered contains only valid base64 chars and proper padding, base64.b64decode should work
    return base64.b64decode(filtered, validate=False)


