import os, sys, time

def _max_rss_mb(pid):
    try:
        p = "/proc/%d/status" % pid
        v = None
        for i in range(500):
            if not os.path.exists(p):
                break
            with open(p, "r") as f:
                for line in f:
                    if line.startswith("VmPeak:"):
                        parts = line.split()
                        v = int(parts[1])  # kB
                        break
            if v is not None:
                return v / 1024.0
            time.sleep(0.001)
        if v is not None:
            return v / 1024.0
    except Exception:
        pass
    return -1.0

def run(bin, prog):
    t0 = time.perf_counter()
    pid = os.fork()
    if pid == 0:
        fd = os.open(os.devnull, os.O_WRONLY)
        os.dup2(fd, 1)
        os.execv(bin, [bin, "-c", prog])
        os._exit(127)
    _, status = os.waitpid(pid, 0)
    rss = _max_rss_mb(pid)
    ms = (time.perf_counter() - t0) * 1000
    return rss, ms, status

