import sys

def only_set_order_differs(str1, str2):
    s1 = str1.strip()
    s2 = str2.strip()

    if not s1 or not s2:
        return False

    # Check if they are sets by looking for set-like syntax {x, y, z}
    # A set has no colons (no key-value pairs) and starts with { ends with }
    def is_set_like(s):
        stripped = s.strip()
        if not stripped.startswith('{') or not stripped.endswith('}'):
            return False
        inner = stripped[1:-1]
        # If it contains a colon at the top level, it's likely a dict
        # Simple check: if there's a colon outside of nested structures
        depth = 0
        for i, c in enumerate(inner):
            if c in '{[':
                depth += 1
            elif c in '}]':
                depth -= 1
            elif c == ':' and depth == 0:
                return False
        return True

    if is_set_like(s1) and is_set_like(s2):
        # Parse the elements of both sets
        def parse_set_elements(s):
            stripped = s.strip()
            inner = stripped[1:-1].strip()
            if not inner:
                return set()
            # Split by commas, but be careful with nested structures
            parts = []
            current = ''
            depth = 0
            for c in inner:
                if c in '{[':
                    depth += 1
                    current += c
                elif c in '}]':
                    depth -= 1
                    current += c
                elif c == ',' and depth == 0:
                    parts.append(current.strip())
                    current = ''
                else:
                    current += c
            if current.strip():
                parts.append(current.strip())

            result = set()
            for part in parts:
                try:
                    val = eval(part)
                    result.add(val)
                except:
                    pass
            return result

        set1 = parse_set_elements(s1)
        set2 = parse_set_elements(s2)

        if set1 == set2:
            # They have the same elements; if they differ as strings, then order differs
            if s1 != s2:
                return True
            else:
                return False
        else:
            return False
    elif not is_set_like(s1) and not is_set_like(s2):
        # Both are dicts (or other non-set types)
        # For dicts, check if they have the same keys and values
        try:
            d1 = eval(s1)
            d2 = eval(s2)
            if isinstance(d1, dict) and isinstance(d2, dict):
                if d1 == d2:
                    if s1 != s2:
                        return True
                    else:
                        return False
                else:
                    return False
        except:
            pass
        return False
    else:
        return False


