import sys

class conformance:
    @staticmethod
    def only_set_order_differs(s1, s2):
        import ast

        def parse_string(s):
            s = s.strip()
            if not s:
                return None

            # Try parsing as Python literal first
            try:
                return ast.literal_eval(s)
            except (ValueError, SyntaxError):
                pass

            # If it looks like a set notation {1, 2, 3}, try converting to list
            if s.startswith('{') and s.endswith('}'):
                inner = s[1:-1]
                # Split by commas, handling simple cases
                parts = [p.strip() for p in inner.split(',')]
                result = []
                for part in parts:
                    try:
                        val = ast.literal_eval(part)
                        result.append(val)
                    except (ValueError, SyntaxError):
                        # Remove quotes if present
                        if part.startswith("'") and part.endswith("'"):
                            result.append(part[1:-1])
                        elif part.startswith('"') and part.endswith('"'):
                            result.append(part[1:-1])
                        else:
                            result.append(part)
                return result

            # Fallback
            if s.startswith("'") or s.startswith('"'):
                return s[1:-1]
            return s

        val1 = parse_string(s1)
        val2 = parse_string(s2)

        if val1 is None or val2 is None:
            return False

        # Convert sets to sorted lists for comparison
        if isinstance(val1, set):
            val1 = sorted(val1)
        if isinstance(val2, set):
            val2 = sorted(val2)

        # For dictionaries, compare the items (sorted by key)
        if isinstance(val1, dict) and isinstance(val2, dict):
            if sorted(val1.items()) == sorted(val2.items()):
                return True
            # Check if only the order differs
            if sorted(val1.keys()) == sorted(val2.keys()):
                # If keys are same but order might differ, and values match when aligned by key
                for k in sorted(val1.keys()):
                    if val1[k] != val2[k]:
                        return False
                return True
            return False

        # For lists, check if they contain same elements
        if isinstance(val1, list) and isinstance(val2, list):
            if len(val1) != len(val2):
                return False
            if sorted(val1) == sorted(val2):
                return True
            return False

        return val1 == val2


