def only_set_order_differs(a: str, b: str) -> bool:
    import ast

    def parse_and_sort(s):
        s = s.strip()
        # Try to parse as a Python literal (dict, set, etc.)
        try:
            obj = ast.literal_eval(s)
        except (ValueError, SyntaxError):
            return None

        if isinstance(obj, dict):
            # For dicts, compare keys and values as sets of tuples
            return sorted((k, v) for k, v in obj.items())
        elif isinstance(obj, set):
            return sorted(obj)
        else:
            return [obj]

    parsed_a = parse_and_sort(a)
    parsed_b = parse_and_sort(b)

    if parsed_a is None or parsed_b is None:
        return False

    return parsed_a == parsed_b


