    try:
        val_a = ast.literal_eval(a.strip())
        val_b = ast.literal_eval(b.strip())
    except Exception:
        return False

    if type(val_a) != type(val_b):
        return False

    if isinstance(val_a, set):
        return val_a == val_b

    if isinstance(val_a, (list, tuple)):
        return list(val_a) == list(val_b) or (isinstance(val_a, (set,)) and isinstance(val_b, (set,)))

    if isinstance(val_a, dict):
        if not isinstance(val_b, dict):
            return False
        # Check if keys are the same but possibly in different order
        if sorted(str(k) for k in val_a.keys()) != sorted(str(k) for k in val_b.keys()):
            return False
        # Check that all values are the same for corresponding keys
        for k in val_a:
            if k not in val_b:
                return False
            if val_a[k] != val_b[k]:
                return False
        return True

    return val_a == val_b


