import json, random

def mulberry32(seed):
    state = [seed & 0xFFFFFFFF]
    def gen():
        state[0] = (state[0] + 0x6D2B79F5) & 0xFFFFFFFF
        t = state[0]
        t = ((t ^ (t >> 15)) * (t | 1)) & 0xFFFFFFFF
        t ^= t + 7
        return ((t ^ (t >> 14)) * (t | 1)) & 0xFFFFFFFF
    def next_float():
        a = gen()
        b = gen()
        return (a / 2**32) + (b / 2**64)
    def next_int(n):
        if n <= 0:
            raise ValueError("n must be positive")
        # Get enough random bits
        bits_needed = n.bit_length()
        while True:
            val = gen()
            if val < (2 ** bits_needed) and val < 2**32 - 1:
                break
        # Rejection sampling to avoid bias
        limit = (2**32 // n) * n
        val = gen()
        while val >= limit:
            val = gen()
        return val % n
    return next_float, next_int

# Monkey-patch random.Random to use our deterministic implementation
next_float, next_int = mulberry32(4242)

class _FakeRandom:
    def __init__(self, seed=None):
        pass
    def choice(self, seq):
        n = len(seq)
        return seq[next_int(n)]
    def randrange(self, start, stop=None, step=1):
        if stop is None:
            start, stop = 0, start
        rng = (stop - start + step - 1) // step
        return start + next_int(rng) * step
    def randint(self, a, b):
        if a > b:
            raise ValueError
        return a + next_int(b - a + 1)

random.Random = _FakeRandom

r = random.Random(4242)

ARGS_DEC=["b'aGk='","b'QUJD'","'aGk='","b''","b'===='","b'a!G k='","b'AA==AA=='","b'-_--'","x","f'aGk='","b'aG'+b'k='"]
ARGS_ENC=["b'hi'","b''","b'\\x00\\xff'","bytes([1,2])","x","b'a'*3"]
FNS=["b64encode","b64decode","urlsafe_b64encode","urlsafe_b64decode"]
KW=["","altchars=None","validate=False","validate=0","altchars=0","altchars=False","validate=None","altchars=b'-_'","validate=True","altchars=1"]
