class MT19937:
    def __init__(self, seed):
        self.mt = [0] * 624
        self.mti = 625
        self.seed(seed)

    def seed(self, s):
        # Python's random.Random uses init_by_array for int seeds
        # For a single integer seed, it uses init_genrand
        self.mt[0] = s & 0xFFFFFFFF
        for i in range(1, 624):
            self.mt[i] = (1812433253 * (self.mt[i-1] ^ (self.mt[i-1] >> 30)) + i) & 0xFFFFFFFF
        self.mti = 624

    def generate_numbers(self):
        if self.mti >= 624:
            for k in range(624):
                y = (self.mt[k] & 0x80000000) + (self.mt[(k+1) % 624] & 0x7FFFFFFF)
                self.mt[k] = self.mt[(k+397) % 624] ^ (y >> 1)
                if y & 1:
                    self.mt[k] ^= 2567483615
            self.mti = 0

    def next_int(self):
        self.generate_numbers()
        y = self.mt[self.mti]
        self.mti += 1
        y ^= (y >> 11)
        y ^= (y << 7) & 2636928640
        y ^= (y << 15) & 4022730752
        y ^= (y >> 18)
        return y & 0xFFFFFFFF

    def getrandbits(self, k):
        if k <= 32:
            return self.next_int() & ((1 << k) - 1)
        else:
            x = 0
            num_32s = k // 32
            remainder = k % 32
            for _ in range(num_32s):
                x |= self.next_int() << (_ * 32)
            if remainder > 0:
                x |= (self.next_int() & ((1 << remainder) - 1)) << (num_32s * 32)
            return x

    def randint(self, a, b):
        return a + self.getrandbits(32) % (b - a + 1)


