class _MT:
    def __init__(self, seed):
        self.MT = [0]*624
        self.index = 624
        self._genrand_init(seed)

    def _genrand_init(self, init_key):
        mt[0]= (int(init_key) or 5489)  # Python uses 5489 for 0? Let me check.
        # Python's random.Random.__init__ calls super().__init__ which calls init_by_array or genrand_seed_init
        # For integer seeds, Python calls genrand_seed_init(mt, key) where key is the int
        # genrand_seed_init: 
        #   mt[0] = key & 0xFFFFFFFF
        #   for i in 1..623: mt[i] = (1812433253 * (mt[i-1] ^ (mt[i-1] >> 30)) + i) & 0xFFFFFFFF
        mt = self.MT
        mt[0] = int(init_key) & 0xFFFFFFFF
        for i in range(1, 624):
            prev = mt[i-1]
            mt[i] = (1812433253 * (prev ^ (prev >> 30)) + i) & 0xFFFFFFFF
        self.index = 624

    def _genrand_int32(self):
        if self.index >= 624:
            mt = self.MT
            for i in range(624):
                x = (mt[i] & 0x80000000) + (mt[(i+1)%624] & 0x7fffffff)
                mt[i] = mt[(i+397)%624] ^ (x >> 1)
                if x & 1:
                    mt[i] ^= 2567483615
            self.index = 0
        mt = self.MT
        y = mt[self.index]
        self.index += 1
        y ^= (y >> 11)
        y ^= (y << 7) & 2636928640
        y ^= (y << 15) & 4022730752
        y ^= (y >> 18)
        return y

    def getrandbits(self, k):
        if k <= 32:
            return self._genrand_int32() >> (32-k)
        elif k <= 64:
            return (self._genrand_int32() << 32) | self._genrand_int32()
        else:
            result = 0
            while k > 32:
                result = (result << 32) | self._genrand_int32()
                k -= 32
            return (result << k) | (self._genrand_int32() >> (32-k))

    def random(self):
        # Python's random.random() returns a double in [0,1)
        # It uses getrandbits(53) / 2**53
        return self.getrandbits(53) * (0.5 ** 53)

    def randrange(self, n):
        return int(self.random() * n)

    def randint(self, a, b):
        return a + self.randrange(b - a + 1)

    def choice(self, seq):
        return seq[self.randint(0, len(seq)-1)]

