def _mulmod(a, b, m):
    result = 0
    a %= m
    b %= m
    while b > 0:
        if b & 1:
            result = (result + a) % m
        b >>= 1
        a = (a * 2) % m
    return result


def _powmod(b, e, m):
    if m == 1:
        return 0
    result = 1
    b %= m
    while e > 0:
        if e & 1:
            result = _mulmod(result, b, m)
        e >>= 1
        b = _mulmod(b, b, m)
    return result


def _invmod(x, y):
    old_r, r = x % y, y
    old_s, s = 1, 0
    while r != 0:
        q = old_r // r
        old_r, r = r, old_r - q * r
        old_s, s = s, old_s - q * s
    if old_r != 1:
        raise ValueError("no inverse")
    return old_s % y


class _Random:
    A = 6364136223846793005
    C = 1442695040888963407
    M = 2 ** 64

    def __init__(self, seed=None):
        if seed is None or isinstance(seed, (int, float)):
            self._state = int(seed) if seed is not None else 0
            self._state &= (self.M - 1)
        elif isinstance(seed, bytes):
            seed_int = 0
            for b in seed:
                seed_int = (seed_int << 8) | b
            self._state = seed_int & (self.M - 1)
        else:
            raise TypeError("unsupported seed type")

    def next(self):
        self._state = (self.A * self._state + self.C) % self.M
        return (self._state >> 5) & 0x7FFFFFFF

    def getrandbits(self, k):
        res = 0
        full_words, rem = divmod(k, 32)
        for _ in range(full_words):
            res = (res << 32) | self.next()
        if rem > 0:
            res = (res << rem) | (self.next() >> (32 - rem))
        return res

    def randbelow(self, n):
        if n <= 0:
            raise ValueError("n must be positive")
        bits = n.bit_length()
        if bits == 0:
            return 0
        limit = (1 << bits) - (1 << bits) % n
        while True:
        # random.randbelow uses rejection sampling to avoid modulo bias
            val = self.getrandbits(bits)
            if val < limit:
                return val % n

    def choice(self, seq):
        return seq[self.randbelow(len(seq))]


