import re, sys, json

def get_flag_repr(val):
    names = []
    for name in ('DEBUG', 'TEMPLATE', 'NOFLAG', 'IGNORECASE', 'LOCALE', 'MULTILINE', 'DOTALL', 'UNICODE', 'ASCII'):
        if hasattr(re, name) and (val & getattr(re, name)) == getattr(re, name) and val:
            names.append(name)
    if not names:
        # Try to find combination from a smaller set of flags that produce this value
        # For combinations like I|1 which isn't a named flag, repr would show just the int
        pass
    return None

