import base64

def decode_b64(data: bytes) -> bytes:
    # Strip whitespace
    data = bytes(b for b in data if b not in (0x20, 0x09, 0x0A, 0x0D))
    # Validate length mod 4 (after stripping padding context)
    # Standard base64: length must be multiple of 4 except trailing 1-3 chars allowed only as padding-free tail... 
    # Actually Python's b64decode requires total length to be a multiple of 4 after adding missing '='.
    # We'll mimic CPython behavior: it pads with '=' to make len % 4 == 0, then decodes.
    # The key difference: whether we stop at first padding or continue reading.

    # Find the position where padding starts (first '=')
    pad_start = data.find(b'=')
    if pad_start == -1:
        # No padding; need length to be 0, 2, or 3 mod 4 for valid base64 without padding
        # Actually, unpadded base64 has length % 4 in {0, 2, 3}
        rem = len(data) % 4
        if rem == 1:
            raise ValueError("Invalid base64 string: length must be a multiple of 4")
        padded = data
        actual_pad_count = 0
    else:
        # Padding found
        # All characters after pad_start should be '=' (they represent padding)
        # But what about characters before that are invalid?
        num_pad = len(data) - pad_start
        if num_pad > 2:
            raise ValueError("Invalid base64 string: too much padding")
        # Pad to multiple of 4
        padded_len = ((len(data) + 3) // 4) * 4
        if padded_len > len(data):
            padded = data + b'=' * (padded_len - len(data))
        else:
            padded = data

    # Now decode the padded string
    # Build lookup table
    b64_chars = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    lookup = {}
    for i, c in enumerate(b64_chars):
        lookup[c] = i
    lookup[b'-'] = 62  # URL-safe variant, but standard b64decode doesn't support by default
    lookup[b'_'] = 63

    # Actually, let's use the standard alphabet only
    lookup = {}
    for i, c in enumerate(b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"):
        lookup[c] = i

    result = bytearray()
    n = len(padded)
    for i in range(0, n, 4):
        quad = padded[i:i+4]
        vals = []
        for c in quad:
            if c == ord('='):
                vals.append(None)
            elif c in lookup:
                vals.append(lookup[c])
            else:
                raise ValueError(f"Invalid character {chr(c)!r} in base64 string")

        # Process the quad
        if all(v is None for v in vals):
            continue
        if vals[0] is None:
            raise ValueError("Invalid base64 padding")

        # Decode 6-bit groups into bytes
        bits = []
        for j, v in enumerate(vals):
            if v is not None:
                for k in range(5, -1, -1):
                    bits.append((v >> k) & 1)
            else:
                # padding adds implicit zeros
                for k in range(6):
                    bits.append(0)

        # Convert bits to bytes
        full_bytes = len(bits) // 8
        for byte_idx in range(full_bytes):
            byte_val = 0
            for bit in range(8):
                byte_val = (byte_val << 1) | bits[byte_idx * 8 + bit]
            result.append(byte_val)

    return bytes(result)


