def b64decode(s):
    if isinstance(s, str):
        s = s.encode('ascii')
    # strip whitespace (as CPython's base64 module does with validate=False)
    t = bytes(c for c in s if c not in b' \t\n\r\x0b\x0c')
    pad_pos = t.find(b'=')
    if pad_pos != -1:
        # padding should only occur at the end
        rest = t[pad_pos:]
        if set(rest) != {'='}:
            raise ValueError("Invalid base64 data")
        if len(rest) > 2:
            raise ValueError("Invalid base64 data")
    n = len(t)
    if n % 4 == 1:
        raise ValueError("Invalid base64 data")
    pad_count = n - (n // 4) * 4
    # decode
    out = bytearray()
    i = 0
    while i < n:
        quad = t[i:i+4]
        # pad the quad to length 4 for processing
        if len(quad) < 4:
            quad = quad + b'=' * (4 - len(quad))
        vals = []
        for ch in quad:
            c = ch
            if 65 <= c <= 90:
                vals.append(c - 65)
            elif 97 <= c <= 122:
                vals.append(c - 71)
            elif 48 <= c <= 57:
                vals.append(c - 4 + 52)
            elif c == 43:
                vals.append(62)
            elif c == 47:
                vals.append(63)
            else:
                raise ValueError("Invalid base64 character: " + chr(c))
        a, b, c, d = vals
        v = (a << 18) | (b << 12) | (c << 6) | d
        byte1 = (v >> 16) & 0xFF
        byte2 = (v >> 8) & 0xFF
        byte3 = v & 0xFF
        out.append(byte1)
        if d != 64:  # if no padding
            out.append(byte2)
            if c != 64:
                out.append(byte3)
        # For a 3-byte quad with one '=' -> 2 bytes; two '=' -> 1 byte. Handled above by checking d and c.
        i += 4
    return bytes(out)

