def fnmatchcase(name, pattern):
    # Build a regex from the fnmatch pattern
    i = 0
    n = len(pattern)
    result = ''
    while i < n:
        c = pattern[i]
        if c == '*':
            result += '.*'
            i += 1
        elif c == '?':
            result += '.'
            i += 1
        elif c == '[':
            j = i + 1
            if j < n and pattern[j] == '!':
                j += 1
            if j < n and pattern[j] == ']':
                j += 1
            while j < n and pattern[j] != ']':
                j += 1
            if j >= n:
                result += re.escape(c)
                i += 1
            else:
                stuff = pattern[i+1:j]
                i = j + 1
                if stuff[0] == '!':
                    stuff = '^' + stuff[1:]
                # Handle ranges in stuff
                # We need to escape special characters that are not part of ranges
                new_stuff = []
                k = 0
                m = len(stuff)
                while k < m:
                    if k + 2 < m and stuff[k+1] == '-' and stuff[k+2] != ']':
                        new_stuff.append(re.escape(stuff[k]) + '-' + re.escape(stuff[k+2]))
                        k += 3
                    else:
                        new_stuff.append(re.escape(stuff[k]))
                        k += 1
                result += '[' + ''.join(new_stuff) + ']'
        else:
            result += re.escape(c)
            i += 1
    return bool(re.match('^' + result + '$', name))

