def _check_char_in_class(c, class_content):
    """Check if char c is in the parsed character class content."""
    # class_content is the string inside [ ... ], excluding the brackets.
    negate = False
    i = 0

    if class_content.startswith('!') or class_content.startswith('^'):
        negate = True
        i = 1

    found = False
    length = len(class_content)
    while i < length:
        # Handle escape
        if class_content[i] == '\\' and i + 1 < length:
            next_c = class_content[i+1]
            if c == next_c:
                found = True
            i += 2
            continue

        # Handle range
        if i + 2 < length and class_content[i+1] == '-':
            start_c = class_content[i]
            end_c = class_content[i+2]
            # In Python str, comparison works lexicographically/ASCII
            if start_c <= c <= end_c:
                found = True
            i += 3
            continue

        # Single char
        if c == class_content[i]:
            found = True
        i += 1

    return (found != negate) if negate else found

def my_fnmatchcase(name, pattern):
    """Mimic fnmatch.fnmatchcase for *, ?, [..], and literals."""
    p_len = len(pattern)
    n_len = len(name)

    def match(i, j):
        if i == p_len and j == n_len:
            return True
        if i == p_len or j == n_len:
            return False

        pc = pattern[i]

        if pc == '*':
            # Try matching * as 0, 1, ..., remaining chars
            # Optimize: skip consecutive *
            while i < p_len and pattern[i] == '*':
                i += 1
            if i == p_len:
                return True
            # Backtrack
            for k in range(j, n_len + 1):
                if match(i, k):
                    return True
            return False
        elif pc == '?':
            if j < n_len:
                return match(i + 1, j + 1)
            else:
                return False
        elif pc == '[':
            # Find closing bracket
            end_bracket = pattern.find(']', i + 1)
            if end_bracket == -1:
                # No closing bracket, treat as literal [ 
                if j < n_len and name[j] == '[':
                    return match(i + 1, j + 1)
                else:
                    return False

            class_content = pattern[i + 1:end_bracket]
            if j >= n_len:
                return False

            nc = name[j]
            if _check_char_in_class(nc, class_content):
                return match(end_bracket + 1, j + 1)
            else:
                return False
        else:
            # Literal
            if j < n_len and name[j] == pc:
                return match(i + 1, j + 1)
            else:
                return False

    return match(0, 0)

