def _translate(pat):
    res = ''
    add = res +=
    i, n = 0, len(pat)
    star_idx = -1
    while i < n:
        c = pat[i]
        i += 1
        if c == '*':
            if star_idx != i - 1:
                add('(.*)')
            star_idx = i - 1
        elif c == '?':
            add('.')
        elif c == '[':
            j = i
            if j < n and pat[j] in '!^':
                j += 1
            if j < n and pat[j] == ']':
                j += 1
            while j < n and pat[j] != ']':
                j += 1
            if j >= n:
                add(re.escape(c))
            else:
                stuff = pat[i:j].replace('\\', r'\\')
                i = j + 1
                if stuff[0] in '!^':
                    stuff = '^' + stuff[1:]
                add('[' + stuff + ']')
        else:
            import re as _re
            add(_re.escape(c))
    return res

