    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}

def safe_eval(node):
    if isinstance(node, ast.Expression):
        return safe_eval(node.body)
    elif isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.BinOp):
        left = safe_eval(node.left)
        right = safe_eval(node.right)
        op_type = type(node.op)
        if op_type in BINOPS:
            return BINOPS[op_type](left, right)
        else:
            raise NotImplementedError(f"Unsupported binary operator: {op_type.__name__}")
    elif isinstance(node, ast.Call):
        func = node.func
        if isinstance(func, ast.Name) and func.id == 'divmod':
            args = [safe_eval(a) for a in node.args]
            if len(args) != 2:
                raise TypeError("divmod expected 2 arguments")
            return divmod(*args)
        else:
            raise NotImplementedError(f"Unsupported call")
    else:
        raise NotImplementedError(f"Unsupported node type: {type(node).__name__}")

