def evaluate(expr):
    expr = expr.strip()

    # Handle divmod(a, b)
    if expr.startswith('divmod') and expr.endswith(')'):
        args_str = expr[7:-1]  # inside parentheses after 'divmod'
        parts = args_str.split(',')
        a = float(parts[0].strip())
        b = float(parts[1].strip())
        return divmod(a, b)

    # Handle ** operator first (highest precedence among these)
    if '**' in expr:
        base_str, exp_str = expr.split('**')
        base = eval_number(base_str.strip())
        exponent = int(exp_str.strip())
        result = base ** exponent

        # Then handle % or // if present
        rest = expr[expr.index('**') + 2:]
        if rest.strip().startswith('%'):
            divisor_str = rest.strip()[1:].strip()
            divisor = eval_number(divisor_str)
            return result % divisor
        elif rest.strip().startswith('//'):
            divisor_str = rest.strip()[2:].strip()
            divisor = eval_number(divisor_str)
            return result // divisor
        else:
            return result

    # Handle // operator
    if '//' in expr:
        left_str, right_str = expr.split('//')
        left = eval_number(left_str.strip())
        right = eval_number(right_str.strip())
        return left // right

    # Handle % operator
    if '%' in expr:
        left_str, right_str = expr.split('%')
        left = eval_number(left_str.strip())
        right = eval_number(right_str.strip())
        return left % right

    # Fallback - shouldn't happen for our expressions
    raise ValueError("Cannot parse: " + expr)


