        for i, ch in enumerate(inner):
            if ch == '(':
                depth += 1
            elif ch == ')':
                depth -= 1
            elif ch == ',' and depth == 0:
                comma_idx = i
                break
        if comma_idx is not None:
            a_str = inner[:comma_idx].strip()
            b_str = inner[comma_idx+1:].strip()
            return divmod(_eval_simple(a_str), _eval_simple(b_str))

    # Check for floor division or modulo
    for op in ['//', '%']:
        idx = -1
        found_op = False
        i = 0
        while i < len(expr):
            if expr[i:i+len(op)] == op:
                # Make sure it's actually this operator
                idx = i
                found_op = True
                break
            i += 1
        if found_op:
            a_str = expr[:idx].strip()
            b_str = expr[idx+len(op):].strip()
            a = _eval_simple(a_str)
            b = _eval_simple(b_str)
            if op == '//':
