"""My own transcription of BOTH binascii.c loops, read from the branch tips today.

stop()  = 3.9/3.11/3.12 ; thru() = 3.13/3.14/main. Both lenient (strict_mode=0).
Then: does the engine's rule (answer iff no alphabet byte after the pad that
closes a quad) ever answer where the two models differ?
"""
import base64, itertools, random, sys

TAB = {}
for i, c in enumerate(b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"):
    TAB[c] = i


def stop(data):
    out = bytearray(); quad = 0; pads = 0; left = 0
    for ch in data:
        if ch == 0x3D:
            if quad >= 2:
                pads += 1
                if quad + pads >= 4:
                    return ("ok", bytes(out))
            continue
        v = TAB.get(ch)
        if v is None:
            continue
        pads = 0
        if quad == 0:   quad = 1; left = v
        elif quad == 1: quad = 2; out.append(((left << 2) | (v >> 4)) & 0xFF); left = v & 0x0F
        elif quad == 2: quad = 3; out.append(((left << 4) | (v >> 2)) & 0xFF); left = v & 0x03
        else:           quad = 0; out.append(((left << 6) | v) & 0xFF); left = 0
    if quad == 1: return ("err", "len")
    if quad != 0: return ("err", "pad")
    return ("ok", bytes(out))


def thru(data):
    out = bytearray(); quad = 0; pads = 0; left = 0
    for ch in data:
        if ch == 0x3D:
            pads += 1
            continue          # lenient: both branches of 3.13 end in `continue`
        v = TAB.get(ch)
        if v is None:
            continue
        pads = 0
        if quad == 0:   quad = 1; left = v
        elif quad == 1: quad = 2; out.append(((left << 2) | (v >> 4)) & 0xFF); left = v & 0x0F
        elif quad == 2: quad = 3; out.append(((left << 4) | (v >> 2)) & 0xFF); left = v & 0x03
        else:           quad = 0; out.append(((left << 6) | v) & 0xFF); left = 0
