# Build a pure-Python decoder that reproduces CPython's binascii.a2b_base64
# behavior (the "stop" model / installed CPython 3.11 semantics).

def a2b_base64_pure(data):
    """Mimic binascii.a2b_base64: strict mode=0 (default), lenient on junk,
    but errors on bad length/padding at end."""
    out = bytearray()
    quad = 0
    left = 0
    pad_count = 0
    seen_pad = False
    # We'll track state across the stream.
    for ch in data:
        if ch == 0x3D:  # '='
            seen_pad = True
            quad += 1
            pad_count += 1
            # In binascii, after first '=', no more non-'=' chars allowed? 
            # Actually binascii allows garbage anywhere, but padding must be 
            # at the end. Let me check actual behavior...
            # binascii.a2b_base64: ignores invalid characters (non-alphabet, non-pad)
            # Padding: only valid at end. If alphabet char appears after pad, error.
            continue
        # Check if it's a valid base64 character
        if 65 <= ch <= 90:      # A-Z
            val = ch - 65
        elif 97 <= ch <= 122:   # a-z
            val = ch - 97 + 26
        elif 48 <= ch <= 57:    # 0-9
            val = ch - 48 + 52
        elif ch == 43:          # +
            val = 62
        elif ch == 47:          # /
            val = 63
        else:
            # Invalid character - ignore (binascii skips them)
            continue

        # If we've already seen a pad, having an alphabet char is an error
        if seen_pad:
            raise ValueError("bad padding")

        if quad == 0:
            left = val
            quad = 1
        elif quad == 1:
            out.append(((left << 2) | (val >> 4)) & 0xFF)
            left = val & 0x0F
            quad = 2
        elif quad == 2:
            out.append(((left << 4) | (val >> 2)) & 0xFF)
            left = val & 0x03
            quad = 3
        elif quad == 3:
            out.append(((left << 6) | val) & 0xFF)
            quad = 0

    # Handle final padding
    total_pad = pad_count
