except Exception:
    try:
        from urllib.request import urlopen as _urlopen
    except Exception:
        _hc = None
        _urlopen = None

def _fetch(url, headers):
    # Try http.client first (it is in the standard library and does not require urllib)
    if _hc is not None:
        from urllib.parse import urlparse
        parsed = urlparse(url)
        host = parsed.hostname
        port = parsed.port or (443 if parsed.scheme == "https" else 80)
        path = parsed.path or "/"
        if parsed.query:
            path += "?" + parsed.query
        conn = _hc.HTTPSConnection(host, port, timeout=60)
        hdrs = dict(headers)
        hdrs["Host"] = host
        conn.request("GET", path, headers=hdrs)
        resp = conn.getresponse()
        body = resp.read().decode()
        conn.close()
        return body
    elif _urlopen is not None:
        req = _urlopen.__self__ if hasattr(_urlopen, "__self__") else None
        # Fallback to urlopen directly
        from urllib.request import Request
        r = Request(url, headers=headers)
        return _urlopen(r, timeout=60).read().decode()
    else:
        raise RuntimeError("No HTTP client available")

def get(u):
    token = os.environ["HF_TOKEN"]
    headers = {"Authorization": "Bearer " + token}
    return _fetch(u, headers)

