        elif c == ord('6'):
            val = 58
        elif c == ord('7'):
            val = 59
        elif c == ord('8'):
            val = 60
        elif c == ord('9'):
            val = 61
        else:
            if validate:
                raise ValueError("Non-base64 digit found")
            else:
                continue

        acc = (acc << 6) | val
        bits_left += 6
        if bits_left >= 8:
            bits_left -= 8
            result.append((acc >> bits_left) & 0xff)
            acc &= (1 << bits_left) - 1

    # Check that remaining bits are zero if validate
    if validate and (bits_left > 0 and acc != 0):
        raise ValueError("Invalid base64 encoded bytes")

    # Verify padding count matches expected
    if padcount != expected_pad:
        raise ValueError("Invalid base64 encoded bytes")

    return bytes(result)


