import sys, json

def _make_e_class():
    ns = {}
    exec("class E: pass", ns)
    return ns['E']


def main():
    prog = 'import datetime\nprint(datetime.datetime.now().isoformat())'

    class Conformance:
        @staticmethod
        def is_nondeterministic(obj):
            program = obj.get('program') if isinstance(obj, dict) else getattr(obj, 'program', None)
            if not isinstance(program, str):
                return False
            tokens = {'open', 'close', 'append', 'pop', 'remove', 'sort', 'reverse', 'shuffle',
                      'setdefault', 'random', 'seed', 'time', 'date', 'datetime'}
            import_types = ['import', 'from']
            for line in program.splitlines():
                stripped = line.strip()
                if not stripped:
                    continue
                if any(t in stripped for t in tokens):
                    return True
                for it in import_types:
                    if stripped.startswith(it + ' ') or stripped == it:
                        parts = stripped.split()
                        mod = parts[1] if len(parts) > 1 else ''
                        if mod in tokens or any(tok in mod for tok in tokens):
                            return True
            return False

    d = {'id': 'x', 'program': prog}
    print('dict ->', Conformance.is_nondeterministic(d))

    E = _make_e_class()
    e = E()
    e.program = prog
    e.extra = {}
    print('obj  ->', Conformance.is_nondeterministic(e))


main()

