import sys, json

class Sighting:
    def __init__(self, key=None, id=None, program=None, argv_tail=None, source=None,
                 session=None, first_seen=None, count=None, stdin_sample=None, model=None):
        self.key = key
        self.id = id
        self.program = program
        self.argv_tail = argv_tail if argv_tail is not None else []
        self.source = source
        self.session = session
        self.first_seen = first_seen
        self.count = count
        self.stdin_sample = stdin_sample
        self.model = model
        self.extra = {}

    @classmethod
    def from_obj(cls, obj):
        s = cls()
        for k, v in obj.items():
            if hasattr(s, k) or k in ("key","id","program","argv_tail","source","session","first_seen","count","stdin_sample","model"):
                setattr(s, k, v)
            else:
                s.extra[k] = v
        return s

    def to_obj(self):
        d = {
            "key": self.key,
            "id": self.id,
            "program": self.program,
            "argv_tail": self.argv_tail,
            "source": self.source,
            "session": self.session,
            "first_seen": self.first_seen,
            "count": self.count,
            "stdin_sample": self.stdin_sample,
        }
        if self.model is not None:
            d["model"] = self.model
        d.update(self.extra)
        return d

    def __eq__(self, other):
        if not isinstance(other, Sighting):
            return False
        return (self.key == other.key and self.id == other.id and
                self.program == other.program and self.argv_tail == other.argv_tail and
                self.source == other.source and self.session == other.session and
                self.first_seen == other.first_seen and self.count == other.count and
                self.stdin_sample == other.stdin_sample)


class Entry:
    def __init__(self, id=None, program=None, count=None, first_seen=None):
        self.id = id
        self.program = program
        self.count = count if count is not None else 0
        self.first_seen = first_seen
        self.extra = {}

    @classmethod
    def from_obj(cls, obj):
        e = cls()
        for k, v in obj.items():
            if k in ("id", "program", "count", "first_seen"):
                setattr(e, k, v)
            else:
                e.extra[k] = v
        return e

    def to_obj(self):
        d = {
            "id": self.id,
            "program": self.program,
            "count": self.count,
            "first_seen": self.first_seen,
        }
        d.update(self.extra)
        return d

    def __eq__(self, other):
        if not isinstance(other, Entry):
            return False
        return (self.id == other.id and self.program == other.program and
                self.count == other.count and self.first_seen == other.first_seen)


def merge(lists):
    """Merge lists of Entries. Entries with same id are considered equal (extra excluded from equality)."""
    seen = {}
    order = []
    for lst in lists:
        for entry in lst:
            if entry.id not in seen:
                seen[entry.id] = entry
                order.append(entry.id)
    return [seen[oid] for oid in order]


