import json, re

def _sorted_glob(pattern):
    import os.path as opath
    parts = pattern.split("/")
    last = parts[-1]
    prefix_dir = "/".join(parts[:-1]) if len(parts) > 1 else "."

    def is_match(fname, pat):
        # translate glob pattern to regex
        i, n = 0, len(pat)
        res = "^"
        while i < n:
            c = pat[i]
            if c == "*":
                j = i
                while j < n and pat[j] == "*":
                    j += 1
                res += ".*"
                i = j
            elif c == "?":
                res += "."
                i += 1
            elif c == "[":
                j = i + 1
                neg = False
                if j < n and pat[j] in "!^":
                    neg = True
                    j += 1
                bracket_chars = []
                while j < n and pat[j] != "]":
                    bracket_chars.append(pat[j])
                    j += 1
                if j >= n:
                    res += "\\["
                    i += 1
                else:
                    if neg:
                        res += "[^"
                    else:
                        res += "["
                    for bc in bracket_chars:
                        if bc in "\\[]":
                            res += "\\" + bc
                        elif ord(bc) > 127:
                            res += bc
                        else:
                            res += bc
                    res += "]"
                    i = j + 1
            else:
                if c in r"\^$.|+(){}":
                    res += "\\" + c
                else:
                    res += c
                i += 1
        res += "$"
        try:
            return bool(re.match(res, fname))
        except re.error:
            return False

    # Walk the directory tree
    results = []
    if not prefix_dir or prefix_dir == ".":
        root = "."
    else:
        root = prefix_dir

    if not opath.isdir(root):
        return []

    for dirpath, dirnames, filenames in os.walk(root):
        for fn in filenames:
            full = opath.join(dirpath, fn)
            if is_match(fn, last):
                # Ensure relative path matches original pattern structure
                rel = opath.relpath(full, ".")
                results.append(rel)

    return sorted(results)


