# Build a mapping of code points where casefold differs from lower,
# excluding the ones that require str.casefold() (like U+00B5).
# For all code points except U+00B5, we can safely use .casefold().
# For U+00B5, we know its casefold is 'μ' (U+03BC), and lower is also 'μ',
# so casefold == lower for U+00B5. We handle it specially.

cf_set = set()
for c in range(0x110000):
    if 0xD800 <= c <= 0xDFFF:
        continue
    if c == 0x00B5:
        # U+00B5 MICRO SIGN: casefold -> U+03BC GREEK SMALL LETTER MU
        # lower -> U+03BC GREEK SMALL LETTER MU
        # So they are equal, skip it
        continue
    ch = chr(c)
    try:
        cf_str = ch.casefold()
    except Exception:
        continue
    lw_str = ch.lower()
    if cf_str != lw_str:
        cf_set.add(c)

ti_set = set()
for c in range(0x110000):
    if 0xD800 <= c <= 0xDFFF:
        continue
    ch = chr(c)
    ti_str = ch.title()
    up_str = ch.upper()
    if ti_str != up_str:
        ti_set.add(c)

rc = ranges(sorted(cf_set))
rt = ranges(sorted(ti_set))

print('casefold ranges:', len(rc)); print('  ', ', '.join("'\\u{%x}'..='\\u{%x}'"%r for r in rc))
print()
print('title ranges:', len(rt)); print('  ', ', '.join("'\\u{%x}'..='\\u{%x}'"%r for r in rt))

