def _glob(pattern):
    """Reproduce glob.glob semantics for this simple pattern using only os.listdir / os.path."""
    # Split into absolute and relative
    if pattern.startswith('/'):
        isabs = True
        rel = pattern[1:]
    else:
        isabs = False
        rel = pattern
    parts = rel.split('/')
    results = []

    def _walk(remaining, prefix):
        if not remaining:
            if prefix and (os.path.isfile(prefix)):
                results.append(prefix)
            return
        cur = remaining[0]
        rest = remaining[1:]
        if cur in ('*', '?', '['):
            try:
                entries = list(os.listdir(prefix))
            except OSError:
                return
            # Use fnmatch-like via regex conversion
            pat = cur.replace('\\', '\\\\').replace('[', '\\[').replace(']', '\\]')
            pat = pat.replace('.', '\\.').replace('*', '.*')
            pat = pat.replace('?', '.')
            rx = re.compile('^' + pat + '$')
            for e in entries:
                if rx.match(e):
                    newprefix = prefix + '/' + e if prefix else e
                    if rest:
                        _walk(rest, newprefix)
                    else:
                        if os.path.isfile(newprefix):
                            results.append(newprefix)
        else:
            newprefix = prefix + '/' + cur if prefix else cur
            _walk(rest, newprefix)

    _walk(parts, '')

    out = []
    base = '' if isabs else '.'
    for r in results:
        full = (base + '/' + r) if base else r
        if isabs:
            out.append(full if full.startswith('/') else '/' + full)
        else:
            out.append(full)
    return sorted(set(out))

