import json

def _find_jsonl():
    home = os.path.expanduser("~")
    projects_dir = os.path.join(home, ".claude", "projects")
    files = []
    try:
        entries1 = os.listdir(projects_dir)
    except Exception:
        return files
    for e1 in sorted(entries1):
        d1 = os.path.join(projects_dir, e1)
        if not os.path.isdir(d1):
            continue
        try:
            entries2 = os.listdir(d1)
        except Exception:
            continue
        for e2 in sorted(entries2):
            f = os.path.join(d1, e2)
            if os.path.isfile(f) and f.endswith(".jsonl"):
                files.append(f)
    return sorted(files)


def main():
    files = _find_jsonl()
    print("transcript files:", len(files))

    c = {}
    persess = {}
    side = {}
    bad = 0

    for f in files:
        try:
            with open(f, errors="replace") as fh:
                for line in fh:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        o = json.loads(line)
                    except Exception:
                        bad += 1
                        continue
                    if o.get("type") != "assistant":
                        continue
                    m = o.get("message")
                    if not isinstance(m, dict):
                        continue
                    mod = m.get("model")
                    if not mod:
                        continue
                    c[mod] = c.get(mod, 0) + 1
                    if f not in persess:
                        persess[f] = set()
                    persess[f].add(mod)
                    if o.get("isSidechain"):
                        side[mod] = side.get(mod, 0) + 1
        except Exception as e:
            print("ERR", f, e)

    print("bad lines:", bad)
    print("=== distinct message.model values, counts ===")
    for k in sorted(c, key=lambda x: (-c[x], x)):
        print("{:8d}  {}".format(c[k], k))

    print("=== sidechain-only counts ===")
    for k in sorted(side, key=lambda x: (-side[x], x)):
        print("{:8d}  {}".format(side[k], k))

    multi = [(f, s) for f, s in persess.items() if len(s) > 1]
    # preserve the original iteration order of files
    multi_sorted = []
    seen_files = set()
    for f in files:
        if f in persess and len(persess[f]) > 1 and f not in seen_files:
            multi_sorted.append((f, persess[f]))
            seen_files.add(f)

    print("=== sessions with >1 distinct model:", len(multi), "of", len(persess))
    for f, s in multi_sorted[:20]:
        print("   ", os.path.basename(f), sorted(s))


