def format_without_n(value, spec):
    if spec and spec[-1] == 'n':
        prefix = spec[:-1]
        try:
            loc = locale.getlocale(locale.LC_ALL)
        except Exception:
            loc = (None, None)
        lang, enc = loc
        use_thousands = True
        if lang is None:
            use_thousands = False
        else:
            lang_parts = lang.split('_')
            code = lang_parts[0].lower()
            # In most locales with a language set, numbers have thousands separator
            use_thousands = True
        if prefix == '' or prefix == '#':
            num_str = str(abs(value))
        else:
            num_str = str(abs(value))

        if use_thousands:
            parts = []
            for i in range(0, len(num_str), 3):
                chunk = num_str[i:i+3]
                if i + 3 < len(num_str):
                    parts.append(chunk + ',')
                else:
                    parts.append(chunk)
            grouped = ''.join(parts)
        else:
            grouped = num_str

        if value < 0:
            result = '-' + grouped
        elif prefix == '#':
            result = '#' + grouped
        elif prefix == '0':
            result = '0' + grouped
        elif prefix in ('+', ' '):
            if prefix == '+':
                result = '+' + grouped
            else:
                result = ' ' + grouped
        elif prefix == '=':
            result = '=' + grouped
        elif prefix == '<':
            result = '<' + grouped
        elif prefix == '^':
            result = '^' + grouped
        elif prefix == '>':
            result = '>' + grouped
        else:
            raise ValueError("Invalid format specification")
        return result
    else:
        return format(value, spec)


