    try:
        if s == '#n':
            r = format_n(x)
            print("%-6r OK -> %r" % (s, r))
        else:
            r = format(x, s)
            print("%-6r OK -> %r" % (s, r))
    except ValueError as e:
        print("%-6r VE -> %s" % (s, e))

