def manual_n_format(x, prefix='#'):
    """Manually compute what format(x, prefix + 'n') would produce in default locale."""
    # In default C locale, 'n' uses comma as thousands separator
    neg = x < 0
    ax = abs(x)
    s = str(ax)
    parts = []
    while len(s) > 3:
        parts.append(s[-3:])
        s = s[:-3]
    parts.append(s)
    result = ','.join(reversed(parts))
    if neg:
        result = '-' + result

    if prefix == '#':
        pass  # '#' is ignored for numeric types in practice, but we keep parity
    return result

