    # Re-implement the core logic of json.dumps from stdlib
    class Encoder:
        def __init__(self, **kwargs):
            self.sep = (', ', ': ')
            if 'separators' in kwargs:
                self.sep = kwargs['separators']
            if 'indent' in kwargs and kwargs['indent'] is not None:
                if isinstance(kwargs['indent'], int):
                    indent = ' ' * kwargs['indent']
                else:
                    indent = kwargs['indent']
                self.indent = indent
                self.itp = indent  # initial tab padding for nested objects
            else:
                self.indent = None
                self.itp = ''

            self.sort_keys = kwargs.get('sort_keys', False)

        def encode(self, o):
            return self._iterencode(o, 0)

        def _iterencode(self, o, level):
            if o is None:
                yield 'null'
            elif o is True:
                yield 'true'
            elif o is False:
                yield 'false'
            elif isinstance(o, str):
                yield self._string_encode(o)
            elif isinstance(o, float):
                if o != o:  # NaN
                    yield 'null'
                elif o == float('inf'):
                    yield '1e999999999'
                elif o == float('-inf'):
                    yield '-1e999999999'
                else:
                    yield repr(o)
            elif isinstance(o, int):
                yield str(o)
            elif isinstance(o, list):
                if not o:
                    yield '[]'
                    return
                yield '['
                first = True
                for item in o:
                    if first:
                        first = False
                    else:
                        yield ','
                        if self.sep[0] != ',' or self.indent:
                            pass
                        if self.indent:
                            yield '\n' + self.indent
                        else:
                            if self.sep[0] == ', ':
                                yield ' '
                    yield from self._iterencode(item, level+1)
                if self.indent:
                    yield '\n'
                yield ']'
            elif isinstance(o, dict):
                if not o:
                    yield '{}'
                    return
                keys = list(o.keys())
                if self.sort_keys:
                    try:
                        keys.sort()
                    except TypeError:
                        pass
                yield '{'
                first = True
                for k in keys:
                    if first:
                        first = False
                    else:
                        yield ','
                        if self.indent:
                            yield '\n' + self.indent
                        else:
                            if self.sep[0] == ', ':
                                yield ' '
                    yield self._string_encode(str(k))
                    if self.indent:
                        yield ': '
                    else:
                        yield self.sep[1]
                    yield from self._iterencode(o[k], level+1)
                if self.indent:
                    yield '\n'
                yield '}'
            else:
                raise TypeError(f"Object of type {type(o).__name__} is not JSON serializable")

        def _string_encode(self, s):
            result = []
            result.append('"')
            for c in s:
                cp = ord(c)
                if cp < 32:
                    escapes = {0x08: '\\b', 0x0c: '\\f', 0x0a: '\\n', 0x0d: '\\r', 0x09: '\\t'}
                    result.append(escapes.get(cp, '\\u%04x' % cp))
                elif c == '"':
                    result.append('\\"')
                elif c == '\\':
                    result.append('\\\\')
                elif cp >= 0xd800 and cp <= 0xdfff:
                    # Surrogate - skip, json doesn't handle raw surrogates well
                    result.append('\\u%04x' % cp)
                else:
                    result.append(c)
            result.append('"')
            return ''.join(result)

