    while spec and spec[0] in '+-# 0z':
        flags += spec[0]
        spec = spec[1:]

    width = ''
    while spec and spec[0].isdigit():
        width += spec[0]
        spec = spec[1:]

    prec = ''
    if spec.startswith('.'):
        spec = spec[1:]
        prec = ''
        while spec and spec[0].isdigit():
            prec += spec[0]
            spec = spec[1:]

