    if not spec:
        raise ValueError("no conversion")
    conv = spec[0]
    rest = spec[1:]
    if rest:
        # Only support 's', 'd' etc as last char; here we have simple cases
        pass

    width_int = int(width) if width else None
    prec_int = int(prec) if prec is not None and prec != '' else None

    # Handle each conversion
