        # Flags like +, #, z are invalid for c
        if any(f in flags for f in '+#z'):
            raise ValueError("invalid format specifier")

        result = ch

        # Apply width with alignment
        if width_int is not None:
            if '-' in flags:
                result = result.ljust(width_int)
            elif ' ' in flags or '0' in flags:
                # For c, space flag left-pads, but 0 flag? Let's check.
                # Actually for %c, 0 is treated like space? Let's verify.
                # In CPython, for %c, 0 flag is equivalent to space flag (left-pad).
                result = result.rjust(width_int, ' ')
            else:
                result = result.rjust(width_int)

        return result

    elif conv == 'd':
        if not isinstance(val, int):
            raise TypeError("%d format: a number is required, got %r" % type(val).__name__)

        # Apply sign
        neg = val < 0
        absval = abs(val)

        s = str(absval)

        # Precision
        if prec_int is not None:
            s = s.zfill(prec_int)

        # Width
        if '+' in flags:
            prefix = '+' if not neg else '-'
        elif ' ' in flags:
            prefix = ' ' if not neg else '-'
        else:
            prefix = '' if not neg else '-'

        result = prefix + s

        # Apply width
        if width_int is not None:
            if '-' in flags:
                result = result.ljust(width_int)
            elif '0' in flags:
                # Zero padding applies before the sign
                total_needed = width_int - len(prefix)
                if total_needed > 0:
                    result = prefix + s.zfill(total_needed)
                else:
                    result = prefix + s[:total_needed] if total_needed >= 0 else s
            else:
                result = result.rjust(width_int)

        # Note: z flag has no effect on d
        return result

    elif conv == 'f':
        if not isinstance(val, float) and not isinstance(val, int):
            raise TypeError("%f format: a number is required, got %r" % type(val).__name__)

        neg = val < 0
        absval = abs(val)

        # Default precision is 6 for %f
        p = prec_int if prec_int is not None else 6

        # Convert to string with specified precision
        s = str(round(absval, p))

