            s = ipart + '.' + dpart
        else:
            s = s + '.' + '0' * p

        # Now apply formatting
        if '+' in flags:
            prefix = '+' if not neg else '-'
        elif ' ' in flags:
            prefix = ' ' if not neg else '-'
        else:
            prefix = '' if not neg else '-'

        result = prefix + s

        if width_int is not None:
            if '-' in flags:
