import os, sys

def glob_jsonl(pattern):
    """Recursively find .jsonl files using os.scandir."""
    results = []
    if not os.path.exists(pattern.rstrip('/') if pattern.endswith('**') else pattern.replace('/**', '')):
        # Check base directory
        base = pattern.replace('/**', '')
        if base.endswith('.jsonl'):
            base = base[:-6]
        if not os.path.isdir(base):
            return results
    base = pattern.replace('/**', '')
    if not os.path.isdir(base):
        return results

    def _walk(d):
        try:
            entries = list(os.scandir(d))
        except (OSError, FileNotFoundError, NotADirectoryError):
            return
        for e in entries:
            try:
                if e.is_dir(follow_symlinks=False):
                    _walk(e.path)
                elif e.name.endswith('.jsonl'):
                    results.append(e.path)
            except Exception:
                pass
    _walk(base)
    return results

