import json,glob,os

# Build a simple Counter class that mimics collections.Counter behavior
class Count:
    def __init__(self):
        self._d = {}
    def __getitem__(self, k):
        return self._d.get(k, 0)
    def __setitem__(self, k, v):
        self._d[k] = v
    def __contains__(self, k):
        return k in self._d
    def update(self, other):
        if isinstance(other, dict):
            for k, v in other.items():
                self._d[k] = self._d.get(k, 0) + v
        else:
            for k in other:
                self._d[k] = self._d.get(k, 0) + 1
    def most_common(self, n=None):
        items = sorted(self._d.items(), key=lambda x: (-x[1], x[0]))
        if n is not None:
            return items[:n]
        return items

def main():
    home = os.path.expanduser('~/.claude/projects')
    files = sorted(glob.glob(os.path.join(home, '**', '*.jsonl'), recursive=True))

    # Compute the depth of home path
    # home is something like /home/user/.claude/projects
    # split gives ['', 'home', 'user', '.claude', 'projects'] -> len = 5
    # A file directly under home would be /home/user/.claude/projects/somefile.jsonl
    # That has 4 slashes (if home starts with / and has 4 parts after empty)
    # Actually, let me just use the same logic as original:
    home_parts = home.split('/')
    expected_slashes = len(home_parts) + 1

    top = [f for f in files if f.count('/') == expected_slashes]

    print("total jsonl:", len(files))

    c = Count()      # all
    ctop = Count()   # main transcript
    csub = Count()   # subagent files

    persess = {}     # dict of filename -> Count

    side = 0

    for f in files:
        sub = '/subagents/' in f

        # Get or create counter for this file
        if f not in persess:
            persess[f] = Count()

        try:
            fh = open(f, errors='replace')
        except Exception:
            continue

        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                o = json.loads(line)
            except Exception:
                continue

            if o.get('type') != 'assistant':
                continue

            m = o.get('message')
            if not isinstance(m, dict):
                continue

            mod = m.get('model')
            if not mod:
                continue

            c[mod] = c[mod] + 1
            if sub:
                csub[mod] = csub[mod] + 1
            else:
                ctop[mod] = ctop[mod] + 1

            persess[f][mod] = persess[f][mod] + 1

            if o.get('isSidechain'):
                side += 1

        fh.close()

    print("=== ALL message.model values ===")
    for k, v in c.most_common():
        print(f"{v:8d}  {k}")

    print("=== main-transcript only ===")
    for k, v in ctop.most_common():
        print(f"{v:8d}  {k}")

    print("=== subagent files only ===")
    for k, v in csub.most_common():
        print(f"{v:8d}  {k}")

    print("isSidechain=true assistant records:", side)

    print("=== per-file model mixes (files with >1) ===")
    expanded_home = os.path.expanduser('~')
    for f in persess:
        cc = persess[f]
        if len(cc._d) > 1:
            display_f = f.replace(expanded_home, '~')
            d = {}
            for k in cc._d:
                d[k] = cc._d[k]
            print(" ", display_f, d)

