def safe_format(value, spec):
    """Emulate format(value, spec) but raise ValueError if the 'n' conversion is requested."""
    if not isinstance(spec, str):
        return format(value, spec)
    # Check for 'n' in the fill/align/type portion (after any width/pad specs)
    # We need to detect when the type specifier is 'n'
    # Format spec grammar: [[fill]align][sign][#][0][width][grouping_option]['.']['precision'][type]
    # We just look for 'n' appearing as a type code. The type code is the last character
    # (or before any trailing chars), but more simply: if 'n' appears anywhere in the spec
    # in a position where it would be interpreted as a type, we refuse.

    # Actually, let's be more precise. We'll try to parse the format spec minimally.
    # If 'n' is used as the type, we raise ValueError.

    s = spec

    # Skip fill and align characters
    i = 0
    if i < len(s) and i + 1 < len(s) and s[i+1] in '<>=^':
        i += 1  # skip fill
    if i < len(s) and s[i] in '<>=^':
        i += 1  # skip align

    # Skip sign
    if i < len(s) and s[i] in '+- ':
        i += 1

    # Skip hash (#) - alternate form
    if i < len(s) and s[i] == '#':
        i += 1

    # Skip zero-padding indicator
    if i < len(s) and s[i] == '0':
        i += 1

    # Skip width digits
    while i < len(s) and s[i].isdigit():
        i += 1

    # Skip grouping option
    if i < len(s) and s[i] in '_,' :
        i += 1

    # Skip precision
    if i < len(s) and s[i] == '.':
        i += 1
        while i < len(s) and s[i].isdigit():
            i += 1

    # Now what remains should be the type code (if any)
    if i < len(s) and s[i] == 'n':
        raise ValueError("cannot convert value to integer")

    return format(value, spec)


