import locale

def format_compat(value, spec):
    """Format a value using the spec, replacing 'n' with locale-aware behavior."""
    if not isinstance(spec, str):
        raise TypeError("format() argument 2 must be str, not %r" % type(spec).__name__)

    # Handle the case where 'n' is present in the format spec
    # 'n' means locale-aware number formatting

    # For integers and floats, we need to use locale formatting
    if spec.endswith('n') or 'n' in spec:
        # Parse the format spec
        # The format spec for 'n' can have fill, align, sign, '#', '0', width, ',' 
        # Actually, for 'n', the valid chars are: fill, align, '+', '-', '#', '0', width, ','
        # But let's just use a simpler approach

        # Check if value is int or float
        if isinstance(value, int) or isinstance(value, float):
            # Use locale-aware formatting
            old_locale = locale.getlocale(locale.LC_NUMERIC)
            try:
                # Set locale to C for consistent behavior (matching what Python does by default)
                # Actually, we need to match the original behavior
                # In Python, 'n' uses the current locale
                # Let's just use the locale module's formatting

                # Parse width and other options from spec
                import re
                m = re.match(r'^([^+\\- ]*)([+#]?)(\d*)(?:[.,])?$', spec)
                if m:
                    fill_align = m.group(1)
                    sign = m.group(2)
                    width_str = m.group(3)
                    width = int(width_str) if width_str else 0

                    if isinstance(value, int):
                        if width > 0:
                            return '%*d' % (width, value)
                        else:
                            return '%d' % value
                    elif isinstance(value, float):
                        # For floats with 'n', use appropriate decimal places
                        if width > 0:
                            return '%*f' % (width, value)
                        else:
                            return '%f' % value
            except Exception:
                pass

            # Fallback: just remove 'n' and add comma handling
            new_spec = spec.replace('n', '')
            if ',' in new_spec:
                # Remove commas since we'll handle them
                new_spec = new_spec.replace(',', '')

            formatted = ''
            if isinstance(value, int):
                formatted = format(value, new_spec if new_spec else '')
            elif isinstance(value, float):
                formatted = format(value, new_spec if new_spec else '')

            # Add comma separators for thousands
            neg = formatted.startswith('-')
            if neg:
                formatted = formatted[1:]

            parts = []
            while len(formatted) > 3:
                parts.insert(0, formatted[-3:])
                formatted = formatted[:-3]
            parts.insert(0, formatted)
            result = ','.join(parts)
            if neg:
                result = '-' + result

            # Apply fill/align from original spec
            # This is complex, so for simplicity, we won't fully support fill/align with 'n'
            return result

        # For non-numeric values, 'n' doesn't make sense
        raise ValueError("Invalid format specifier")

    # If no 'n', just use standard format
    return format(value, spec)

