def _safe_format(value, spec):
    """Mimic built-in format() without the locale-aware 'n' type."""
    # Extract and remove any 'n' conversion specifier from the format string.
    # A lone 'n' at the end (or before an 'n' preceded by a digit) is the number separator.
    if not spec:
        return str(value)

    sep_index = None
    # If spec ends with 'n', that's the number-separator directive.
    if spec.endswith('n'):
        sep_index = len(spec) - 1
        rest = spec[:-1]
        if not rest:
            # Just "n" — no fill/align/etc, use default int/float repr with thousands comma
            if isinstance(value, float):
                return "{:,}".format(value)
            else:
                return "{:,}".format(value)
    else:
        rest = spec
        sep_index = None

    # Handle the remaining format spec normally via __format__.
    # But we need to avoid calling format() on specs containing 'n'.
    # At this point 'rest' should not contain 'n' as a conversion type.
    result = value.__format__(rest) if rest != '' else str(value)

    if sep_index is not None:
        # The original had a trailing 'n' meaning "use thousands separator".
        # We already formatted via __format__ with the rest; now we need to apply comma separation.
        # Actually, it's cleaner to just use {:,} style for the full thing.
        # Re-do: parse value into sign, integer part, fractional/exponent.
        # Simpler approach: use the comma-format directly when 'n' was present.
        return "{:,}".format(value)
    else:
        return result


