# Build the output without importing json
def _json_escape(s):
    result = ['"']
    for ch in s:
        code = ord(ch)
        if ch == '"':
            result.append('\\"')
        elif ch == '\\':
            result.append('\\\\')
        elif code < 32:
            if ch == '\n':
                result.append('\\n')
            elif ch == '\t':
                result.append('\\t')
            elif ch == '\r':
                result.append('\\r')
            elif ch == '\b':
                result.append('\\b')
            elif ch == '\f':
                result.append('\\f')
            else:
                result.append('\\u%04x' % code)
        else:
            result.append(ch)
    result.append('"')
    return ''.join(result)

