def _is_printable(c):
    code = ord(c)
    # Control chars
    if code < 0x20:
        return False
    if code == 0x7f:
        return False
    # CPython specific non-printables often found in general category Cc/Cf/Zl/Zp/etc
    # Specifically U+0085 (NEL) is not considered printable in CPython
    if code == 0x85:
        return False
    # Other common non-printable ranges
    if 0x7f <= code <= 0xa0:
        return False
    if 0xd800 <= code <= 0xdfff:
        return False
    if 0xfeff <= code <= 0xfffe:
        return False
    if 0xfff0 <= code <= 0xffff:
        return False
    return True

def repr_str(s):
    if s is None:
        return 'None'

    needs_single = "'" in s
    needs_double = '"' in s

    if needs_single and not needs_double:
        quote = "'"
    elif needs_double and not needs_single:
        quote = '"'
    else:
        quote = '"'

    out = [quote]
    for c in s:
        code = ord(c)
        if c == quote:
            out.append('\\' + quote)
        elif c == '\\':
            out.append('\\\\')
        elif c == '\n':
            out.append('\\n')
        elif c == '\t':
            out.append('\\t')
        elif c == '\r':
            out.append('\\r')
        elif c == '\v':
            out.append('\\v')
        elif c == '\f':
            out.append('\\f')
        elif c == '\b':
            out.append('\\b')
        elif _is_printable(c):
            out.append(c)
        elif code < 0x100:
            out.append('\\x%02x' % code)
        elif code < 0x10000:
            out.append('\\u%04x' % code)
        else:
            out.append('\\U%08x' % code)
    out.append(quote)
    return ''.join(out)

def repr_bytes(b):
    out = [b'b']
    quote = b'"'
    has_single = b'\'' in b
    has_double = b'"' in b
    if has_single and not has_double:
        quote = b"'"
    elif has_double and not has_single:
        quote = b'"'
    else:
        quote = b'"'

    out.append(quote)
    for byte in b:
        if byte == 92:  # \
            out.append(b'\\\\')
        elif byte == 39:  # '
            if quote == b"'":
                out.append(b"\\'")
            else:
                out.append(b"'")
        elif byte == 34:  # "
            if quote == b'"':
                out.append(b'\\"')
            else:
                out.append(b'"')
        elif byte == 10:  # \n
            out.append(b'\\n')
        elif byte == 9:   # \t
            out.append(b'\\t')
        elif byte == 13:  # \r
            out.append(b'\\r')
        elif byte == 8:   # \b
            out.append(b'\\b')
        elif byte == 11:  # \v
            out.append(b'\\v')
        elif byte == 12:  # \f
            out.append(b'\\f')
        elif 32 <= byte <= 126:
            out.append(bytes([byte]))
        else:
            out.append(b'\\x%02x' % byte)
    out.append(quote)
    return b''.join(out).decode('ascii')

