def unicode_escape_repr(s):
    if s == "":
        return '""'
    if not (s.startswith("'") or s.endswith("\\") or s == "'" or s == '"' or '\n' in s or '\r' in s or "\t" in s or '"\u0085' in s):
        pass
    # Determine if we need double quotes
    use_double = False
    has_single = "'" in s
    has_double = '"' in s
    has_backslash = "\\" in s
    has_newline = "\n" in s or "\r" in s or "\u0085" in s

    if has_newline and has_backslash:
        use_double = True
    elif has_newline:
        # repr prefers single quotes, but if there's a backslash it uses double
        # Actually let me check: repr('\n') is "'\\n'" so single quote
        # repr("\n") is "'\\n'" - wait no
        # Let me think about this differently

    # Actually the simplest approach: use Python's actual repr logic
    # The rule is: if the string contains single quotes, use double; 
    # if it contains both, escape appropriately.
    # But for strings with newlines, repr still uses single quotes normally.

    # Let me just manually construct what repr would do
    # For the specific case of \x85, it should appear as \x85 in the repr

    # Check if all chars are printable ASCII or common whitespace
    def is_printable(c):
        cp = ord(c)
        # Printable range: 0x20-0x7E plus tab(9), newline(10), cr(13)
        if cp == 9 or cp == 10 or cp == 13:
            return True
        if 0x20 <= cp <= 0x7E:
            return True
        return False

    # Build the escaped content
    parts = []
    for c in s:
        cp = ord(c)
        if c == '\\':
            parts.append('\\\\')
        elif c == "\n":
            parts.append('\\n')
        elif c == "\t":
            parts.append('\\t')
        elif c == "\r":
            parts.append('\\r')
        elif c == "\v":
            parts.append('\\v')
        elif c == "\f":
            parts.append('\\f')
        elif cp < 0x20 or cp >= 0x7F:
            if cp < 0x100:
                parts.append('\\x%02x' % cp)
            else:
                # For higher Unicode, repr uses \uXXXX
                parts.append('\\u%04x' % cp)
        else:
            parts.append(c)

    inner = ''.join(parts)

    # Choose delimiter
    if has_single and not has_double:
        return '"' + inner.replace('"', '\\"') + '"'
    elif has_single and has_double:
        # Escape both? No, pick one and escape that one
        # If has single: use double and escape doubles
        return '"' + inner.replace('"', '\\"') + '"'
    else:
        # Use single quotes
        return "'" + inner.replace("'", "\\'") + "'"

