# Build repr of a string manually to avoid repr() on strings containing U+0085
def _repr_str(s):
    if s == "":
        return "''"
    if not s.isprintable():
        # use ascii representation style but ensure proper escaping
        result = ascii(s)  # This escapes non-ascii as \xNN etc., but we need to check if it handles U+0085 properly
        # Actually, let's be safer and build it character by character
    # Let's just build it char by char for safety
    out = []
    use_double = False
    has_single = "'" in s
    has_double = '"' in s
    if has_single and not has_double:
        quote = '"'
    else:
        quote = "'"

    for ch in s:
        cp = ord(ch)
        if ch == "\\":
            out.append("\\\\")
        elif ch == '\n':
            out.append("\\n")
        elif ch == '\r':
            out.append("\\r")
        elif ch == '\t':
            out.append("\\t")
        elif ch == '\v':
            out.append("\\v")
        elif ch == '\f':
            out.append("\\f")
        elif ch == quote:
            out.append("\\" + quote)
        elif ch == '':
            out.append('\\x00')
        elif 0x20 <= cp < 0x7f:
            out.append(ch)
        elif cp == 0x85:
            # U+0085 is NEL. In CPython, repr shows it as escaped \x85
            out.append('\\x85')
        elif 0x7f <= cp <= 0xff:
            out.append('\\x%02x' % cp)
        elif cp < 0x1000:
            out.append('\\u%04x' % cp)
        elif cp < 0x10000:
            out.append('\\U%08x' % cp)
        else:
            out.append('\\U%08x' % cp)

    result = quote + ''.join(out) + quote
    return result


