import sys

def escape_unicode(s):
    out = []
    for ch in s:
        cp = ord(ch)
        if cp == 0x08:
            out.append("\\b")
        elif cp == 0x09:
            out.append("\\t")
        elif cp == 0x0a:
            out.append("\\n")
        elif cp == 0x0c:
            out.append("\\f")
        elif cp == 0x0d:
            out.append("\\r")
        elif cp == 0x1b:
            out.append("\\x1b")
        elif cp == 0x27:
            out.append("'")
        elif cp == 0x5c:
            out.append("\\\\")
        elif cp >= 0x20 and cp < 0x7f:
            out.append(ch)
        elif cp == 0x85:
            out.append("\\x85")
        else:
            # Use the shortest \u or \U escape
            if cp <= 0xffff:
                hexstr = format(cp, "04x")
                out.append("\\u" + hexstr)
            else:
                hexstr = format(cp, "08x")
                out.append("\\U" + hexstr)
    return ''.join(out)

