import sys
import ast
import re
from types import SimpleNamespace as NS


def is_seeded_stream(e):
    """Check if the program seeds the random number generator."""
    try:
        tree = ast.parse(e.program)
    except SyntaxError:
        return False

    # Look for random.seed(...) or assignments like s = random.seed; s(...)
    for node in ast.walk(tree):
        # Direct call: random.seed(args)
        if isinstance(node, ast.Call):
            func = node.func
            if isinstance(func, ast.Attribute):
                if isinstance(func.value, ast.Name) and func.value.id == 'random':
                    if func.attr == 'seed':
                        return True
            # Call through alias: s(args) where s = random.seed
            elif isinstance(func, ast.Name):
                func_name = func.id
                # Check if func_name was assigned from random.seed
                for subnode in ast.walk(tree):
                    if isinstance(subnode, ast.Assign):
                        targets = []
                        if isinstance(subnode.targets, list):
                            targets = subnode.targets
                        else:
                            targets = [subnode.targets]
                        for t in targets:
                            if isinstance(t, ast.Name) and t.id == func_name:
                                val = subnode.value
                                if isinstance(val, ast.Attribute):
                                    if isinstance(val.value, ast.Name) and val.value.id == 'random':
                                        if val.attr == 'seed':
                                            return True
    return False


def is_run_specific(e):
    """Check if the program's output depends on runtime specifics (time, pid, etc.)"""
    try:
        tree = ast.parse(e.program)
    except SyntaxError:
        return False

    for node in ast.walk(tree):
        if isinstance(node, ast.Name):
            name = node.id
            if name in ('time', 'pid', 'os'):
                return True
        if isinstance(node, ast.Attribute):
            attr_path = ''
            current = node
            parts = []
            while isinstance(current, ast.Attribute):
                parts.append(current.attr)
                current = current.value
            if isinstance(current, ast.Name):
                parts.append(current.id)
            attr_path = '.'.join(reversed(parts))
            if attr_path in ('time.time', 'time.monotonic', 'time.process_time', 
                           'os.getpid', 'os.times'):
                return True
    return False


def is_nondeterministic(e):
    """Check if the program uses unseeded randomness or other nondeterministic sources."""
    try:
        tree = ast.parse(e.program)
    except SyntaxError:
        return False

    # If it uses random but doesn't seed it, it's nondeterministic
    uses_random = False
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                if alias.name == 'random' or alias.name.startswith('random.'):
                    uses_random = True
                    break
        elif isinstance(node, ast.ImportFrom):
            if node.module == 'random':
                uses_random = True
                break
        elif isinstance(node, ast.Attribute):
            if isinstance(node.value, ast.Name) and node.value.id == 'random':
                uses_random = True
                break

    if not uses_random:
        return False

    # If seeded, not nondeterministic (assuming seed makes it deterministic)
    if is_seeded_stream(e):
        return False

    return True


