import re


def is_seeded_stream(e):
    p = e.program
    # Check if random.seed is called
    return bool(re.search(r'random\.seed\(', p))


def is_run_specific(e):
    p = e.program
    # Check for time-dependent or OS-specific calls
    if 'time()' in p or 'time.time' in p:
        return True
    if '__import__(' in p:
        return True
    if 'os.urandom' in p:
        return True
    return False


def is_nondeterministic(e):
    p = e.program
    # If it uses random but no seed, it's nondeterministic
    if re.search(r'random\.(random|randint|choice|shuffle|sample)\(', p):
        if not re.search(r'random\.seed\(', p):
            return True
    if 'os.urandom' in p:
        return True
    return False


