import os, sys

# Find huggingface_hub package directory without inspect or direct import of the package
def find_module_dir():
    # First try to find it via sys.path by scanning path entries
    for entry in sys.path:
        if not entry:
            continue
        candidate = os.path.join(entry, 'huggingface_hub')
