    """Parse a format spec. Returns (type_char, fill, align, sign, alt, width, prec)."""
    fill = ''
    align = ''
    sign = ''
    alt = ''
    width = None
    prec = None
    type_char = ''

    i = 0
    n = len(s)

    # Check for fill and align
    if n >= 2 and s[1] in '=<>' :
        fill = s[0]
        align = s[1]
        i = 2
    elif n >= 1 and s[0] in '=<>':
        align = s[0]
        i = 1

    # Sign
    if i < n and s[i] in '+-':
        sign = s[i]
        i += 1

    # Alt
    if i < n and s[i] == '#':
        alt = s[i]
        i += 1

    # Width
    width_str = ''
    while i < n and s[i].isdigit():
        width_str += s[i]
        i += 1
