        width = int(width_str)

    # Precision
    if i < n and s[i] == '.':
        i += 1
        prec_str = ''
        while i < n and s[i].isdigit():
            prec_str += s[i]
            i += 1
        if prec_str:
            prec = int(prec_str)
        else:
            prec = None

    # Type
    if i < n:
        type_char = s[i]

    return type_char, fill, align, sign, alt, width, prec


