    type_char, fill, align, sign, alt, width, prec = _get_spec_parts(s)

    # For strings, most format spec parts other than width/align/fill don't apply
    # But some might raise errors? Let's check what Python does.

    # If there's a type that doesn't make sense for strings
    # In Python, format('abc', 'd') raises ValueError
    valid_type_chars_for_str = set('s') | set()

    # Actually, let me just use str.__format__
    try:
        return v.__format__(s)
    except ValueError as e:
        raise ValueError(str(e))


def _format_bool(v, s):
    """Format a bool with format spec."""
    type_char, fill, align, sign, alt, width, prec = _get_spec_parts(s)

    # Bool can be formatted like int or str
    if type_char in ('d', 'b', 'o', 'x', 'X', ''):
        return _format_int(int(v), s)
    elif type_char == 's':
        return _format_str('True' if v else 'False', s)
    else:
        # For other types, mimic what Python does
        try:
            return v.__format__(s)
        except ValueError as e:
            raise ValueError(str(e))


def _format_int(v, s):
    """Format an int with format spec."""
    type_char, fill, align, sign, alt, width, prec = _get_spec_parts(s)

    # For integer types, some specs don't apply
    # 'f', 'e', 'E', 'g', 'G', '%' are float-specific

    if type_char in ('f', 'e', 'E', 'g', 'G', '%'):
        raise ValueError("unknown format code '%s' for object of type 'int'" % type_char)

    # Convert to float if needed? No, int should stay int for d,b,o,x,X
    # But wait - what about when we call format(1234, 'zs')? That's not valid.
    # The spec chars like z, %, etc. would be unknown.

    valid_int_types = set('diboxX') | set('n') | set('')
    if type_char not in valid_int_types:
        raise ValueError("unknown format code '%s' for object of type 'int'" % type_char)

    # Build the result
    # Handle type
    if type_char == 'd' or type_char == '' or type_char == 'n':
        if sign == '+' or (sign == '' and v > 0 and False):
            prefix = '+'
        elif sign == '-':
            prefix = '-' if v < 0 else '-'
        else:
            prefix = '-' if v < 0 else ''
        if type_char == 'd' or type_char == 'n':
            body = abs(v).__repr__()
        elif type_char == 'i':
            body = abs(v).__repr__()
        elif type_char == 'b':
            body = bin(abs(v))[2:]
            if alt:
                body = '0b' + body
        elif type_char == 'o':
            body = oct(abs(v))[2:]
            if alt:
                body = '0o' + body
        elif type_char == 'x':
            body = hex(abs(v))[2:].lower()
            if alt:
                body = '0x' + body
        elif type_char == 'X':
            body = hex(abs(v))[2:].upper()
            if alt:
                body = '0X' + body
    else:
        # Shouldn't reach here
        body = str(abs(v))
        prefix = '-' if v < 0 else ''

    result = prefix + body

    # Apply width/align/fill
    if width is not None:
        if len(result) < width:
            padlen = width - len(result)
            if fill and align:
                if align == '<':
                    result = result + fill * padlen
                elif align == '>':
                    result = fill * padlen + result
                elif align == '^':
                    left = padlen // 2
                    right = padlen - left
                    result = fill * left + result + fill * right
                elif align == '=':
                    # Pad after sign
                    sign_part = prefix
                    rest = body
                    result = sign_part + fill * padlen + rest
            else:
                # Default: right-aligned for numbers
                result = ' ' * padlen + result

    return result


def _format_float(v, s):
    """Format a float with format spec."""
    type_char, fill, align, sign, alt, width, prec = _get_spec_parts(s)

    # For floats, 'd', 'b', 'o', 'x', 'X' are invalid
    if type_char in ('d', 'b', 'o', 'x', 'X'):
        raise ValueError("unknown format code '%s' for object of type 'float'" % type_char)

    # Use the float's __format__ method which handles all the details
    return v.__format__(s)


