        trans = bytes.maketrans(b'-_', b'+/')
        data = data.translate(trans)

    # Check for valid encoding
    n = 0
    pads = 0
    for c in data:
        if c in IDX:
            n += 1
            pads = 0
        elif c == 0x3d:
            pads += 1

    rem = n % 4
    if rem == 1 or (rem != 0 and pads < 4 - rem):
        raise Exception("Invalid base64")

    acc = 0
    bits = 0
    out = bytearray()
    for c in data:
        if c not in IDX:
            continue
        acc = (acc << 6) | IDX[c]
        bits += 6
        if bits >= 8:
            bits -= 8
            out.append((acc >> bits) & 0xFF)

    return bytes(out)

